  ui_story_5089_50890100_105_dialog_content = "呵呵，我這就回宮做最後的準備。PlayerName公子，明日再見。",
  ui_story_5089_50890100_106_dialog_content = "我也該收拾一下行李了。",
  ui_story_5089_50890100_107_dialog_content = "要走了嗎？",
  ui_story_5089_50890100_108_dialog_content = "嗚哇！阿霓妳又是什麼時候來的？",
  ui_story_5089_50890100_109_dialog_content = "從小PlayerName想叫阿霓幫忙，用神通掩蓋行蹤開始～",
