  ui_story_5089_50890100_115_dialog_content = "有什麼關係嘛，反正神明啊菩薩啊什麼的，每過一段時間在人們口中的傳說都會變一變。",
  ui_story_5089_50890100_116_dialog_content = "決定了，之後就找個武館去學打拳。",
  ui_story_5089_50890100_117_dialog_content = "好好好，但到時候可要記得收點力，我不能看著妳，但也要注意別太亂來哦。",
