  ui_story_5089_50890100_130_dialog_content = "也該去跟其他人告別才行。",
  ui_story_5089_50890100_131_dialog_content = "<color=#e8d9bb>翌日。</color>",
  ui_story_5089_50890100_132_dialog_content = "和丹棠約好的地方，是在這裡吧。",
  ui_story_5089_50890100_133_dialog_content = "PlayerName！PlayerName！你終於來了，我都等了好久啦。",
