  ui_story_5089_50890100_136_dialog_content = "都是我精心挑選的寶貝喲。",
  ui_story_5089_50890100_137_dialog_content = "看，這是我小時候幾乎不離身的布偶；這是我過節時親手做的花燈。",
  ui_story_5089_50890100_138_dialog_content = "還有我最喜歡的話本子——夫子不讓我看，我託了好多人才買到的！",
  ui_story_5089_50890100_139_dialog_content = "還有、還有……丹棠和國師都跟我說過了。",
