  ui_story_5089_50890100_144_dialog_content = "太好了！",
  ui_story_5089_50890100_145_dialog_content = "來人，把剩下的也都抬上來。",
  ui_story_5089_50890100_146_dialog_content = "等等……那堆成山的箱子是怎麼回事？！",
  ui_story_5089_50890100_147_dialog_content = "無趣的添頭而已。因為時間太緊，只有這一箱禮物是我親手挑選的。",
  ui_story_5089_50890100_148_dialog_content = "但請你相信，我的誠意是真的！",
