  ui_story_5089_50890100_150_dialog_content = "竟然連結婚之前，必須要先「追求」你都不知道。",
  ui_story_5089_50890100_151_dialog_content = "……咦？",
  ui_story_5089_50890100_152_dialog_content = "起錨——",
  ui_story_5089_50890100_153_dialog_content = "開船囉——",
  ui_story_5089_50890100_154_dialog_content = "<color=#e8d9bb>船隻緩緩離岸，只留下世子還在岸上揮手高呼。</color>",
  ui_story_5089_50890100_155_dialog_content = "我還會繼續送禮物追求你的，直到你答應做我未婚妻為止——！",
  ui_story_5089_50890100_156_dialog_content = "……",
  ui_story_5089_50890100_157_dialog_content = "離開皓津果然是正確的選擇！",
  ui_story_5089_50890100_158_dialog_content = "沒想到世子這麼喜歡PlayerName公子，我還從未見過他對一件事如此上心呢。",
  ui_story_5089_50890100_159_dialog_content = "但這麼多禮物，就算全是玩具我也不能收啊……",
  ui_story_5089_50890100_160_dialog_content = "PlayerName公子若是執意不願收，等到了鄴國，再著人退回便是。",
  ui_story_5089_50890100_161_dialog_content = "也只能這樣了，現在還是救璇極要緊。",
  ui_story_5089_50890100_162_dialog_content = "那麼走吧，去……不。",
  ui_story_5089_50890100_163_dialog_content = "回鄴國。",
  ui_story_5089_50890201_1_dialog_content = "PlayerName閣下、丹棠殿下，請準備下船。",
  ui_story_5089_50890201_2_dialog_content = "不是才剛經過濟鄴交界沒多久嗎，這麼快就到了？",
  ui_story_5089_50890201_3_dialog_content = "尚未，只是鄴國地處中原，不如濟國水系豐沛，水路只能走到這裡。",
  ui_story_5089_50890201_4_dialog_content = "我記得這裡的碼頭……是銅犁鎮吧。",
  ui_story_5089_50890201_5_dialog_content = "是，我已在鎮上訂好了客棧，需得在此歇息一晚。",
  ui_story_5089_50890201_6_dialog_content = "等明日置辦了馬車，再走陸路往都城去。",
  ui_story_5089_50890201_7_dialog_content = "我們明明還在水上，阿玖竟然能做這麼多事？",
  ui_story_5089_50890201_8_dialog_content = "船上有小舟，我借用了一艘提前划去了岸上。",
  ui_story_5089_50890201_9_dialog_content = "畢竟此行倉促，無人迎接。",
  ui_story_5089_50890201_10_dialog_content = "不得不使殿下屈尊於簡陋小店已是有罪，所以更得確保周圍環境的安全。",
  ui_story_5089_50890201_11_dialog_content = "說是快到了，但現在也還完全看不到陸地。",
  ui_story_5089_50890201_12_dialog_content = "妳竟然就靠自己划船往返，難怪衣擺都濕透了。",
  ui_story_5089_50890201_13_dialog_content = "快點去換衣服吧，這樣下去會感冒的。",
  ui_story_5089_50890201_14_dialog_content = "無妨。我自小習武，身體還算強健。",
  ui_story_5089_50890201_15_dialog_content = "此前上岸是為探路，但為自身瑣事離開殿下身側就是失職。",
  ui_story_5089_50890201_16_dialog_content = "不過在殿下面前儀態不整也確實不該，我這就隱去暗處。",
  ui_story_5089_50890201_17_dialog_content = "等等，我不是那個意思——",
  ui_story_5089_50890201_18_dialog_content = "算了，PlayerName公子，由她去吧。",
  ui_story_5089_50890201_19_dialog_content = "這都是最近阿玖出來露面時間最長的一次了。",
  ui_story_5089_50890201_20_dialog_content = "就連在宮裡，都常只是低頭整理一下書信，再抬頭，就看見茶已換好，點心齊備。",
  ui_story_5089_50890201_21_dialog_content = "不過出門與人說一兩句話，再回房就會看到一切都變得乾淨整潔。",
  ui_story_5089_50890201_22_dialog_content = "這期間她做的事甚至比她原本慣做得都多，卻偏偏怎麼都見不到人。",
  ui_story_5089_50890201_23_dialog_content = "（田、田螺姑娘？）",
  ui_story_5089_50890201_24_dialog_content = "妳們之間究竟發生什麼事了？",
  ui_story_5089_50890201_25_dialog_content = "……PlayerName公子，可還記得之前在皓津作亂的那群人？",
  ui_story_5089_50890201_26_dialog_content = "那些自稱「駿命」的傢伙？",
  ui_story_5089_50890201_27_dialog_content = "多虧善女龍王大人相助，巡檢司一舉逮捕了大批潛藏於濟國的駿命者。",
  ui_story_5089_50890201_28_dialog_content = "其中在濟國朝內擔任官職的，就有數十人至多。",
  ui_story_5089_50890201_29_dialog_content = "儘管都是不重要的小官閒職，但假以時日，等這些暗處的人聯結成網……",
  ui_story_5089_50890201_30_dialog_content = "這種可從各方面對大王，對朝廷施加影響的勢力，說一句能動搖國本也不為過。",
  ui_story_5089_50890201_31_dialog_content = "幸好這次把他們都抓起來了，而且濟王他們也都有所防範，不會再讓他們為所欲為了吧。",
  ui_story_5089_50890201_32_dialog_content = "但PlayerName公子，這般的組織，真的會只侷限於濟國嗎？",
  ui_story_5089_50890201_33_dialog_content = "妳的意思是……",
  ui_story_5089_50890201_34_dialog_content = "皓津動亂那夜，我去尋你，卻剛出宮門就遭人攔截。",
  ui_story_5089_50890201_35_dialog_content = "我還是第一次聽說！妳沒受傷吧？為什麼不告訴大家？",
  ui_story_5089_50890201_36_dialog_content = "因為攔截我的，是鄴國的暗探。",
  ui_story_5089_50890201_37_dialog_content = "啊？！",
  ui_story_5089_50890201_38_dialog_content = "當今兆國皇帝年幼，八大諸侯各懷心思。",
  ui_story_5089_50890201_39_dialog_content = "彼此安插暗探間諜雖是心照不宣，卻也不是能言之於口的事。",
  ui_story_5089_50890201_40_dialog_content = "而鄴國的暗探敬我是郡主，實際卻只聽命於叔父本人。",
  ui_story_5089_50890201_41_dialog_content = "那麼他們攔截於我，相助於駿命之事……",
  ui_story_5089_50890201_42_dialog_content = "也只能是鄴王在背後授意？",
  ui_story_5089_50890201_43_dialog_content = "……叔父他，雖然以前聲名不顯，但繼位後任官以才，憂民以仁，有明君之風。",
  ui_story_5089_50890201_44_dialog_content = "此番所為定是被駿命在下蒙蔽！",
  ui_story_5089_50890201_45_dialog_content = "我明白了，難怪妳要這麼匆忙動身。",
  ui_story_5089_50890201_46_dialog_content = "是為了避開鄴國駿命者的耳目，爭取行動自由，找機會讓鄴王知道真相對吧。",
  ui_story_5089_50890201_47_dialog_content = "也能順理成章救出為了幫我們而入獄的璇極！",
  ui_story_5089_50890201_48_dialog_content = "知我者，PlayerName公子也。",
  ui_story_5089_50890201_49_dialog_content = "不過這些事，和阿玖有什麼關係？",
  ui_story_5089_50890201_50_dialog_content = "PlayerName公子不知道嗎？",
  ui_story_5089_50890201_51_dialog_content = "阿玖她，正是鄴國暗探的首領。",
  ui_story_5089_50890201_52_dialog_content = "但……她不是丹棠的護衛嗎？",
  ui_story_5089_50890201_53_dialog_content = "阿玖原是叔父麾下的親信，在我赴濟國為質前，才指派給我作為護衛。",
  ui_story_5089_50890201_54_dialog_content = "叔父對她有大恩，她不會違背叔父的任何命令。",
  ui_story_5089_50890201_55_dialog_content = "所以叔父叫她護我周全，她就願為此豁出性命。",
  ui_story_5089_50890201_56_dialog_content = "叔父說擔憂我的安危，叫她每月寫信報告近況，她便無論寒暑，從不逾期。",
  ui_story_5089_50890201_57_dialog_content = "這是……",
  ui_story_5089_50890201_58_dialog_content = "嗯，我理解叔父的關心，但換一種角度，說是監視亦未嘗不可。",
  ui_story_5089_50890201_59_dialog_content = "等等，那我們現在的行動不是依舊在駿命的掌握中？！阿玖她……",
  ui_story_5089_50890201_60_dialog_content = "……她沒有。",
  ui_story_5089_50890201_61_dialog_content = "PlayerName公子也看得出來吧，阿玖實在不是什麼靈活的傢伙。",
  ui_story_5089_50890201_62_dialog_content = "她不會違背叔父的命令，卻也知道我們此行的意義，所以她只能不看，不聽，不問。",
  ui_story_5089_50890201_63_dialog_content = "只完成最低限度的護衛職責，主動將自己從我身邊調開，便可以不用報告自己也不知道的事。",
  ui_story_5089_50890201_64_dialog_content = "這已經是她所能做到的最大的努力了。",
  ui_story_5089_50890201_65_dialog_content = "而且，能看到那個頑固的阿玖動搖，我其實有些欣喜。",
  ui_story_5089_50890201_66_dialog_content = "至少我們一起在濟國的這五年，不算虛度。",
  ui_story_5089_50890201_67_dialog_content = "丹棠。",
  ui_story_5089_50890201_68_dialog_content = "怎麼，PlayerName公子覺得我幸災樂禍？",
  ui_story_5089_50890201_69_dialog_content = "妳在濟國這些年，是不是過得很辛苦？",
  ui_story_5089_50890201_70_dialog_content = "……哎？",
  ui_story_5089_50890201_71_dialog_content = "啊，那個……我的意思是……",
  ui_story_5089_50890201_72_dialog_content = "我知道濟王、世子跟國師他們都是好人，但畢竟，不是家啊。",
  ui_story_5089_50890201_73_dialog_content = "唉……",
  ui_story_5089_50890201_74_dialog_content = "為、為什麼嘆氣？我說錯什麼了嗎？",
  ui_story_5089_50890201_75_dialog_content = "PlayerName公子若是領兵打仗，必是個善用奇襲的謀將。",
  ui_story_5089_50890201_76_dialog_content = "咦？突然跳到這種話題？",
  ui_story_5089_50890201_77_dialog_content = "暫且失陪，既要下船上岸，我得先去補個妝才行。",
  ui_story_5089_50890201_78_dialog_content = "喔，好……",
  ui_story_5089_50890201_79_dialog_content = "唉。",
  ui_story_5089_50890201_80_dialog_content = "唉。",
  ui_story_5089_50890201_81_dialog_content = "朽木不可雕。",
  ui_story_5089_50890201_82_dialog_content = "鐵樹不開花。",
  ui_story_5089_50890201_83_dialog_content = "「朽木」難道是在說我？等等……多言多語？你們怎麼在這？",
  ui_story_5089_50890201_84_dialog_content = "給點金瓜，指點迷津！",
  ui_story_5089_50890201_85_dialog_content = "送點銀棗，答疑解惑！",
  ui_story_5089_50890201_86_dialog_content = "很遺憾，我沒有金瓜也沒有銀棗。",
  ui_story_5089_50890201_87_dialog_content = "肚子餓了就該去找你們的主人。李天閑也在這吧？我早就習慣他這樣神出鬼沒了。",
  ui_story_5089_50890201_88_dialog_content = "李天閑，你在吧？",
  ui_story_5089_50890201_89_dialog_content = "沒有主人了。",
  ui_story_5089_50890201_90_dialog_content = "沉進水底了。",
  ui_story_5089_50890201_91_dialog_content = "就在那！",
  ui_story_5089_50890201_92_dialog_content = "什麼？！",
  ui_story_5089_50890201_93_dialog_content = "咕嚕嚕……救……在下……不會游……咕嚕嚕嚕……",
  ui_story_5089_50890201_94_dialog_content = "為什麼李天閑會在水裡？不對……",
  ui_story_5089_50890201_95_dialog_content = "救人啊！",
  ui_story_5089_50890202_1_dialog_content = "哈啾！",
  ui_story_5089_50890202_2_dialog_content = "唉，可算是活過來了。",
  ui_story_5089_50890202_3_dialog_content = "你怎麼會在這種地方溺水？別告訴我又是龍宮請你做客。",
  ui_story_5089_50890202_4_dialog_content = "說來話……倒也不長。",
  ui_story_5089_50890202_5_dialog_content = "在下在濟國逛膩了，就想去別處看看，但您也知道，在下囊中羞澀。",
  ui_story_5089_50890202_6_dialog_content = "坐不起大船，只能蹭些商隊的順風車走走停停，可算是到了鄴國。",
  ui_story_5089_50890202_7_dialog_content = "但您猜怎麼著？在野外趕路的時候，竟然遇見暗鬼了！",
  ui_story_5089_50890202_8_dialog_content = "這可稀奇，朝廷的鎮邪大儀年年都辦，這濟鄴交界又不沿海。",
  ui_story_5089_50890202_9_dialog_content = "怕是哪座山裡藏著的暗鬼餓壞了，想出來找點吃的，偏在下倒楣碰上了。",
  ui_story_5089_50890202_10_dialog_content = "這不，被追著追著，一不留神，就掉進水裡去了。",
  ui_story_5089_50890202_11_dialog_content = "多虧了您幾位，這救命之恩不得不報，可在下又身無長物……",
  ui_story_5089_50890202_12_dialog_content = "看來只能以身相許了。",
  ui_story_5089_50890202_13_dialog_content = "不需要！",
  ui_story_5089_50890202_14_dialog_content = "你就沒別的事情好做嗎？",
  ui_story_5089_50890202_15_dialog_content = "您可還記得在下的名字？",
  ui_story_5089_50890202_16_dialog_content = "難道不是李天閑？",
  ui_story_5089_50890202_17_dialog_content = "沒錯，正是「天下第一大閑人」之意啊。",
  ui_story_5089_50890202_18_dialog_content = "您也別急著拒絕，在下臨行前為自己算過一卦，說此行雖有水禍，卻能得多金之人相助。",
  ui_story_5089_50890202_19_dialog_content = "但這多金之人呢……來，勞煩您伸個手。",
  ui_story_5089_50890202_20_dialog_content = "這樣？",
  ui_story_5089_50890202_21_dialog_content = "<color=#e8d9bb>嘩啦。</color>",
  ui_story_5089_50890202_22_dialog_content = "呃……為什麼要把卦籤往我手上倒？",
  ui_story_5089_50890202_23_dialog_content = "哎呀呀，不得了不得了，竟是陰龍陰鼠卦。",
  ui_story_5089_50890202_24_dialog_content = "這龍騰鼠躍本是大吉，偏偏二者皆陰，乃是真龍既隱，小人作祟，將有大災殃之兆啊。",
  ui_story_5089_50890202_25_dialog_content = "按說見了這卦，在下該是腳底抹油躲得越遠越好，但誰讓救命之恩未報呢？",
  ui_story_5089_50890202_26_dialog_content = "罷，罷，在下今兒就捨命陪君子，跟您一道，幫著擋一擋這災殃了。",
  ui_story_5089_50890202_27_dialog_content = "我總覺得不光你說的話，就連這所謂的救命之恩都很可疑。",
  ui_story_5089_50890202_28_dialog_content = "瞧您說的，在下不是您親手救起來的嗎？",
  ui_story_5089_50890202_29_dialog_content = "但你說自己會被「多金之人」所救。",
  ui_story_5089_50890202_30_dialog_content = "不是我吹牛，我這輩子還沒體驗過有錢是什麼感覺呢！",
  ui_story_5089_50890202_31_dialog_content = "這就怪了，卦象顯示，您現在應當富可敵國才是。",
  ui_story_5089_50890202_32_dialog_content = "只有夢裡才會有這種好事吧。",
  ui_story_5089_50890202_33_dialog_content = "PlayerName閣下，船已靠岸，請下船。行李稍後有船伕來搬。",
  ui_story_5089_50890202_34_dialog_content = "既然說了要報恩，這種事在下自然也得也來搭把手，這一箱就交給在下來抬——",
  ui_story_5089_50890202_35_dialog_content = "哎喲，怎麼這麼重，嘶……",
  ui_story_5089_50890202_36_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_5089_50890202_37_dialog_content = "<color=#e8d9bb>箱子重重落下，蓋子也隨之鬆動，意外掀開，露出一片幾乎要刺傷人眼的金黃。</color>",
  ui_story_5089_50890202_38_dialog_content = "PlayerName公子，下船的準備——",
  ui_story_5089_50890202_39_dialog_content = "……",
  ui_story_5089_50890202_40_dialog_content = "……",
  ui_story_5089_50890202_41_dialog_content = "……",
  ui_story_5089_50890202_42_dialog_content = "沒摔壞吧！哎呀，哎呀，這要磕破了一點，賣了在下可都賠不起啊！",
  ui_story_5089_50890202_43_dialog_content = "丹棠、李天閑……那個，我的眼睛好像出問題了。",
  ui_story_5089_50890202_44_dialog_content = "世子送我的箱子裡，怎麼好像裝著一大堆黃金呢？啊哈哈哈……",
  ui_story_5089_50890202_45_dialog_content = "……阿玖。",
  ui_story_5089_50890202_46_dialog_content = "<color=#e8d9bb>玖應聲而出，不待多說，已飛快將所有箱子檢查了一遍。</color>",
  ui_story_5089_50890202_47_dialog_content = "回稟殿下，已查驗完畢，除了兩箱玩具，和幾匣翡翠珠玉外，全是黃金。",
  ui_story_5089_50890301_1_dialog_content = "走了半天，怎麼還沒到？客棧距離碼頭有這麼遠嗎……",
  ui_story_5089_50890301_2_dialog_content = "這不是您剛迎了財神爺進門——富起來了，害怕遭人搶劫，才非要走小路嘛。",
  ui_story_5089_50890301_3_dialog_content = "因為必須還回去啊，而且任誰突然發現自己帶著一堆黃金都會這樣的！",
  ui_story_5089_50890301_4_dialog_content = "明明世子說箱子裡都是些「無趣的添頭」……",
  ui_story_5089_50890301_5_dialog_content = "對於濟國的世子來說，金銀錢財或許真是最無趣的東西了。",
  ui_story_5089_50890301_6_dialog_content = "但對於其他人嘛……至少在鄴國，PlayerName公子拿著這些金子，便是想買一座城都輕輕鬆鬆。",
  ui_story_5089_50890301_7_dialog_content = "不過無須擔心，有阿玖在，尋常盜匪還靠近不了我們。",
  ui_story_5089_50890301_8_dialog_content = "客棧到了，街道盡頭便是。",
  ui_story_5089_50890301_9_dialog_content = "總算可以休息了，這一段路真是走得提心吊膽……丹棠，妳怎麼了？",
  ui_story_5089_50890301_10_dialog_content = "無事，只是想起當年去往濟國時，也曾途徑此地。",
  ui_story_5089_50890301_11_dialog_content = "銅犁鎮毗鄰鄴國最大的糧產地之一，又有碼頭，比不得大城，可也算熱鬧。",
  ui_story_5089_50890301_12_dialog_content = "今日故地重遊，卻總覺得有幾分冷清。",
  ui_story_5089_50890301_13_dialog_content = "姑娘有年頭沒來了吧。",
  ui_story_5089_50890301_14_dialog_content = "還請老伯賜教。",
  ui_story_5089_50890301_15_dialog_content = "賜教什麼，人人都知道的事。",
  ui_story_5089_50890301_16_dialog_content = "這幾年城裡頭建了不少大工坊，給的月錢豐厚，年輕人就都出去做工了。",
  ui_story_5089_50890301_17_dialog_content = "也就是小老兒年紀大了，不然也想去那風吹不著雨曬不著的工坊裡賺錢哪。",
  ui_story_5089_50890301_18_dialog_content = "原來如此，對了老伯，您這米要價幾何呀？",
  ui_story_5089_50890301_19_dialog_content = "小姐要買？這兩個月糧價倒是一直在漲，今天又多了點，這個價——",
  ui_story_5089_50890301_20_dialog_content = "……好，多謝老伯。",
  ui_story_5089_50890301_21_dialog_content = "那袋米有什麼不對嗎？",
  ui_story_5089_50890301_22_dialog_content = "我之前出於好奇也在皓津問過米價，和老伯說的差不多，沒什麼問題吧。",
  ui_story_5089_50890301_23_dialog_content = "這種小鎮的米價，竟與繁華程度在整個大兆都數一數二的皓津相差不多。",
  ui_story_5089_50890301_24_dialog_content = "已經是最大的問題了。只是，為何……",
  ui_story_5089_50890301_25_dialog_content = "<color=#e8d9bb>砰。</color>",
  ui_story_5089_50890301_26_dialog_content = "抱歉，撞到你了，沒事吧……咦？你懷裡抱著的是……",
  ui_story_5089_50890301_27_dialog_content = "……！",
  ui_story_5089_50890301_28_dialog_content = "客官！快……快攔住那小子！",
  ui_story_5089_50890301_29_dialog_content = "他偷了您的行李！",
  ui_story_5089_50890301_30_dialog_content = "！",
  ui_story_5089_50890301_31_dialog_content = "——！",
  ui_story_5089_50890301_32_dialog_content = "抓住了。",
  ui_story_5089_50890301_33_dialog_content = "放開我！快點……放開！啊嗚！",
  ui_story_5089_50890301_34_dialog_content = "<color=#e8d9bb>小男孩猛地咬上了阿玖鉗住他的手，後者卻不為所動，連表情都絲毫未變。</color>",
  ui_story_5089_50890301_35_dialog_content = "東西還來。",
  ui_story_5089_50890301_36_dialog_content = "<color=#e8d9bb>男孩紅著眼，咬得更深。</color>",
  ui_story_5089_50890301_37_dialog_content = "阿玖！",
  ui_story_5089_50890301_38_dialog_content = "<color=#e8d9bb>意識只移開了一瞬，男孩已游魚般逃脫。</color>",
  ui_story_5089_50890301_39_dialog_content = "略！",
  ui_story_5089_50890301_40_dialog_content = "喂，你——",
  ui_story_5089_50890301_41_dialog_content = "來人啊！救命啊！有人販子要抓小孩啦！",
  ui_story_5089_50890301_42_dialog_content = "誰？光天化日敢搶孩子！",
  ui_story_5089_50890301_43_dialog_content = "那邊那群穿得奇奇怪怪的，一看就不像好人！",
  ui_story_5089_50890301_44_dialog_content = "抓起來！報官！",
  ui_story_5089_50890301_45_dialog_content = "這是怎麼了，別急，別急啊，都是自己人，咱們有話好好說。",
  ui_story_5089_50890301_46_dialog_content = "誰跟你是自己人！",
  ui_story_5089_50890301_47_dialog_content = "糟糕，人太多，要讓他跑了。",
  ui_story_5089_50890301_48_dialog_content = "從殿下身邊退開！",
  ui_story_5089_50890301_49_dialog_content = "阿玖，沒事的，他們都是普通百姓。",
  ui_story_5089_50890301_50_dialog_content = "但萬一……",
  ui_story_5089_50890301_51_dialog_content = "妳身手快，帶著PlayerName公子去找人，這裡交給我來解決。",
  ui_story_5089_50890301_52_dialog_content = "不行，我得保護殿下。",
  ui_story_5089_50890301_53_dialog_content = "這是命令。",
  ui_story_5089_50890301_54_dialog_content = "……是。",
  ui_story_5089_50890301_55_dialog_content = "PlayerName閣下，請跟緊我。",
  ui_story_5089_50890301_56_dialog_content = "那孩子怎麼一眨眼就不見了。",
  ui_story_5089_50890301_57_dialog_content = "唉，從看到那堆金子開始我就隱約覺得會發生這種事。",
  ui_story_5089_50890301_58_dialog_content = "雖然動手的是個孩子，有點出人意料。",
  ui_story_5089_50890301_59_dialog_content = "不過那孩子穿的破破爛爛的，一定有什麼苦衷吧。",
  ui_story_5089_50890301_60_dialog_content = "……",
  ui_story_5089_50890301_61_dialog_content = "不是必要，妳也不打算和我說話了嗎？",
  ui_story_5089_50890301_62_dialog_content = "……",
  ui_story_5089_50890301_63_dialog_content = "我只是個外人，對龍洲的很多事都還不太懂，也沒辦法大言不慚地說能理解你們的處境。",
  ui_story_5089_50890301_64_dialog_content = "但是一路走來我見過很多人。",
  ui_story_5089_50890301_65_dialog_content = "有人為了自己的信念獻出一切，甘願成為黎明的光火。",
  ui_story_5089_50890301_66_dialog_content = "有人為了自己的夢想毀滅一切，您可墮入黑暗的深淵。",
  ui_story_5089_50890301_67_dialog_content = "當然我不是想評判他們的對錯，我也沒有資格三言兩語去定義別人的人生，我想說的是……",
  ui_story_5089_50890301_68_dialog_content = "唯獨什麼都不做，是得不到，也改變不了任何東西的。",
  ui_story_5089_50890301_69_dialog_content = "我是鄴王麾下的劍客，丹棠殿下身邊的護衛。",
  ui_story_5089_50890301_70_dialog_content = "責任就是聽命行事，盡忠職守。",
  ui_story_5089_50890301_71_dialog_content = "不需要我去改變什麼。",
  ui_story_5089_50890301_72_dialog_content = "那，我這麼問吧。如果鄴王和丹棠對妳下了相反的命令，要怎麼辦？",
  ui_story_5089_50890301_73_dialog_content = "……大王和郡主都是心懷天下，為鄴國盡心之人。",
  ui_story_5089_50890301_74_dialog_content = "這種回答說服不了任何人喔。",
  ui_story_5089_50890301_75_dialog_content = "我……",
  ui_story_5089_50890301_76_dialog_content = "還是沒有那孩子的影子啊，我來感應看看吧。",
  ui_story_5089_50890301_77_dialog_content = "感應。",
  ui_story_5089_50890301_78_dialog_content = "找到了，在南邊的巷子——嗯？",
  ui_story_5089_50890301_79_dialog_content = "略略略～",
  ui_story_5089_50890301_80_dialog_content = "這孩子……",
  ui_story_5089_50890301_81_dialog_content = "（咦？腳下好像絆到了什麼東西……）",
  ui_story_5089_50890301_82_dialog_content = "<color=#e8d9bb>劈裡啪啦！</color>",
  ui_story_5089_50890301_83_dialog_content = "<color=#e8d9bb>一排竹竿猛地砸來。</color>",
  ui_story_5089_50890301_84_dialog_content = "陷阱？！",
  ui_story_5089_50890301_85_dialog_content = "（先、先後退！）",
  ui_story_5089_50890301_86_dialog_content = "<color=#e8d9bb>但就像早已預測過入侵者的行動一般，隨後踩下的石磚早已被精準挖空。</color>",
  ui_story_5089_50890301_87_dialog_content = "<color=#e8d9bb>嗖！</color>",
  ui_story_5089_50890301_88_dialog_content = "<color=#e8d9bb>一隻裝滿水的木桶從天而降——</color>",
  ui_story_5089_50890301_89_dialog_content = "嗚哇！",
  ui_story_5089_50890301_90_dialog_content = "小心。",
  ui_story_5089_50890301_91_dialog_content = "<color=#e8d9bb>彷彿一陣無形的風吹過。</color>",
  ui_story_5089_50890301_92_dialog_content = "<color=#e8d9bb>阿玖只向前邁了半步，劍未出鞘，只精準地插入桶梁，借力一轉。</color>",
  ui_story_5089_50890301_93_dialog_content = "<color=#e8d9bb>桶內的水半滴未灑，已飄然落回對面的男孩腳下。</color>",
  ui_story_5089_50890301_94_dialog_content = "<color=#e8d9bb>同時，從巷子兩側砸下的竹竿在空中奇異地頓了一頓，失卻力道，盡數散落在地。</color>",
  ui_story_5089_50890301_95_dialog_content = "<color=#e8d9bb>竟是不知何時，已齊齊被從中間切斷。</color>",
  ui_story_5089_50890301_96_dialog_content = "好……好厲害。",
  ui_story_5089_50890301_97_dialog_content = "怎麼會……",
  ui_story_5089_50890301_98_dialog_content = "把東西還回來。",
  ui_story_5089_50890301_99_dialog_content = "……不知道妳在說什麼！",
  ui_story_5089_50890301_100_dialog_content = "別跑——",
  ui_story_5089_50890301_101_dialog_content = "等等，阿玖。",
  ui_story_5089_50890301_102_dialog_content = "他大費周章地佈置這麼多陷阱，還特地守在這裡，我認為一定有原因。",
  ui_story_5089_50890301_103_dialog_content = "東西就藏在旁邊那棟房子裡吧？",
  ui_story_5089_50890301_104_dialog_content = "！",
  ui_story_5089_50890301_105_dialog_content = "站住！喂！是我偷了你們的東西，快來抓我啊！",
  ui_story_5089_50890301_106_dialog_content = "果然。",
  ui_story_5089_50890301_107_dialog_content = "我可以先不進去，但作為交換，你能冷靜下來和我們談談嗎？",
  ui_story_5089_50890301_108_dialog_content = "我們不是壞人，如果你是遇到什麼困難，說不定我們可以幫忙。",
  ui_story_5089_50890301_109_dialog_content = "……其實，我……",
  ui_story_5089_50890301_110_dialog_content = "後退！",
  ui_story_5089_50890301_111_dialog_content = "怎麼……？！",
  ui_story_5089_50890301_112_dialog_content = "<color=#e8d9bb>唰——</color>",
  ui_story_5089_50890301_113_dialog_content = "<color=#e8d9bb>視線只來得及捕捉到一絲閃光。</color>",
  ui_story_5089_50890301_114_dialog_content = "<color=#e8d9bb>叮！</color>",
  ui_story_5089_50890301_115_dialog_content = "<color=#e8d9bb>阿玖的劍轉瞬出鞘，在空中硬架上數條極細，卻極堅韌的金屬絲。</color>",
  ui_story_5089_50890301_116_dialog_content = "找到了。",
  ui_story_5089_50890301_117_dialog_content = "你是——",
  ui_story_5089_50890301_118_dialog_content = "<color=#e8d9bb>來者不答，只更多金屬絲帶著寒意襲來！</color>",
  ui_story_5089_50890302_1_dialog_content = "阿玖，趁現在抓住他！",
  ui_story_5089_50890302_2_dialog_content = "嘖。",
  ui_story_5089_50890302_3_dialog_content = "<color=#e8d9bb>原本已經倒下的刺客忽一抬手，一條幾乎看不見的金屬絲直奔而來！</color>",
  ui_story_5089_50890302_4_dialog_content = "！",
  ui_story_5089_50890302_5_dialog_content = "<color=#e8d9bb>滴答。</color>",
  ui_story_5089_50890302_6_dialog_content = "<color=#e8d9bb>一滴血悄然滾落，砸碎在髒兮兮的地磚上，濺出一片猩紅。</color>",
  ui_story_5089_50890302_7_dialog_content = "阿玖……！",
  ui_story_5089_50890302_8_dialog_content = "<color=#e8d9bb>她擋在前方，直接用手攔住了那鋒利的兇器。</color>",
  ui_story_5089_50890302_9_dialog_content = "讓PlayerName閣下受驚了，還請恕罪。",
  ui_story_5089_50890302_10_dialog_content = "<color=#e8d9bb>隨後，她合攏手掌，用力一攥。</color>",
  ui_story_5089_50890302_11_dialog_content = "<color=#e8d9bb>剛趁機躍入空中，試圖逃走的刺客被血色的金屬線牽動，重重摔落。</color>",
  ui_story_5089_50890302_12_dialog_content = "我去將他押來。",
  ui_story_5089_50890302_13_dialog_content = "怎麼偏偏碰上那個鬼面閻王……",
  ui_story_5089_50890302_14_dialog_content = "現在乖乖受降，還能留你一命。",
  ui_story_5089_50890302_15_dialog_content = "……霜刃大人，雖說在下不過一介斥候，但都是大王直屬，便也斗膽與您稱句同僚。",
  ui_story_5089_50890302_16_dialog_content = "在下正在執行任務，您是想要阻攔，違抗大王之命嗎？",
  ui_story_5089_50890302_17_dialog_content = "……",
  ui_story_5089_50890302_18_dialog_content = "阿玖，妳回來了，傷口還好嗎？那個人……",
  ui_story_5089_50890302_19_dialog_content = "是我的錯，讓他……逃了。",
  ui_story_5089_50890302_20_dialog_content = "這樣啊，沒關係，你沒事就好……不，也算不上沒事。",
  ui_story_5089_50890302_21_dialog_content = "為什麼剛剛要拿手去擋啊！你就不知道痛嗎！讓我看看傷口。",
  ui_story_5089_50890302_22_dialog_content = "小傷而已，我自會處理，不敢勞煩PlayerName閣下。",
  ui_story_5089_50890302_23_dialog_content = "妳啊……算了，妳現在就處理，我去看看那兩個孩子。",
  ui_story_5089_50890302_24_dialog_content = "兩個孩子？",
  ui_story_5089_50890302_25_dialog_content = "嗯，就在那邊的房子裡。",
  ui_story_5089_50890302_26_dialog_content = "嗚哇啊啊啊——好可怕啊嗚嗚嗚——",
  ui_story_5089_50890302_27_dialog_content = "妳、妳別哭了。對了！我帶了好東西要給妳喔。",
  ui_story_5089_50890302_28_dialog_content = "看，這裡有可愛的布偶，漂亮的花燈。",
  ui_story_5089_50890302_29_dialog_content = "還有好多話本子！我唸給妳聽好不好？別哭了……",
  ui_story_5089_50890302_30_dialog_content = "嗚嗚嗚嗚……",
  ui_story_5089_50890302_31_dialog_content = "就是這樣，那孩子沒偷金子，只拿了世子送的玩具。",
  ui_story_5089_50890302_32_dialog_content = "誰稀罕你們的金子！",
  ui_story_5089_50890302_33_dialog_content = "哇啊啊可怕的人嗚嗚嗚——",
  ui_story_5089_50890302_34_dialog_content = "你們嚇到她了！快出去！喂，妳別哭了！妳想要什麼我都去找給妳。",
  ui_story_5089_50890302_35_dialog_content = "……",
  ui_story_5089_50890302_36_dialog_content = "阿玖？",
  ui_story_5089_50890302_37_dialog_content = "<color=#e8d9bb>她在小女孩面前蹲下，生硬地抬起手，將自己的面具蓋在了她頭上。</color>",
  ui_story_5089_50890302_38_dialog_content = "妳、妳要幹什麼？妳要敢傷害她——",
  ui_story_5089_50890302_39_dialog_content = "風來了，雨來了，龍王背著鼓來了。",
  ui_story_5089_50890302_40_dialog_content = "哪裡藏，面具下藏，一藏藏個小女郎。",
  ui_story_5089_50890302_41_dialog_content = "女郎女郎別害怕，屋裡有個大甜瓜。",
  ui_story_5089_50890302_42_dialog_content = "<color=#e8d9bb>在阿玖柔聲念著的歌謠裡，藏在面具下的女孩哭聲漸漸小了。</color>",
  ui_story_5089_50890302_43_dialog_content = "（阿玖，原來會露出這麼溫柔的表情啊。）",
  ui_story_5089_50890302_44_dialog_content = "PlayerName公子、阿玖，總算找到你們了。",
  ui_story_5089_50890302_45_dialog_content = "咦，竟能看見阿玖主動摘下面具，這是怎麼了？",
  ui_story_5089_50890302_46_dialog_content = "丹棠殿下，這是……",
  ui_story_5089_50890302_47_dialog_content = "大姐姐……",
  ui_story_5089_50890302_48_dialog_content = "嗯？",
  ui_story_5089_50890302_49_dialog_content = "剛才的歌，可以再唱一遍嗎？",
  ui_story_5089_50890302_50_dialog_content = "很像……媽媽唱的歌。",
  ui_story_5089_50890302_51_dialog_content = "可以。",
  ui_story_5089_50890302_52_dialog_content = "真的嗎！那可以讓大家都來聽聽嗎！",
  ui_story_5089_50890302_53_dialog_content = "大家……？",
  ui_story_5089_50890302_54_dialog_content = "二狗哥哥，可以把大家都叫來嗎！",
  ui_story_5089_50890302_55_dialog_content = "他們好像不是壞蛋，妳想叫就叫吧。",
  ui_story_5089_50890302_56_dialog_content = "怎麼了？小花妹妹突然叫我們過來。",
  ui_story_5089_50890302_57_dialog_content = "管他呢，反正咱們也沒事幹。",
  ui_story_5089_50890302_58_dialog_content = "怎麼還有大人在啊……",
  ui_story_5089_50890302_59_dialog_content = "怎麼這麼多孩子？",
  ui_story_5089_50890302_60_dialog_content = "這個在下知道，剛從客棧老闆那兒打聽來的。",
  ui_story_5089_50890302_61_dialog_content = "之前那老伯不是說，鎮上的壯年不少都去工坊做工了嗎？",
  ui_story_5089_50890302_62_dialog_content = "但畢竟人生地不熟的，不少人就把孩子扔在老家給長輩照顧。",
  ui_story_5089_50890302_63_dialog_content = "但人老了，總有管不到的地方，這些孩子就聚在一起漫山遍野地跑。",
  ui_story_5089_50890302_64_dialog_content = "所以他們其實沒有血緣關係？我還以為小花是二狗的妹妹，所以才……",
  ui_story_5089_50890302_65_dialog_content = "小花就是我妹妹。我爹娘死得早，是她家給了我口飯吃。",
  ui_story_5089_50890302_66_dialog_content = "她爹娘前幾天離家的時候叫我照顧好她，我當然要照辦。",
  ui_story_5089_50890302_67_dialog_content = "但小花想爹娘，這幾天一直哭，所以我才想要……",
  ui_story_5089_50890302_68_dialog_content = "想用玩具哄她開心？",
  ui_story_5089_50890302_69_dialog_content = "但既然被你們抓住了，要打要罵我也認了。",
  ui_story_5089_50890302_70_dialog_content = "雖然偷東西不對，但知道了這些後怎麼可能再罵你啊。",
  ui_story_5089_50890302_71_dialog_content = "不過這些孩子該怎麼辦？阿玖被他們包圍，看起來都快僵住了。",
  ui_story_5089_50890302_72_dialog_content = "所以PlayerName公子也別再躲懶了，快來幫忙。",
  ui_story_5089_50890302_73_dialog_content = "我該做點什麼？",
  ui_story_5089_50890302_74_dialog_content = "叫阿玖在這麼多人面前唱詩未免太為難她了，所以我們得幫忙分擔一些。",
  ui_story_5089_50890302_75_dialog_content = "走吧，回客棧，取我的琵琶去。",
  ui_story_5089_50890302_76_dialog_content = "早就聽說PlayerName公子擅琴，卻一直未能得見，不知今日你可願與我合奏？",
  ui_story_5089_50890302_77_dialog_content = "我是很樂意，但這裡並沒有琴啊。",
  ui_story_5089_50890302_78_dialog_content = "可以有，可以有。",
  ui_story_5089_50890302_79_dialog_content = "昔有賢者鼓盆而歌，今亦可以有空裔擊杯奏樂嘛。",
  ui_story_5089_50890302_80_dialog_content = "看，只要在幾個杯子裡裝上不等量的水，這麼一敲，就能奏出不同的音調了。",
  ui_story_5089_50890302_81_dialog_content = "那我試試看。",
  ui_story_5089_50890302_82_dialog_content = "阿玖，可還記得我們剛造訪雙榭城時，我與妳說的話？",
  ui_story_5089_50890302_83_dialog_content = "若有朝一日能與琴師合奏，希望妳能來舞劍。",
  ui_story_5089_50890302_84_dialog_content = "在、在這大庭廣眾之下……",
  ui_story_5089_50890302_85_dialog_content = "不只妳，我們全都在喔。",
  ui_story_5089_50890302_86_dialog_content = "唉，若是你實在不願，我也不勉強你，只是要讓今日這樂聲有些殘缺了。",
  ui_story_5089_50890302_87_dialog_content = "我、我知道了……",
  ui_story_5089_50890302_88_dialog_content = "獻醜了。",
  ui_story_5089_50890302_89_dialog_content = "呵呵，阿玖妳看，那些孩子們的眼睛都亮了呢。",
  ui_story_5089_50890302_90_dialog_content = "妳的劍舞，必定是天下第一好的。",
  ui_story_5089_50890302_91_dialog_content = "殿下實在謬讚，這等粗陋武藝，只能勉強不污各位眼睛罷了。",
  ui_story_5089_50890302_92_dialog_content = "這有了奏樂的，舞劍的，在下能幹些什麼呢？",
  ui_story_5089_50890302_93_dialog_content = "不如在下來唱個小調，給大家助興吧。",
  ui_story_5089_50890302_94_dialog_content = "喔？你會唱些什麼？",
  ui_story_5089_50890302_95_dialog_content = "咳咳，瞧一瞧，看一看了啊。",
  ui_story_5089_50890302_96_dialog_content = "南來的北往的，諸位父老相親，咱們今兒個在此獻藝。",
  ui_story_5089_50890302_97_dialog_content = "沒錢的呢，捧個人場，但要有那麼三五餘錢，還是望您捧個錢場啊。",
  ui_story_5089_50890302_98_dialog_content = "<color=#e8d9bb>叮。</color>",
  ui_story_5089_50890302_99_dialog_content = "<color=#e8d9bb>竟真有不明真相，聚集而來的百姓扔了幾枚銅板過來。</color>",
  ui_story_5089_50890302_100_dialog_content = "李天閑！",
  ui_story_5089_50890302_101_dialog_content = "哎殿下，奏樂呢，靜心，靜心啊。",
  ui_story_5089_50890302_102_dialog_content = "<color=#e8d9bb>隱約欲來的風雨，臨時拼湊的琴，各懷心事的同伴。</color>",
  ui_story_5089_50890302_103_dialog_content = "<color=#e8d9bb>這絕稱不上一場完美的演奏，甚至完全是心血來潮的湊巧。</color>",
  ui_story_5089_50890302_104_dialog_content = "<color=#e8d9bb>但至少，此時此刻——</color>",
  ui_story_5089_50890302_105_dialog_content = "<color=#e8d9bb>此景當歌。</color>",
  ui_story_5089_50890401_1_dialog_content = "PlayerName公子，你一直拿在手裡，翻來覆去看的是什麼？",
  ui_story_5089_50890401_2_dialog_content = "你說這個銅偶？是剛剛分開前二狗給我的。",
  ui_story_5089_50890401_3_dialog_content = "阿玖送了一副面具給小花，不再需要玩具了，二牛也就把東西都還了回來。",
  ui_story_5089_50890401_4_dialog_content = "然後作為賠禮，給了我這個。",
  ui_story_5089_50890401_5_dialog_content = "說是不久前一個路過鎮子的大姐姐做給他的，一種叫「魔合羅」的玩具。",
  ui_story_5089_50890401_6_dialog_content = "那個大姐姐身邊跟著好多黑衣人，還都不怎麼說話，可嚇人了。",
  ui_story_5089_50890401_7_dialog_content = "不過那個大姐姐是個好人，請我們去大酒樓吃了好多肉！",
  ui_story_5089_50890401_8_dialog_content = "她還會做好多東西，之前巷子裡的那些陷阱就是按照她畫的設計圖做的。",
  ui_story_5089_50890401_9_dialog_content = "她說那都是機關術的基礎，要是學好了能變聰明呢。",
  ui_story_5089_50890401_10_dialog_content = "她有說自己叫什麼名字嗎？",
  ui_story_5089_50890401_11_dialog_content = "那倒沒有，她們只在鎮上待了一天，很快就走了。不過……對了。",
  ui_story_5089_50890401_12_dialog_content = "大姐姐其實有點奇怪，明明這段時間都沒下雨，卻整天帶著一把好大的傘。",
  ui_story_5089_50890401_13_dialog_content = "是不是聽起來很像是我們認識的某個人？",
  ui_story_5089_50890401_14_dialog_content = "從濟國回鄴，這是最快的一條路，璇璣卿他們也經過這裡也不無可能。",
  ui_story_5089_50890401_15_dialog_content = "只是還能吃肉喝酒，跟小孩子玩鬧，甚至隨身帶著武器……",
  ui_story_5089_50890401_16_dialog_content = "這位朝廷重犯的日子聽起來過得竟還不錯。",
  ui_story_5089_50890401_17_dialog_content = "不過身邊跟著一堆黑衣人，還是沒法自由行動吧。",
  ui_story_5089_50890401_18_dialog_content = "PlayerName公子，那個人偶可以暫且借我嗎？",
  ui_story_5089_50890401_19_dialog_content = "拿去吧。不過我看了半天，還試著感應過裡面，結果什麼都發現。",
  ui_story_5089_50890401_20_dialog_content = "也就是說，即使裡面有資訊，也只會藏於人偶本身嗎……",
  ui_story_5089_50890401_21_dialog_content = "<color=#e8d9bb>深夜。</color>",
  ui_story_5089_50890401_22_dialog_content = "哈欠～",
  ui_story_5089_50890401_23_dialog_content = "喉嚨好乾，想喝水……",
  ui_story_5089_50890401_24_dialog_content = "茶壺空了？去大廳裡看看吧。",
  ui_story_5089_50890401_25_dialog_content = "咦？我記得旁邊是丹棠的房間，竟然還亮著燈？",
  ui_story_5089_50890401_26_dialog_content = "外面是PlayerName公子嗎？",
  ui_story_5089_50890401_27_dialog_content = "咦？丹棠你看得見我？",
  ui_story_5089_50890401_28_dialog_content = "光聽腳步聲就知道了，請進來吧。",
  ui_story_5089_50890401_29_dialog_content = "桌上那是……妳還在研究那個人偶啊。",
  ui_story_5089_50890401_30_dialog_content = "璇璣卿在那種情況下留下的東西，就算並非刻意，也一定蘊含著某種資訊。",
  ui_story_5089_50890401_31_dialog_content = "說到底，「魔合羅」到底是什麼？",
  ui_story_5089_50890401_32_dialog_content = "是一種以前流行過的玩具，一般是用泥土或者木頭雕刻成的偶人，沒有用金屬的。",
  ui_story_5089_50890401_33_dialog_content = "但這個不是銅做的嗎？",
  ui_story_5089_50890401_34_dialog_content = "璇璣卿擅用銅，她初次嶄露頭角，便是因為做了一套奏樂銅人。",
  ui_story_5089_50890401_35_dialog_content = "她與銅人一起列隊奏樂，竟無人發現異常，直至表演結束，觀眾才得知奏樂的竟都是銅人。",
  ui_story_5089_50890401_36_dialog_content = "原來璇極能做出那麼厲害的人偶……但為什麼我們手裡這個就這麼醜？",
  ui_story_5089_50890401_37_dialog_content = "這便是我想說的另一點異常。",
  ui_story_5089_50890401_38_dialog_content = "但「魔合羅」本該是漂亮可愛的孩童模樣，她卻偏做得醜如妖魔，還加了幾道皺紋。",
  ui_story_5089_50890401_39_dialog_content = "「魔合羅」手中應拿著荷葉或荷花。",
  ui_story_5089_50890401_40_dialog_content = "這個銅人手裡雖也拿著花，細細看來，卻是木蘭。",
  ui_story_5089_50890401_41_dialog_content = "一種生於水下，一種卻極怕水淹，乃是水火不容。",
  ui_story_5089_50890401_42_dialog_content = "這人偶和「魔合羅」處處肖似，卻處處不同，只能說是個偽物替身罷了。",
  ui_story_5089_50890401_43_dialog_content = "偽物……替身……",
  ui_story_5089_50890401_44_dialog_content = "還有，以前有一齣名為《魔合羅》的折子戲。",
  ui_story_5089_50890401_45_dialog_content = "大部人對這齣戲不甚熟悉，但其中一句唱詞卻流傳極廣，人盡皆知。",
  ui_story_5089_50890401_46_dialog_content = "是什麼詞？",
  ui_story_5089_50890401_47_dialog_content = "「畫虎畫皮難畫骨，知人知面不知心。」",
  ui_story_5089_50890401_48_dialog_content = "<color=#e8d9bb>啪。</color>",
  ui_story_5089_50890401_49_dialog_content = "！",
  ui_story_5089_50890401_50_dialog_content = "誰在外面！",
  ui_story_5089_50890402_1_dialog_content = "打不過就跑，本郡主今天算是見識了他們的本事。",
  ui_story_5089_50890402_2_dialog_content = "那些人是駿命？還是……",
  ui_story_5089_50890402_3_dialog_content = "不知。",
  ui_story_5089_50890402_4_dialog_content = "但就現狀而言，是駿命，還是鄴國暗探，都沒什麼區別了。",
  ui_story_5089_50890402_5_dialog_content = "好在剛剛來的人還不多，武藝也算不得多高強。",
  ui_story_5089_50890402_6_dialog_content = "唯有逃跑的功夫一流，應當只是前來打探消息的斥候。",
  ui_story_5089_50890402_7_dialog_content = "也就是說我們行蹤已經暴露了，是不是快點離開比較好？",
  ui_story_5089_50890402_8_dialog_content = "說來，PlayerName公子，你有沒有發現一件奇怪的事情。",
  ui_story_5089_50890402_9_dialog_content = "什麼……啊！",
  ui_story_5089_50890402_10_dialog_content = "我們鬧出這麼大的動靜……阿玖呢？",
  ui_story_5089_50890402_11_dialog_content = "派出去的那幾個傢伙怎麼還沒回來，不會是沒命了吧。",
  ui_story_5089_50890402_12_dialog_content = "這點小事都做不好，死了也活該。",
  ui_story_5089_50890402_13_dialog_content = "唉，也是我們這種人命賤。不管他們了，我出去上個廁所。",
  ui_story_5089_50890402_14_dialog_content = "別動。",
  ui_story_5089_50890402_15_dialog_content = "！",
  ui_story_5089_50890402_16_dialog_content = "好，好，我不動，英雄您別急。",
  ui_story_5089_50890402_17_dialog_content = "能悄無聲息地潛入我們這暗樁，把劍架在我脖子上，我一定不是您的對手。",
  ui_story_5089_50890402_18_dialog_content = "所以您先把劍拿遠點，不然一不小心割斷了我的脖子，想問什麼也問不到了。",
  ui_story_5089_50890402_19_dialog_content = "你們在這做什麼，到底收到了什麼命令？",
  ui_story_5089_50890402_20_dialog_content = "您問這個是……",
  ui_story_5089_50890402_21_dialog_content = "少廢話，回答問題。",
  ui_story_5089_50890402_22_dialog_content = "好好好，我們就是奉了主人的命令，想要把家裡不聽話的小姐帶回去。",
  ui_story_5089_50890402_23_dialog_content = "家事而已，也不犯法吧。",
  ui_story_5089_50890402_24_dialog_content = "這種陣仗的「家事」？",
  ui_story_5089_50890402_25_dialog_content = "誰叫我們主子家大業大呢，而且小姐身邊還帶著個厲害的護衛。",
  ui_story_5089_50890402_26_dialog_content = "那護衛還是我們主子親自指派的呢，但也不知道發了什麼瘋，竟跟著小姐胡鬧。",
  ui_story_5089_50890402_27_dialog_content = "主子很是失望。",
  ui_story_5089_50890402_28_dialog_content = "……",
  ui_story_5089_50890402_29_dialog_content = "我也說了，只是「家事」，血緣至親嘛。",
  ui_story_5089_50890402_30_dialog_content = "主子生氣歸生氣，但也不可能真害小姐。",
  ui_story_5089_50890402_31_dialog_content = "小姐再不懂事，抓回去最多也就是關個禁閉，抄抄家規什麼的就算了。",
  ui_story_5089_50890402_32_dialog_content = "偏那個護衛忘了本，眼看要壞了主子的大事。",
  ui_story_5089_50890402_33_dialog_content = "可憐主子多年栽培，竟是養出一條白眼狼來，英雄您說這事——",
  ui_story_5089_50890402_34_dialog_content = "哎，英雄？您還在嗎？",
  ui_story_5089_50890402_35_dialog_content = "呵。",
  ui_story_5089_50890402_36_dialog_content = "你怎麼這麼半天才回來？",
  ui_story_5089_50890402_37_dialog_content = "遇到個熟人，聊了兩句。",
  ui_story_5089_50890402_38_dialog_content = "等出去打探消息的人回來，告訴他們。",
  ui_story_5089_50890402_39_dialog_content = "明日就去迎郡主歸家。",
  ui_story_5089_50890402_40_dialog_content = "若是那位鬼面閻王阻攔，就以叛逃論處。",
  ui_story_5089_50890402_41_dialog_content = "殺。",
  ui_story_5089_50890402_42_dialog_content = "……丹棠殿下、PlayerName閣下，你們為何都在外面？",
  ui_story_5089_50890402_43_dialog_content = "阿玖，妳去哪了？我們剛剛——",
  ui_story_5089_50890402_44_dialog_content = "PlayerName公子。",
  ui_story_5089_50890402_45_dialog_content = "很晚了，回去休息吧。",
  ui_story_5089_50890402_46_dialog_content = "有些事，我還要再想想。",
  ui_story_5089_50890402_47_dialog_content = "……好。",
  ui_story_5089_50890402_48_dialog_content = "晚安，丹棠、阿玖。",
  ui_story_5089_50890402_49_dialog_content = "PlayerName公子，晚安。",
  ui_story_5089_50890402_50_dialog_content = "……",
  ui_story_5089_50890402_51_dialog_content = "<color=#e8d9bb>翌日。</color>",
  ui_story_5089_50890402_52_dialog_content = "方便打擾一下嗎，李大師。",
  ui_story_5089_50890402_53_dialog_content = "嘶……在下是睡糊塗了，還是今兒太陽從西邊出來了？",
  ui_story_5089_50890402_54_dialog_content = "丹棠殿下怎麼說話這麼客氣了？",
  ui_story_5089_50890402_55_dialog_content = "大概是因為，我想請你算上一卦。",
  ui_story_5089_50890402_56_dialog_content = "這可真是稀罕。",
  ui_story_5089_50890402_57_dialog_content = "您是想窺天地，卜吉凶，還是算姻緣呀？",
  ui_story_5089_50890402_58_dialog_content = "我想……問一問前路。",
  ui_story_5089_50890402_59_dialog_content = "有件事，不知該不該，又能不能做。",
  ui_story_5089_50890402_60_dialog_content = "好嘞，明白了，勞煩您伸個手，讓在下擲個籤。",
  ui_story_5089_50890402_61_dialog_content = "好。",
  ui_story_5089_50890402_62_dialog_content = "<color=#e8d9bb>嘩啦。</color>",
  ui_story_5089_50890402_63_dialog_content = "<color=#e8d9bb>兩支卦籤落在丹棠手上。但還不等她細看，嘩啦啦啦——</color>",
  ui_story_5089_50890402_64_dialog_content = "<color=#e8d9bb>李天閑將整個籤筒裡的籤都倒了出來。</color>",
  ui_story_5089_50890402_65_dialog_content = "李大師這是何意？",
  ui_story_5089_50890402_66_dialog_content = "唉，聽您這麼叫真是渾身不自在，您還是叫李天閑吧，李騙子也行啊。",
  ui_story_5089_50890402_67_dialog_content = "您看，這卦籤雖不起眼，但在下行走江湖，也是靠它們混口飯吃。",
  ui_story_5089_50890402_68_dialog_content = "有信者呢，便為他們解一解禍，避一避災。",
  ui_story_5089_50890402_69_dialog_content = "有不信者呢，打幾句哈哈，說句信則有不信則無也就罷了。",
  ui_story_5089_50890402_70_dialog_content = "但您說著想問它，卻又疑它。想為前路求一天命，卻又不肯乖乖聽命行事。",
  ui_story_5089_50890402_71_dialog_content = "此舉可與踢在下的館子無異啊。",
  ui_story_5089_50890402_72_dialog_content = "……這是否言重了些。",
  ui_story_5089_50890402_73_dialog_content = "在下可不覺得。",
  ui_story_5089_50890402_74_dialog_content = "敢問，當最初的那兩支籤落下時，殿下是否已有了希望的結果？",
  ui_story_5089_50890402_75_dialog_content = "……",
  ui_story_5089_50890402_76_dialog_content = "您看，我說什麼來著。堂堂灼華郡主，不信天命可是人盡皆知。",
  ui_story_5089_50890402_77_dialog_content = "既然心裡已有決斷，就甭來消遣在下了。",
  ui_story_5089_50890402_78_dialog_content = "不過還是得請您搭把手，把我那卦籤再裝回來。",
  ui_story_5089_50890402_79_dialog_content = "李大師。",
  ui_story_5089_50890402_80_dialog_content = "不是，丹棠殿下，咱話不都說透了嗎，您怎麼還這麼叫呢？",
  ui_story_5089_50890402_81_dialog_content = "因為我還有一事相求。",
  ui_story_5089_50890402_82_dialog_content = "……在下錯了，在下收回剛才的話。",
  ui_story_5089_50890402_83_dialog_content = "來您伸手，在下這就給您抽籤重算一卦，告訴您此事不可為。",
  ui_story_5089_50890402_84_dialog_content = "很遺憾，我乃灼華郡主。",
  ui_story_5089_50890402_85_dialog_content = "不信天命，人盡皆知。",
  ui_story_5089_50890402_86_dialog_content = "活該，活該。",
  ui_story_5089_50890402_87_dialog_content = "搬石頭砸腳！",
  ui_story_5089_50890402_88_dialog_content = "唉……行吧，誰讓在下還欠著一份救命之恩呢。",
  ui_story_5089_50890402_89_dialog_content = "您說要怎麼辦吧。",
  ui_story_5089_50890402_90_dialog_content = "丹棠，我已經按妳說的找了鏢局。",
  ui_story_5089_50890402_91_dialog_content = "把世子送的金子都交給他們先行押送到王都去了。",
  ui_story_5089_50890402_92_dialog_content = "接下來怎麼辦，我們也走嗎？",
  ui_story_5089_50890402_93_dialog_content = "不急。",
  ui_story_5089_50890402_94_dialog_content = "剛剛客棧老闆送來了兩包新茶，我覺得味道不錯，坐下來喝一杯再走也好。",
  ui_story_5089_50890402_95_dialog_content = "真的還能這麼悠閒嗎？",
  ui_story_5089_50890402_96_dialog_content = "沒關係，花不了多久。",
  ui_story_5089_50890402_97_dialog_content = "阿玖，妳在吧？",
  ui_story_5089_50890402_98_dialog_content = "……是。",
  ui_story_5089_50890402_99_dialog_content = "也來喝杯茶，喝完我有話和妳說。",
  ui_story_5089_50890402_100_dialog_content = "是。",
  ui_story_5089_50890402_101_dialog_content = "這茶真的很好喝，味道淡淡的，但很清爽，不知道為什麼還有種其他茶沒有的果香。",
  ui_story_5089_50890402_102_dialog_content = "因為我在裡面加了以微毒樹果製成的「寒脈散」。",
  ui_story_5089_50890402_103_dialog_content = "……咦？",
  ui_story_5089_50890402_104_dialog_content = "<color=#e8d9bb>咚！</color>",
  ui_story_5089_50890402_105_dialog_content = "<color=#e8d9bb>阿玖突然單膝跪倒在地。</color>",
  ui_story_5089_50890402_106_dialog_content = "阿、阿玖！",
  ui_story_5089_50890402_107_dialog_content = "沒事的，這藥只會使人身體麻痺，動彈不得，但不會傷及根本，過段時間就會自然恢復。",
  ui_story_5089_50890402_108_dialog_content = "只是越是內力深厚，武藝高強之人，中毒越快，持續的時間越長罷了。",
  ui_story_5089_50890402_109_dialog_content = "所以我才什麼感覺都沒有嗎……不對，不是說這個的時候。",
  ui_story_5089_50890402_110_dialog_content = "為什麼要做這種事？",
  ui_story_5089_50890402_111_dialog_content = "因為，已經沒有時間了。",
  ui_story_5089_50890402_112_dialog_content = "丹棠殿下，多言多語說有不少人朝客棧來了。",
  ui_story_5089_50890402_113_dialog_content = "眼看來者不善哪。",
  ui_story_5089_50890402_114_dialog_content = "李天閑，你也……你是誰啊！",
  ui_story_5089_50890402_115_dialog_content = "行不更名，坐不改姓，在下阿玖姑娘是也。",
  ui_story_5089_50890402_116_dialog_content = "這不是全改了嗎？！",
  ui_story_5089_50890402_117_dialog_content = "都這時候了，您就別在這點小事上吹毛求疵了。",
  ui_story_5089_50890402_118_dialog_content = "是我的問題嗎！",
  ui_story_5089_50890402_119_dialog_content = "勞駕，請幫在下把阿玖姑娘藏進那邊的櫃子去，咱們動作得快點了。",
  ui_story_5089_50890402_120_dialog_content = "喔，好……什麼？",
  ui_story_5089_50890402_121_dialog_content = "為什麼……",
  ui_story_5089_50890402_122_dialog_content = "<color=#e8d9bb>阿玖的身體微微搖晃，彷彿拚盡全力想要對抗藥效，幾乎能聽到體內的骨骼咯咯作響。</color>",
  ui_story_5089_50890402_123_dialog_content = "<color=#e8d9bb>手上的傷口裂開，鮮血濡濕了衣衫。</color>",
  ui_story_5089_50890402_124_dialog_content = "<color=#e8d9bb>她挪動僵硬的身體，終於扯住了丹棠的一角裙擺。</color>",
  ui_story_5089_50890402_125_dialog_content = "……",
  ui_story_5089_50890402_126_dialog_content = "<color=#e8d9bb>丹棠後退一步，將裙擺從阿玖手中扯開。</color>",
  ui_story_5089_50890402_127_dialog_content = "朝夕相處的這五年，妳為我做了很多，我很感謝妳。",
  ui_story_5089_50890402_128_dialog_content = "妳是很好的姑娘，也一度是最稱職的下屬。",
  ui_story_5089_50890402_129_dialog_content = "但是，現在已經無法再粉飾太平了。",
  ui_story_5089_50890402_130_dialog_content = "誠然妳不願意傷害我，但妳也不會違抗叔父的命令。",
  ui_story_5089_50890402_131_dialog_content = "妳無法走上兩條相反的道路，也無法同時成為對立兩人手中的劍。",
  ui_story_5089_50890402_132_dialog_content = "丹棠……殿下……",
  ui_story_5089_50890402_133_dialog_content = "其實這件事本輪不到我替妳安排，因為這當是妳自己的選擇。",
  ui_story_5089_50890402_134_dialog_content = "遺憾妳不願選，那便會有人像我這般來接管這份權利。",
  ui_story_5089_50890402_135_dialog_content = "放棄了行動的自由，自然就只能成為任人擺弄的傀儡。",
  ui_story_5089_50890402_136_dialog_content = "妳看，現在要怎麼做已經由不得妳了。",
  ui_story_5089_50890402_137_dialog_content = "阿玖。",
  ui_story_5089_50890402_138_dialog_content = "從今日起，我解除妳擔任灼華郡主貼身護衛的職責。",
  ui_story_5089_50890402_139_dialog_content = "！",
  ui_story_5089_50890402_140_dialog_content = "我不需要，也不敢需要現在的妳。",
  ui_story_5089_50890402_141_dialog_content = "我不打算再做被妳保護，卻也要受妳監視的郡主。",
  ui_story_5089_50890402_142_dialog_content = "我想要——",
  ui_story_5089_50890402_143_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5089_50890402_144_dialog_content = "<color=#e8d9bb>外頭傳來的巨響淹沒了丹棠最後的幾個字。</color>",
  ui_story_5089_50890402_145_dialog_content = "進去吧您～",
  ui_story_5089_50890402_146_dialog_content = "嗯？",
  ui_story_5089_50890402_147_dialog_content = "<color=#e8d9bb>我也被推進了衣櫃裡。</color>",
  ui_story_5089_50890402_148_dialog_content = "對不起，PlayerName公子，這次是我自作主張。",
  ui_story_5089_50890402_149_dialog_content = "但阿玖，和之後的事，就都拜託給你了。",
  ui_story_5089_50890402_150_dialog_content = "等等，丹棠！",
  ui_story_5089_50890402_151_dialog_content = "<color=#e8d9bb>衣櫃的門關上了。</color>",
  ui_story_5089_50890402_152_dialog_content = "<color=#e8d9bb>下一刻，房間的門被猛然撞開。</color>",
  ui_story_5089_50890402_153_dialog_content = "唉，郡主娘娘您可真難請。",
  ui_story_5089_50890402_154_dialog_content = "（這個聲音是！）",
  ui_story_5089_50890402_155_dialog_content = "綴戶……",
  ui_story_5089_50890402_156_dialog_content = "璇璣卿說的沒錯，妳真的還活著。",
  ui_story_5089_50890402_157_dialog_content = "還沒造出最強的機關獸，我怎麼捨得死呢？",
  ui_story_5089_50890402_158_dialog_content = "之前來不及問，但現狀早已不言而喻，妳果然也是駿命的成員。",
  ui_story_5089_50890402_159_dialog_content = "誰願意支持我的機關術，我就認誰當主子，這不是很正常嗎？",
  ui_story_5089_50890402_160_dialog_content = "但好不容易又拿到了燭陰火，我忙著調整新一代蠆的能源系統呢。",
  ui_story_5089_50890402_161_dialog_content = "這幫傢伙卻非要拉我過來迎接您。",
  ui_story_5089_50890402_162_dialog_content = "不過他們倒是答應了我一件好事。",
  ui_story_5089_50890402_163_dialog_content = "如果您願意反抗一旁的護衛，我就可以現場實地測試新武器。",
  ui_story_5089_50890402_164_dialog_content = "所以能否請您兩位反抗一下呢？",
  ui_story_5089_50890402_165_dialog_content = "為何要反抗？",
  ui_story_5089_50890402_166_dialog_content = "我是鄴國郡主，妳姑且不論，其餘的諸位都是我叔父手下的將士吧。",
  ui_story_5089_50890402_167_dialog_content = "叔父的屬下只是迎我歸家，又不會傷害我。對吧，阿玖。",
  ui_story_5089_50890402_168_dialog_content = "（點頭。）",
  ui_story_5089_50890402_169_dialog_content = "唉，算了，就這樣吧。趕緊走吧，工坊那邊還忙著呢。",
  ui_story_5089_50890402_170_dialog_content = "等等，郡主身邊應該還有兩人。",
  ui_story_5089_50890402_171_dialog_content = "那個算命的騙子聽到動靜早就跑了。",
  ui_story_5089_50890402_172_dialog_content = "至於空裔，獨自一人什麼都做不了，你們還擔心什麼？",
  ui_story_5089_50890402_173_dialog_content = "而且如果我沒猜錯，叔父的命令應該只是要把「我」帶回去吧。",
  ui_story_5089_50890402_174_dialog_content = "是……郡主請。",
  ui_story_5089_50890402_175_dialog_content = "<color=#e8d9bb>房間重歸寂靜。</color>",
  ui_story_5089_50890402_176_dialog_content = "<color=#e8d9bb>只是這次，只剩下我和阿玖兩人。</color>",
  ui_story_5089_50890501_1_dialog_content = "……那兩個人在想些什麼啊！",
  ui_story_5089_50890501_2_dialog_content = "之前還說要爭取自由行動的時間，結果現在完全不反抗就乖乖就範了？！",
  ui_story_5089_50890501_3_dialog_content = "連綴戶那種危險的傢伙都混在裡面，怎麼可能保證安全？！",
  ui_story_5089_50890501_4_dialog_content = "阿玖也覺得很沒道理對吧！",
  ui_story_5089_50890501_5_dialog_content = "我……不知道。",
  ui_story_5089_50890501_6_dialog_content = "殿下似乎已經不再信任我了。",
  ui_story_5089_50890501_7_dialog_content = "或許正如她所說，我其實失職得徹底。",
  ui_story_5089_50890501_8_dialog_content = "而且我已經不再是丹棠殿下的護衛，現在要做什麼也……",
  ui_story_5089_50890501_9_dialog_content = "妳在說什麼傻話，不是至少還有一件事非做不可嗎？",
  ui_story_5089_50890501_10_dialog_content = "什麼？",
  ui_story_5089_50890501_11_dialog_content = "丹棠說，已經沒有時間了。",
  ui_story_5089_50890501_12_dialog_content = "但明明之前在船上，她還沒有這麼急切，還說她能理解妳的猶豫。",
  ui_story_5089_50890501_13_dialog_content = "才經過昨天一晚，她的態度就變了。",
  ui_story_5089_50890501_14_dialog_content = "或許關鍵就在於璇極的那個人偶。",
  ui_story_5089_50890501_15_dialog_content = "再加上她明明什麼都沒告訴我，卻說什麼後面的事交給我了……",
  ui_story_5089_50890501_16_dialog_content = "我想只要按照現在的線索，想辦法去見到璇極，一定就能搞懂一些真相。",
  ui_story_5089_50890501_17_dialog_content = "然後，阿玖，妳可以和丹棠吵一架。",
  ui_story_5089_50890501_18_dialog_content = "和丹棠殿下……怎可如此僭越！",
  ui_story_5089_50890501_19_dialog_content = "明明她已經不是妳的主人了？",
  ui_story_5089_50890501_20_dialog_content = "即便如此……",
  ui_story_5089_50890501_21_dialog_content = "不管是出於什麼理由，有什麼苦衷，她都是單方面做出了決定。",
  ui_story_5089_50890501_22_dialog_content = "老實說，就連我都有點生氣。",
  ui_story_5089_50890501_23_dialog_content = "不光被丟在這種人生地不熟的地方……",
  ui_story_5089_50890501_24_dialog_content = "還要在什麼都不知道的情況下，眼睜睜看著重要的朋友拿自己的安危冒險。",
  ui_story_5089_50890501_25_dialog_content = "所以等這些亂七八糟的事情解決，我們一起去吧。",
  ui_story_5089_50890501_26_dialog_content = "去找那任性的郡主大人好好理論一番。",
  ui_story_5089_50890501_27_dialog_content = "PlayerName閣下……",
  ui_story_5089_50890501_28_dialog_content = "不過在那之前，妳願意助我一臂之力嗎？",
  ui_story_5089_50890501_29_dialog_content = "畢竟我一個人，能做的事確實有限。",
  ui_story_5089_50890501_30_dialog_content = "我自小在鄴王麾下長大，只知揮劍和聽命行事。",
  ui_story_5089_50890501_31_dialog_content = "如果這點本事能派上用場，PlayerName閣下，請為我下令。",
  ui_story_5089_50890501_32_dialog_content = "先把妳的這種想法丟掉。作為代替……",
  ui_story_5089_50890501_33_dialog_content = "「我們是互相幫助的朋友」。把這句話記在心裡吧。",
  ui_story_5089_50890501_34_dialog_content = "……我還不曾有過朋友。",
  ui_story_5089_50890501_35_dialog_content = "丹棠要是聽見這句話，她會比我們先生氣的。",
  ui_story_5089_50890501_36_dialog_content = "殿下千金之軀，怎能與我這種人互稱朋友！唔——",
  ui_story_5089_50890501_37_dialog_content = "唉，好了，把手給我，別勉強自己，扶著我慢慢走。",
  ui_story_5089_50890501_38_dialog_content = "一起去王都吧。",
  ui_story_5089_50890502_1_dialog_content = "嗷——",
  ui_story_5089_50890502_2_dialog_content = "PlayerName閣下，妖魔都已清理完畢。",
  ui_story_5089_50890502_3_dialog_content = "這裡應該離城鎮不遠吧。",
  ui_story_5089_50890502_4_dialog_content = "距離王都只剩不到半個時辰的路程，周圍還有好幾個村子。",
  ui_story_5089_50890502_5_dialog_content = "不是說龍洲因為鎮邪大儀的存在，有人煙的地方不會有暗鬼嗎？",
  ui_story_5089_50890502_6_dialog_content = "這……",
  ui_story_5089_50890502_7_dialog_content = "之前李天閑也說撞見過暗鬼。",
  ui_story_5089_50890502_8_dialog_content = "希望只是巧合……我們現在沒功夫處理更多麻煩事了，繼續趕路吧。",
  ui_story_5089_50890502_9_dialog_content = "是。",
  ui_story_5089_50890502_10_dialog_content = "那邊有什麼嗎？",
  ui_story_5089_50890502_11_dialog_content = "嗯？",
  ui_story_5089_50890502_12_dialog_content = "感覺妳的視線一直往那邊飄。",
  ui_story_5089_50890502_13_dialog_content = "那邊是我年幼時住過的村子。",
  ui_story_5089_50890502_14_dialog_content = "那不就是阿玖的家鄉嗎？要不要回去看看？",
  ui_story_5089_50890502_15_dialog_content = "不必了，我早已沒了家人，與村裡人也不算熟悉。",
  ui_story_5089_50890502_16_dialog_content = "剩下那兩座茅屋，也早已稱不上是家。",
  ui_story_5089_50890502_17_dialog_content = "正事要緊。",
  ui_story_5089_50890502_18_dialog_content = "PlayerName閣下，看，前方就是鄴國王都——璟良城。",
  ui_story_5089_50890502_19_dialog_content = "……",
  ui_story_5089_50890502_20_dialog_content = "（我本以為見識過濟國王宮的金裝玉砌後，不會再對什麼景象大驚小怪。）",
  ui_story_5089_50890502_21_dialog_content = "（但璟良城，屋頂有龍形的機關噴雲吐霧，街上有鳳狀的銅鳥傳消寄息。）",
  ui_story_5089_50890502_22_dialog_content = "<color=#e8d9bb>街衢洞達，工坊百千。紅塵四合，煙雲相連。</color>",
  ui_story_5089_50890502_23_dialog_content = "<color=#e8d9bb>不像皓津金翠珠玉，嬌鳥啼花的綺麗奢靡，在滿城的金屬色裡，自有一番工巧乾坤。</color>",
  ui_story_5089_50890502_24_dialog_content = "<color=#e8d9bb>轟隆隆——！</color>",
  ui_story_5089_50890502_25_dialog_content = "什麼聲音？！",
  ui_story_5089_50890502_26_dialog_content = "是火龍輦。",
  ui_story_5089_50890502_27_dialog_content = "PlayerName閣下可注意到，周圍街道的地上有何特異之處？",
  ui_story_5089_50890502_28_dialog_content = "你說嵌在地板上的那兩條金屬軌道？我們一路過來的時候似乎也偶爾能看到。",
  ui_story_5089_50890502_29_dialog_content = "有些眼熟，很像是我知道的某種東西……",
  ui_story_5089_50890502_30_dialog_content = "火龍輦是多年前朝中一名為「候風」的大人改良的機關車，",
  ui_story_5089_50890502_31_dialog_content = "透過水火能術彼此影響產生的能量為能源，哪怕裝載大量貨物也依舊能驅動車身。",
  ui_story_5089_50890502_32_dialog_content = "缺點是消耗的能源太多，還只能在專門的軌道上行駛。",
  ui_story_5089_50890502_33_dialog_content = "所以現在大多只由王宮統一籌畫，交給大型工坊的主人出資建設。",
  ui_story_5089_50890502_34_dialog_content = "負責建設軌道的工坊主便可優先租用火龍輦，進行貨物運輸。",
  ui_story_5089_50890502_35_dialog_content = "所以果然是……蒸汽火車？！",
  ui_story_5089_50890502_36_dialog_content = "那是何物？",
  ui_story_5089_50890502_37_dialog_content = "是艾斯特拉一種類似的東西。不過竟然能一個人做出來，那個候風大人真厲害啊。",
  ui_story_5089_50890502_38_dialog_content = "郡主也曾說過一樣的話。",
  ui_story_5089_50890502_39_dialog_content = "她說從所造之物上可以看出，候風卿其人極有才幹，天賦怕不在璇極大人之下。",
  ui_story_5089_50890502_40_dialog_content = "據說，他還曾試製過能夠在空中穩定承載多人飛行的巨鳶。",
  ui_story_5089_50890502_41_dialog_content = "可惜後來因黨爭獲罪，不知所蹤，相關的研發就停了下來。",
  ui_story_5089_50890502_42_dialog_content = "真可惜，要是能完善的話，一定會變成很厲害的東西。",
  ui_story_5089_50890502_43_dialog_content = "不過阿玖知道的真清楚，我還以為妳不會關心這種事。",
  ui_story_5089_50890502_44_dialog_content = "都是丹棠殿下告訴我的。",
  ui_story_5089_50890502_45_dialog_content = "她還說若非她當時年幼不懂朝中事，定會想方設法留下這種人才。",
  ui_story_5089_50890502_46_dialog_content = "哈哈，確實是丹棠的風格。",
  ui_story_5089_50890502_47_dialog_content = "好了，我們也得努力了。",
  ui_story_5089_50890502_48_dialog_content = "為了讓鄴國不必再失去璇極這樣的人才，和丹棠這麼盡職盡責的郡主。",
  ui_story_5089_50890502_49_dialog_content = "首先得先想辦法見她們一面……",
  ui_story_5089_50890502_50_dialog_content = "大王親自下令羈押的犯人，一般會關在王宮外圍的天牢裡。",
  ui_story_5089_50890502_51_dialog_content = "雖說守衛眾多，但只要有PlayerName閣下從旁相助，哪怕我折在裡面，也定能將璇極大人劫出。",
  ui_story_5089_50890502_52_dialog_content = "一上來就用這麼激進的手段？！",
  ui_story_5089_50890502_53_dialog_content = "PlayerName閣下說要我幫忙，難道不是叫我成為你的刀劍的意思？",
  ui_story_5089_50890502_54_dialog_content = "但我沒打算變成朝廷欽犯！更不打算叫妳去死！",
  ui_story_5089_50890502_55_dialog_content = "一定還有別的辦法，總之先去那個什麼天牢看看。",
  ui_story_5089_50890502_56_dialog_content = "要是他們敢傷害璇極……到時候再動用最後的手段。",
  ui_story_5089_50890502_57_dialog_content = "說起來，在璟良，認識阿玖的人一定很多吧。",
  ui_story_5089_50890502_58_dialog_content = "在大王身邊時，我也一直擔任暗衛，鮮少露面，最多只與同僚有接觸。",
  ui_story_5089_50890502_59_dialog_content = "但大部分人應當只記得我這張面具，或許連我是男是女都弄不清。",
  ui_story_5089_50890502_60_dialog_content = "畢竟他們背後提起我時，都只用「鬼面閻王」代稱。",
  ui_story_5089_50890502_61_dialog_content = "所以如果PlayerName閣下有所擔憂……",
  ui_story_5089_50890502_62_dialog_content = "這樣就好。",
  ui_story_5089_50890502_63_dialog_content = "嗯，好……雖然我覺得從某種意義上來說，這樣大概會更顯眼。",
  ui_story_5089_50890502_64_dialog_content = "果然這張臉不堪入目……我這就去找塊面紗遮擋一二。",
  ui_story_5089_50890502_65_dialog_content = "不需要！妳這種認知是從哪來的！完全相反，妳的臉非常——非常……",
  ui_story_5089_50890502_66_dialog_content = "非常美。",
  ui_story_5089_50890502_67_dialog_content = "嗯？",
  ui_story_5089_50890502_68_dialog_content = "算了，不用在意這種事，快走吧。",
  ui_story_5089_50890502_69_dialog_content = "此處乃王宮重地，閒雜人等，速速退開。",
  ui_story_5089_50890502_70_dialog_content = "果然想直接進去是不可能的啊。",
  ui_story_5089_50890502_71_dialog_content = "那就由我暗中潛入……",
  ui_story_5089_50890502_72_dialog_content = "這個方案放到最後再說！",
  ui_story_5089_50890502_73_dialog_content = "對了，我還帶著璇極的機關鳥，要是能引開守衛，說不定能用它和璇極溝通。",
  ui_story_5089_50890502_74_dialog_content = "引開守衛就由我——",
  ui_story_5089_50890502_75_dialog_content = "等等——糟糕！",
  ui_story_5089_50890502_76_dialog_content = "<color=#e8d9bb>一不注意，剛剛取出的機關鳥突然脫手。</color>",
  ui_story_5089_50890502_77_dialog_content = "<color=#e8d9bb>遵循早已設定好的程式，為了尋找璇極直直地朝宮門衝去——</color>",
  ui_story_5089_50890502_78_dialog_content = "完了——咦？",
  ui_story_5089_50890502_79_dialog_content = "<color=#e8d9bb>不知從何處閃過一道金光。</color>",
  ui_story_5089_50890502_80_dialog_content = "<color=#e8d9bb>兩名守衛竟像是完全沒注意到異常似的，任由機關鳥越過了大門。</color>",
  ui_story_5089_50890502_81_dialog_content = "……還需要我引開守衛嗎？",
  ui_story_5089_50890502_82_dialog_content = "這個……",
  ui_story_5089_50890502_83_dialog_content = "<color=#e8d9bb>宮門內突然傳來了些許響動。</color>",
  ui_story_5089_50890502_84_dialog_content = "敢問，可是有貴客在此？",
  ui_story_5089_50890502_85_dialog_content = "妳是？",
  ui_story_5089_50890502_86_dialog_content = "請隨婢來。",
  ui_story_5089_50890502_87_dialog_content = "璇極大人在等您。",
  ui_story_5089_50890502_88_dialog_content = "PlayerName閣下，春朔一別，我們也是許久未見了啊。",
  ui_story_5089_50890502_89_dialog_content = "玖姑娘也是，最近都還好嗎？",
  ui_story_5089_50890502_90_dialog_content = "璇極妳才是！這段時間過的怎麼樣，沒被欺負吧？",
  ui_story_5089_50890502_91_dialog_content = "我當然——哎呀，這欄杆豎在這太礙事了，撤了撤了。",
  ui_story_5089_50890502_92_dialog_content = "……咦？",
  ui_story_5089_50890502_93_dialog_content = "來來來，進來坐下說。你們都還沒吃午飯吧，正好。",
  ui_story_5089_50890502_94_dialog_content = "千技、千巧，去尚食局看看。",
  ui_story_5089_50890502_95_dialog_content = "桔槔卿之前跟我打賭，輸給我一條鮮魚，說好今天帶來。",
  ui_story_5089_50890502_96_dialog_content = "正好叫廚師做一道豉汁蒸魚。",
  ui_story_5089_50890502_97_dialog_content = "是。",
  ui_story_5089_50890502_98_dialog_content = "璇極……妳這是……",
  ui_story_5089_50890502_99_dialog_content = "哎，你們別笑話，宮裡頭什麼都好，就是想吃這一口鮮哪，難。",
  ui_story_5089_50890502_100_dialog_content = "……",
  ui_story_5089_50890502_101_dialog_content = "我現在覺得，抱著劫獄的覺悟來到這裡的我們完全是個笑話。",
  ui_story_5089_50890502_102_dialog_content = "妳真的是被抓進來的？這裡又真的是監牢嗎？",
  ui_story_5089_50890502_103_dialog_content = "哈哈哈，當然了，沒看我這酒葫蘆都空啦。",
  ui_story_5089_50890502_104_dialog_content = "我再怎麼說也曾於宮內任職，在這裡交了不少朋友，還有師門同窗照拂。",
  ui_story_5089_50890502_105_dialog_content = "大王再怎麼惱我，也不好在正式定罪之前與我為難。",
  ui_story_5089_50890502_106_dialog_content = "只是畢竟是戴罪之身，他們怎麼都不肯替我買酒，所以我現在也只能為你們倒一杯清茶。",
  ui_story_5089_50890502_107_dialog_content = "PlayerName閣下、玖姑娘。",
  ui_story_5089_50890502_108_dialog_content = "能來到這裡，想必一路多有不平。我以茶代酒，敬兩位一杯。",
  ui_story_5089_50890502_109_dialog_content = "多謝你們惦念。",
  ui_story_5089_50890502_110_dialog_content = "沒想到艾斯特拉大陸之行，最大的收穫並非燭陰火，而是珍貴的摯友啊。",
  ui_story_5089_50890502_111_dialog_content = "倒……倒也不值得這麼鄭重。",
  ui_story_5089_50890502_112_dialog_content = "不過，璇極妳知不知道燭陰火現在在誰手上？還有丹棠和——",
  ui_story_5089_50890502_113_dialog_content = "噓。",
  ui_story_5089_50890502_114_dialog_content = "我現在不過一介囚犯，外面的事就算妳和我說了也沒用。",
  ui_story_5089_50890502_115_dialog_content = "而且你看，我在這裡茶來伸手飯來張口，自在得都快樂不思蜀了。",
  ui_story_5089_50890502_116_dialog_content = "其餘事，與我何干？",
  ui_story_5089_50890502_117_dialog_content = "騙人。",
  ui_story_5089_50890502_118_dialog_content = "喔？",
  ui_story_5089_50890502_119_dialog_content = "這裡不是一塊機巧零件都沒有嗎？",
  ui_story_5089_50890502_120_dialog_content = "說璇極會覺得這種環境舒服，誰會信啊。",
  ui_story_5089_50890502_121_dialog_content = "哈哈，PlayerName公子還是如此耿直。",
  ui_story_5089_50890502_122_dialog_content = "那麼你聽好了。",
  ui_story_5089_50890502_123_dialog_content = "抓我是大王親旨，接下來我的生死，也只繫於大王一人之手。",
  ui_story_5089_50890502_124_dialog_content = "便是靠著玖姑娘的高強武藝強行越獄，也依舊名不正，言不順。",
  ui_story_5089_50890502_125_dialog_content = "但妳一定知道些什麼。我們現在該怎麼辦？",
  ui_story_5089_50890502_126_dialog_content = "現在還不是能考慮「怎麼辦」的時候。",
  ui_story_5089_50890502_127_dialog_content = "雖然我不好對外面的事發表意見，但好歹當過幾天謀士，與你分享些經驗還是可以的。",
  ui_story_5089_50890502_128_dialog_content = "比如說，若想謀事，眼界粗淺，力有不濟者方謀之以術。",
  ui_story_5089_50890502_129_dialog_content = "上上之選，乃是謀之以勢。",
  ui_story_5089_50890502_130_dialog_content = "順勢而為，自有天助。",
  ui_story_5089_50890502_131_dialog_content = "但前提是，你要放寬視野，看清那隱約而來的浪潮走向。",
  ui_story_5089_50890502_132_dialog_content = "才能在所需的「勢」到達之時，抓住它。",
  ui_story_5089_50890502_133_dialog_content = "正如機關造物，牽一髮而動全身。",
  ui_story_5089_50890502_134_dialog_content = "一個再簡單不過的動作，都需要數個結構精準配合。",
  ui_story_5089_50890502_135_dialog_content = "說不準哪個細小的零件失靈，就會拖累整個機關一同崩潰。",
  ui_story_5089_50890502_136_dialog_content = "可是……我連該去看什麼都不知道。",
  ui_story_5089_50890502_137_dialog_content = "那就看看身邊如何？",
  ui_story_5089_50890502_138_dialog_content = "比如說，現在偏偏是你們兩位站在我面前。這真的不是誰的特意安排嗎？",
  ui_story_5089_50890502_139_dialog_content = "！",
  ui_story_5089_50890502_140_dialog_content = "再比如說，雖然玖姑娘與我們相識已久……",
  ui_story_5089_50890502_141_dialog_content = "但你可知道她所從何來？",
  ui_story_5089_50890502_142_dialog_content = "璇極大人，菜已備好。",
  ui_story_5089_50890502_143_dialog_content = "只是大王身邊的暗衛剛剛前來，氣勢洶洶地要召您問話。",
  ui_story_5089_50890502_144_dialog_content = "千巧已經去了前面擋著，但怕是等不了多久，您說……",
  ui_story_5089_50890502_145_dialog_content = "我知道了。",
  ui_story_5089_50890502_146_dialog_content = "這審問也真是，早不來晚不來，偏偏午飯時候來。",
  ui_story_5089_50890502_147_dialog_content = "害得PlayerName閣下和玖姑娘都享不了這口福。",
  ui_story_5089_50890502_148_dialog_content = "唉，但也沒辦法。",
  ui_story_5089_50890502_149_dialog_content = "……璇極，要不然妳和我們一起走吧。",
  ui_story_5089_50890502_150_dialog_content = "我們不久前才親眼看到，鄴王身邊的人和綴戶待在一起，他們——",
  ui_story_5089_50890502_151_dialog_content = "千技，送客。",
  ui_story_5089_50890502_152_dialog_content = "璇極！",
  ui_story_5089_50890502_153_dialog_content = "好啦好啦，快走吧。我有我該應付的麻煩，你也有你的事要辦吧。",
  ui_story_5089_50890502_154_dialog_content = "我相信PlayerName閣下。",
  ui_story_5089_50890502_155_dialog_content = "你一定能看清「勢」之所在。",
  ui_story_5089_50890601_1_dialog_content = "<color=#e8d9bb>千技駕著馬車將我們送出城後就離開了。</color>",
  ui_story_5089_50890601_2_dialog_content = "結果又只剩我們兩個人了。",
  ui_story_5089_50890601_3_dialog_content = "璇極說了那麼一大堆，究竟是什麼意思……",
  ui_story_5089_50890601_4_dialog_content = "<color=#e8d9bb>咕～</color>",
  ui_story_5089_50890601_5_dialog_content = "……",
  ui_story_5089_50890601_6_dialog_content = "說起來，我們今天還什麼東西都沒吃呢。",
  ui_story_5089_50890601_7_dialog_content = "我去村子裡找戶人家問問，能不能花錢請他們做頓便飯。",
  ui_story_5089_50890601_8_dialog_content = "PlayerName閣下請稍等。",
  ui_story_5089_50890601_9_dialog_content = "好……咦？",
  ui_story_5089_50890601_10_dialog_content = "這裡……有村子嗎？",
  ui_story_5089_50890601_11_dialog_content = "近來米價高，機會難得，小老兒家稍好點的糧食都賣給了過路的濟國行商。",
  ui_story_5089_50890601_12_dialog_content = "只剩下自家吃的一點陳年糙米，做了點粥飯，也不知道合不合貴人的胃口……",
  ui_story_5089_50890601_13_dialog_content = "請別在意，我們餓了半天，能有飯吃已經很好了。",
  ui_story_5089_50890601_14_dialog_content = "這位大人怎麼不坐下來吃啊？可是還有什麼沒照顧到？",
  ui_story_5089_50890601_15_dialog_content = "我就不必了。",
  ui_story_5089_50890601_16_dialog_content = "不吃點東西，身體會撐不住的喔。",
  ui_story_5089_50890601_17_dialog_content = "無妨，以前執行任務時我曾三日不曾進食，亦不影響揮劍。",
  ui_story_5089_50890601_18_dialog_content = "況且我貌如夜叉，不好嚇到旁人。",
  ui_story_5089_50890601_19_dialog_content = "關於這個……",
  ui_story_5089_50890601_20_dialog_content = "這話，還有這幅面具……難道妳是……九妹？",
  ui_story_5089_50890601_21_dialog_content = "誰？",
  ui_story_5089_50890601_22_dialog_content = "……是我。",
  ui_story_5089_50890601_23_dialog_content = "許久未見了，李伯。",
  ui_story_5089_50890601_24_dialog_content = "哎呦，哎呦！妳還活著啊！",
  ui_story_5089_50890601_25_dialog_content = "當年見妳爹娘死得慘，連那倆官爺都死了，大傢伙都以為妳一定也沒命了呢。",
  ui_story_5089_50890601_26_dialog_content = "那時候妳才幾歲啊？現在都長這麼大了！",
  ui_story_5089_50890601_27_dialog_content = "妳一個小姑娘，這幾年是怎麼過的啊……",
  ui_story_5089_50890601_28_dialog_content = "我有幸受一位恩公收留，過得很好。",
  ui_story_5089_50890601_29_dialog_content = "那就好，那就好！",
  ui_story_5089_50890601_30_dialog_content = "等著，李伯再給妳拿點醃菜去，坐下來吃點啊。",
  ui_story_5089_50890601_31_dialog_content = "這裡是阿玖的家鄉啊。",
  ui_story_5089_50890601_32_dialog_content = "勉強算是。",
  ui_story_5089_50890601_33_dialog_content = "我家原本住在一個更偏僻的村子，搬來這裡，是為避禍。",
  ui_story_5089_50890601_34_dialog_content = "避禍？",
  ui_story_5089_50890601_35_dialog_content = "我當時還不到十歲，還記得的也不太多。",
  ui_story_5089_50890601_36_dialog_content = "大概是哪個癖好獨特的大人看中了我的臉，想買回去做個玩意兒。",
  ui_story_5089_50890601_37_dialog_content = "但爹娘不願，他們便幾次三番找我家麻煩，我們便逃到了這裡。",
  ui_story_5089_50890601_38_dialog_content = "從那之後，爹娘就給我戴上了面具，叫我跟大家說自己貌似夜叉，見不得人。",
  ui_story_5089_50890601_39_dialog_content = "怎麼這樣……",
  ui_story_5089_50890601_40_dialog_content = "戴上面具也好，畢竟確是我給家中添了麻煩，而且我本也不擅長和人說話。",
  ui_story_5089_50890601_41_dialog_content = "只是爹娘似乎總是心裡有愧。",
  ui_story_5089_50890601_42_dialog_content = "每次村裡其他孩子叫我醜八怪，阿娘都會抱著我給我唱詩。",
  ui_story_5089_50890601_43_dialog_content = "阿爹還會把捨不得吃的甜瓜給我。",
  ui_story_5089_50890601_44_dialog_content = "啊，阿玖之前唱的那首歌……是專門為妳編的吧？妳爹娘一定很愛妳。",
  ui_story_5089_50890601_45_dialog_content = "後來呢？",
  ui_story_5089_50890601_46_dialog_content = "PlayerName閣下應該也看到了，這村子西邊有一座山。",
  ui_story_5089_50890601_47_dialog_content = "呃……哪座？",
  ui_story_5089_50890601_48_dialog_content = "我們出去說吧。",
  ui_story_5089_50890601_49_dialog_content = "九妹？妳們這就要走了？",
  ui_story_5089_50890601_50_dialog_content = "我們要去礦山那邊看看。",
  ui_story_5089_50890601_51_dialog_content = "行，只是早幾年礦就被採完了，勞工營也撤了。",
  ui_story_5089_50890601_52_dialog_content = "之後那塊地上建了座大工坊，但也沒見做出什麼玩意來。",
  ui_story_5089_50890601_53_dialog_content = "村上的年輕人想去問問招不招工，也沒見到個人影，大概是廢棄了，沒什麼好看的。",
  ui_story_5089_50890601_54_dialog_content = "倒是九妹……",
  ui_story_5089_50890601_55_dialog_content = "還有事？",
  ui_story_5089_50890601_56_dialog_content = "沒，沒什麼……唉，就是想說這年頭，大家都不容易。",
  ui_story_5089_50890601_57_dialog_content = "妳既然有這運道，就好好活著吧。",
  ui_story_5089_50890601_58_dialog_content = "妳爹娘泉下有知，也能高興。",
  ui_story_5089_50890601_59_dialog_content = "……好。",
  ui_story_5089_50890601_60_dialog_content = "阿玖說的就是那座光禿禿的山？",
  ui_story_5089_50890601_61_dialog_content = "對。在大王繼位之前，這周圍都是他的封地，包括那座礦山。",
  ui_story_5089_50890601_62_dialog_content = "他在山下設了一座勞工營，常收些流民囚犯去做工。",
  ui_story_5089_50890601_63_dialog_content = "那天，有兩名官兵押送一死囚去往勞工營，但中途憊懶，便就近找了我家借宿。",
  ui_story_5089_50890601_64_dialog_content = "爹娘伺候了他們半日，用家中存糧給他們換了酒，又被他們支使去給那死囚送飯。",
  ui_story_5089_50890601_65_dialog_content = "結果他們酒勁上頭，非要看我的真容，強扯掉了我的面具，又想欺侮我。",
  ui_story_5089_50890601_66_dialog_content = "多虧當時有人路過，幫著推倒了籬笆，將那兩人壓死了。",
  ui_story_5089_50890601_67_dialog_content = "但他大抵是不願惹上麻煩，一直藏在陰影裡沒有露面，當時我也沒有餘裕細想。",
  ui_story_5089_50890601_68_dialog_content = "我只意識到自己又闖了大禍，想要去尋爹娘……",
  ui_story_5089_50890601_69_dialog_content = "卻只看到他們的屍身倒在血泊中。",
  ui_story_5089_50890601_70_dialog_content = "還在冒熱氣的白粥灑得滿地，而那名死囚已掙脫鎖鏈逃跑了。",
  ui_story_5089_50890601_71_dialog_content = "我有時候會想，「命運弄人」或許是確有其事。",
  ui_story_5089_50890601_72_dialog_content = "被其他人叫醜八怪，小妖魔，挨打挨罵的時候我都沒有怕過。",
  ui_story_5089_50890601_73_dialog_content = "唯獨那天，見到爹娘屍身的那一次，我怕了。",
  ui_story_5089_50890601_74_dialog_content = "但也唯獨那次，不會再有阿娘唱詩哄我了。",
  ui_story_5089_50890601_75_dialog_content = "抱歉，說遠了，那之後——",
  ui_story_5089_50890601_76_dialog_content = "阿玖！",
  ui_story_5089_50890601_77_dialog_content = "嗯？",
  ui_story_5089_50890601_78_dialog_content = "如果妳不喜歡，不告訴我這些事也沒關係的。",
  ui_story_5089_50890601_79_dialog_content = "沒什麼喜不喜歡的。",
  ui_story_5089_50890601_80_dialog_content = "我雖然不明白璇極大人的意思，但也知道她每一句話都定有其意義。",
  ui_story_5089_50890601_81_dialog_content = "她既然提了我的來處，我就該將這些事說與你聽。",
  ui_story_5089_50890601_82_dialog_content = "還要多謝PlayerName閣下不嫌我說得瑣碎。",
  ui_story_5089_50890601_83_dialog_content = "……說這種事怎麼可能真的無動於衷。",
  ui_story_5089_50890601_84_dialog_content = "如果真覺得無所謂……",
  ui_story_5089_50890601_85_dialog_content = "誰會一直記得那一碗灑在地上的白粥啊！",
  ui_story_5089_50890601_86_dialog_content = "PlayerName閣下，難道生氣了？",
  ui_story_5089_50890601_87_dialog_content = "真虧妳看得出來啊。",
  ui_story_5089_50890601_88_dialog_content = "對，我非常生氣。",
  ui_story_5089_50890601_89_dialog_content = "對不起，這故事聽起來很不快吧。",
  ui_story_5089_50890601_90_dialog_content = "但……我很快就報仇了。",
  ui_story_5089_50890601_91_dialog_content = "在那之後，我拿了官兵隨身的雁翎刀，追了那死囚一天一夜。",
  ui_story_5089_50890601_92_dialog_content = "但沒想到他竟闖入了勞工營，試圖刺殺當時的鄴王殿下。",
  ui_story_5089_50890601_93_dialog_content = "當我趕到時，他已然伏法。",
  ui_story_5089_50890601_94_dialog_content = "殿下問了我的來意，知道我家人已逝，便收留了我，賜名為「玖」。",
  ui_story_5089_50890601_95_dialog_content = "不光替我報了仇，還允我在他府中安身，教我讀書寫字，習武強身。",
  ui_story_5089_50890601_96_dialog_content = "所以我無論如何，都想報此大恩。",
  ui_story_5089_50890601_97_dialog_content = "左右除此之外，我也沒有其他揮劍……亦或是活下去的理由了。",
  ui_story_5089_50890601_98_dialog_content = "我不是在說這個。",
  ui_story_5089_50890601_99_dialog_content = "妳口口聲聲報仇、報恩。",
  ui_story_5089_50890601_100_dialog_content = "但除此之外，妳的心情呢？妳自己想做的事呢？",
  ui_story_5089_50890601_101_dialog_content = "之前替我擋下攻擊也好，若無其事說自己去劫獄也好，覺得自己的心情不重要也好。",
  ui_story_5089_50890601_102_dialog_content = "妳憑什麼總是一臉理所當然地，把犧牲自己當成無謂的小事？",
  ui_story_5089_50890601_103_dialog_content = "就算妳再強，也依然是血肉之軀，會受傷、會疼痛、會難過，一不小心也真的會死。",
  ui_story_5089_50890601_104_dialog_content = "我並沒有那麼想，只是有時為了完成任務……",
  ui_story_5089_50890601_105_dialog_content = "好的，我懂了，我開始明白該怎麼和妳說話了。",
  ui_story_5089_50890601_106_dialog_content = "對不起，丹棠，我錯怪妳了，我親身體驗到阿玖她有多頑固了。",
  ui_story_5089_50890601_107_dialog_content = "接下來，我就用妳能聽懂的話跟妳說吧。",
  ui_story_5089_50890601_108_dialog_content = "嗯？",
  ui_story_5089_50890601_109_dialog_content = "妳奮不顧身的犧牲精神讓我很困擾。",
  ui_story_5089_50890601_110_dialog_content = "空裔是愛好和平的種族，所以我不想見血，不想要妳受傷。",
  ui_story_5089_50890601_111_dialog_content = "我還想把妳完完整整地還給丹棠。",
  ui_story_5089_50890601_112_dialog_content = "所以如果妳還願意聽我的命令，就給我牢牢遵循這條守則。",
  ui_story_5089_50890601_113_dialog_content = "「不管面對怎樣的狀況，都先好好珍惜妳自己。」",
  ui_story_5089_50890601_114_dialog_content = "我……",
  ui_story_5089_50890601_115_dialog_content = "我不想聽藉口，這種時候只需要回答「是」就行了。",
  ui_story_5089_50890601_116_dialog_content = "是，我會記住。",
  ui_story_5089_50890601_117_dialog_content = "但這條命令，可有期限？",
  ui_story_5089_50890601_118_dialog_content = "妳是不是完全沒聽懂我在說什麼？",
  ui_story_5089_50890601_119_dialog_content = "算了，非要說一個期限的話，我想想……",
  ui_story_5089_50890601_120_dialog_content = "就到，妳能不為報恩，也不為報仇地揮劍時為止吧。",
  ui_story_5089_50890601_121_dialog_content = "嗯？",
  ui_story_5089_50890601_122_dialog_content = "就算有意見我也不會改命令的。",
  ui_story_5089_50890601_123_dialog_content = "不，只是這句話，師父也曾經跟我說過。",
  ui_story_5089_50890601_124_dialog_content = "師父？",
  ui_story_5089_50890601_125_dialog_content = "我的劍術，師從天下第一劍客。",
  ui_story_5089_50890601_126_dialog_content = "他雖然說我是塊頑石，不願正式收我為徒，但也教了我許多。",
  ui_story_5089_50890601_127_dialog_content = "只是唯獨師父自創的，據說足以開山分海的「驚霆劍」，他怎麼都不肯教我。",
  ui_story_5089_50890601_128_dialog_content = "他說那並非實在的劍招，也教不了我。",
  ui_story_5089_50890601_129_dialog_content = "只有我能不為報恩，也不為報仇地揮劍時，才能有資格悟得它。",
  ui_story_5089_50890601_130_dialog_content = "好神祕啊，就沒有其他線索——唔！",
  ui_story_5089_50890601_131_dialog_content = "抱歉，PlayerName閣下，有人來了。",
  ui_story_5089_50890601_132_dialog_content = "唔……綴戶？！",
  ui_story_5089_50890601_133_dialog_content = "為什麼會出現在這裡……阿玖，我們跟上去！",
  ui_story_5089_50890601_134_dialog_content = "她進了那座工坊？我們也——",
  ui_story_5089_50890601_135_dialog_content = "嘎！",
  ui_story_5089_50890601_136_dialog_content = "有機關獸守衛，阿玖小心！",
  ui_story_5089_50890602_1_dialog_content = "只是一座廢棄工坊，怎麼可能守衛這麼嚴密。",
  ui_story_5089_50890602_2_dialog_content = "這裡還有不少人活動的痕跡，加上綴戶在這裡……",
  ui_story_5089_50890602_3_dialog_content = "這裡大概是駿命的據點。",
  ui_story_5089_50890602_4_dialog_content = "請小心，包括地下部分，這座工坊內部空間極大，路線又錯綜複雜。",
  ui_story_5089_50890602_5_dialog_content = "一旦迷路會很麻煩。",
  ui_story_5089_50890602_6_dialog_content = "真巧，我對這種建築很有經驗。感應能力很方便探路。",
  ui_story_5089_50890602_7_dialog_content = "感應——",
  ui_story_5089_50890602_8_dialog_content = "啊，這裡儲存了好多武器！",
  ui_story_5089_50890602_9_dialog_content = "駿命到底想做什麼……咦？",
  ui_story_5089_50890602_10_dialog_content = "前面角落的那個房間裡，似乎關著一個人。",
  ui_story_5089_50890602_11_dialog_content = "！",
  ui_story_5089_50890602_12_dialog_content = "<color=#e8d9bb>進門的瞬間，一股惡臭撲面而來。</color>",
  ui_story_5089_50890602_13_dialog_content = "<color=#e8d9bb>藏在角落裡的人影顫抖了一下，往牆邊縮得更深了。</color>",
  ui_story_5089_50890602_14_dialog_content = "看周圍的環境，他應該被關在這裡很久了。",
  ui_story_5089_50890602_15_dialog_content = "你是誰？為什麼會在這裡？",
  ui_story_5089_50890602_16_dialog_content = "啊——啊——",
  ui_story_5089_50890602_17_dialog_content = "嗚……哈哈……嗚哇啊——",
  ui_story_5089_50890602_18_dialog_content = "不行，無法溝通，好像已經癡傻了。",
  ui_story_5089_50890602_19_dialog_content = "我們先往深處探查一下這座工坊，然後再來想辦法救他……",
  ui_story_5089_50890602_20_dialog_content = "阿玖？妳還站在那裡幹什麼？",
  ui_story_5089_50890602_21_dialog_content = "怎麼會……您怎麼會在這裡……",
  ui_story_5089_50890602_22_dialog_content = "大王！",
  ui_story_5089_50890602_23_dialog_content = "妳說……這是鄴王？！",
  ui_story_5089_50890700_1_dialog_content = "<color=#e8d9bb>翌日。</color>",
  ui_story_5089_50890700_2_dialog_content = "……殿下，丹棠殿下？",
  ui_story_5089_50890700_3_dialog_content = "嗯？有事？",
  ui_story_5089_50890700_4_dialog_content = "不是您托我打聽芳澤、韶欽那兩位郡主的消息嗎？",
  ui_story_5089_50890700_5_dialog_content = "啊，對。阿姐和阿妹她們還好嗎？",
  ui_story_5089_50890700_6_dialog_content = "聽說不久前鄴王派她們去祭祖，這段時間都要待在離宮，不回璟良。",
  ui_story_5089_50890700_7_dialog_content = "怪不得……",
  ui_story_5089_50890700_8_dialog_content = "您一直在這兒發呆，怎麼早膳都沒吃？嘖嘖嘖，可惜這些好菜都涼透了。",
  ui_story_5089_50890700_9_dialog_content = "我沒什麼胃口。",
  ui_story_5089_50890700_10_dialog_content = "要發愁的事兒再多，咱都不該跟自個身子過不去對吧。",
  ui_story_5089_50890700_11_dialog_content = "更何況您現在被困在這宮裡，再愁也沒用，還不是只能指望著PlayerName跟玖姑娘。",
  ui_story_5089_50890700_12_dialog_content = "昨兒不是有婢女傳信過來，說他們一切都好嗎？",
  ui_story_5089_50890700_13_dialog_content = "還是說您不相信他們？",
  ui_story_5089_50890700_14_dialog_content = "我自然相信。倒是你……",
  ui_story_5089_50890700_15_dialog_content = "我還以為你早就會趁機溜了呢。",
  ui_story_5089_50890700_16_dialog_content = "瞧您說的。這宮裡有得吃，有得睡，可是頂頂好的日子。",
  ui_story_5089_50890700_17_dialog_content = "我都捨不得了，所以剛卜算了一卦，看看這日子能享受到何時。結果您猜怎麼著？",
  ui_story_5089_50890700_18_dialog_content = "卦象顯示，您這兒啊，還用得著在下。",
  ui_story_5089_50890700_19_dialog_content = "我拜託你當阿玖的替身，本就已是強人所難，怎麼還敢再麻煩你呢？",
  ui_story_5089_50890700_20_dialog_content = "等此間事了，我還得給你應得的酬勞——",
  ui_story_5089_50890700_21_dialog_content = "<color=#e8d9bb>轟！！</color>",
  ui_story_5089_50890700_22_dialog_content = "什麼聲音？！",
  ui_story_5089_50890700_23_dialog_content = "殿下，有人強闖內宮，還請您移步——唔。",
  ui_story_5089_50890700_24_dialog_content = "李天閑，你打暈他幹什麼？",
  ui_story_5089_50890700_25_dialog_content = "您看，用得著在下的地方，這不就來了？",
  ui_story_5089_50890700_26_dialog_content = "啊，啊——",
  ui_story_5089_50890700_27_dialog_content = "哈欠～啊，竟然已經天亮了。",
  ui_story_5089_50890700_28_dialog_content = "一夜都不敢睡……",
  ui_story_5089_50890700_29_dialog_content = "啊啊——",
  ui_story_5089_50890700_30_dialog_content = "唉，我們已經冒著風險，連夜帶你去鎮上看了好幾個大夫了。",
  ui_story_5089_50890700_31_dialog_content = "但都說你的癡症是中毒所致，而且毒性早已入骨，無藥可醫。",
  ui_story_5089_50890700_32_dialog_content = "啊嗚，啊嗚——",
  ui_story_5089_50890700_33_dialog_content = "你真的是鄴王本人嗎？如果是的話……",
  ui_story_5089_50890700_34_dialog_content = "事情可就不是一句麻煩能形容的了。",
  ui_story_5089_50890700_35_dialog_content = "還有阿玖昨天說的那些話，總讓我有種不祥的預感。",
  ui_story_5089_50890700_36_dialog_content = "這家醫館說不行嗎？",
  ui_story_5089_50890700_37_dialog_content = "但別灰心，阿玖，說不定其他大夫會有辦法呢，比如寫信問問厘青。",
  ui_story_5089_50890700_38_dialog_content = "或者找到丹棠說的那位「卜存子」——",
  ui_story_5089_50890700_39_dialog_content = "PlayerName閣下。",
  ui_story_5089_50890700_40_dialog_content = "如果宮裡那位不是真正的大王，那丹棠殿下將會如何？",
  ui_story_5089_50890700_41_dialog_content = "這個……",
  ui_story_5089_50890700_42_dialog_content = "我不僅深受大王之恩，丹棠殿下也對我照拂良多。",
  ui_story_5089_50890700_43_dialog_content = "殿下已親口解除了我的護衛之職，我或許沒資格對她的事多嘴。",
  ui_story_5089_50890700_44_dialog_content = "但如果我不能再保護她，PlayerName閣下……",
  ui_story_5089_50890700_45_dialog_content = "丹棠殿下的安危就拜託你了。",
  ui_story_5089_50890700_46_dialog_content = "對不起。",
  ui_story_5089_50890700_47_dialog_content = "說到阿玖……阿玖呢？！",
  ui_story_5089_50890700_48_dialog_content = "唔……我就知道！",
  ui_story_5089_50890700_49_dialog_content = "還好提前做了準備……",
  ui_story_5089_50890700_50_dialog_content = "李伯！可以麻煩你照顧一下這個人嗎？",
  ui_story_5089_50890700_51_dialog_content = "啊？行是行，只是您這麼急匆匆的，要去哪啊。",
  ui_story_5089_50890700_52_dialog_content = "去璟良！",
  ui_story_5089_50890700_53_dialog_content = "啊啊——",
  ui_story_5089_50890700_54_dialog_content = "大王，有刺客闖宮，內衛軍不敵，她馬上就要逼近正殿了！",
  ui_story_5089_50890700_55_dialog_content = "殿下，是霜刃大人。",
  ui_story_5089_50890700_56_dialog_content = "可需要我們出動？",
  ui_story_5089_50890700_57_dialog_content = "不必，本王就在這裡等她。",
  ui_story_5089_50890700_58_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5089_50890700_59_dialog_content = "站住！大王在此，不得近前！",
  ui_story_5089_50890700_60_dialog_content = "讓開。",
  ui_story_5089_50890700_61_dialog_content = "呃啊——",
  ui_story_5089_50890700_62_dialog_content = "<color=#e8d9bb>玖邁步踏入正殿，抬眼，與王座上之人對視。</color>",
  ui_story_5089_50890700_63_dialog_content = "看來本王確實培養出了一把好刀。",
  ui_story_5089_50890700_64_dialog_content = "闔宮上下，竟無人是你的對手。",
  ui_story_5089_50890700_65_dialog_content = "別裝了。",
  ui_story_5089_50890700_66_dialog_content = "我已經見到了真正的殿下，你這個假貨——",
  ui_story_5089_50890700_67_dialog_content = "從大王的位置上滾下來！",
  ui_story_5089_50890700_68_dialog_content = "喔，你見到了那個傻子。",
  ui_story_5089_50890700_69_dialog_content = "<color=#e8d9bb>噹！</color>",
  ui_story_5089_50890700_70_dialog_content = "<color=#e8d9bb>刀劍交擊，發出清脆的錚鳴。</color>",
  ui_story_5089_50890700_71_dialog_content = "竟敢對殿下出言不遜！",
  ui_story_5089_50890700_72_dialog_content = "呵，氣勢不錯。",
  ui_story_5089_50890700_73_dialog_content = "不愧是我麾下的第一劍客。",
  ui_story_5089_50890700_74_dialog_content = "你——！",
  ui_story_5089_50890700_75_dialog_content = "都出來，跟你們的首領練練。",
  ui_story_5089_50890700_76_dialog_content = "是！",
  ui_story_5089_50890700_77_dialog_content = "<color=#e8d9bb>暗衛從兩側包夾接近，鋒利的金屬絲破空而來。</color>",
  ui_story_5089_50890700_78_dialog_content = "<color=#e8d9bb>玖剛要閃身躲避，餘光卻在下一瞬捕捉到假鄴王的動作露出破綻。</color>",
  ui_story_5089_50890700_79_dialog_content = "——！",
  ui_story_5089_50890700_80_dialog_content = "<color=#e8d9bb>金屬絲貫穿了她的小腿，她的動作卻半分未停，劍尖刺向假鄴王的心臟！</color>",
  ui_story_5089_50890700_81_dialog_content = "妳從小就有這種壞習慣。",
  ui_story_5089_50890700_82_dialog_content = "<color=#e8d9bb>噹！</color>",
  ui_story_5089_50890700_83_dialog_content = "<color=#e8d9bb>劍鋒陷入鄴王袍內的軟甲，帶來片刻的滯澀。</color>",
  ui_story_5089_50890700_84_dialog_content = "該死——",
  ui_story_5089_50890700_85_dialog_content = "<color=#e8d9bb>玖即刻撤力，正要再度揮劍。</color>",
  ui_story_5089_50890700_86_dialog_content = "妳的劍很利，但只將鋒銳打磨到極致，代價則是劍身的易碎。",
  ui_story_5089_50890700_87_dialog_content = "我替妳取名為玖，可不是想要玉石俱焚的結局。",
  ui_story_5089_50890700_88_dialog_content = "！",
  ui_story_5089_50890700_89_dialog_content = "<color=#e8d9bb>十年前。</color>",
  ui_story_5089_50890700_90_dialog_content = "妳為了追殺親兇手，打著赤腳，獨自一人，不吃不喝地追到了這裡？",
  ui_story_5089_50890700_91_dialog_content = "哈哈哈，沒想到妳年紀小，志卻堅。",
  ui_story_5089_50890700_92_dialog_content = "但看妳如今饑腸轆轆，手腳滿是血泡，搖搖晃晃的樣子……",
  ui_story_5089_50890700_93_dialog_content = "便是真追上了仇人，怕是最多只能得個玉石俱焚的結局，這不好。",
  ui_story_5089_50890700_94_dialog_content = "……那也無妨，因為妳這條命除了報仇已再無意義？",
  ui_story_5089_50890700_95_dialog_content = "罷了，既然我替妳處理了仇人，送佛送上天，妳這條命就也由我接手吧。",
  ui_story_5089_50890700_96_dialog_content = "妳說妳叫九妹，這可算不上名字。",
  ui_story_5089_50890700_97_dialog_content = "從今後，妳就叫「玖」如何？",
  ui_story_5089_50890700_98_dialog_content = "是如玉的美石，卻又當比玉更堅。",
  ui_story_5089_50890700_99_dialog_content = "我還想要妳成為我手下的一把利刃，所以磨練自己可以，但可別輕易崩碎了。",
  ui_story_5089_50890700_100_dialog_content = "<color=#e8d9bb>玖晃神了一刹，便立刻有無數金屬線織成羅網，將她拖倒在地，壓在其中。</color>",
  ui_story_5089_50890700_101_dialog_content = "<color=#e8d9bb>面具掉落在地，她卻只看向假鄴王。</color>",
  ui_story_5089_50890700_102_dialog_content = "你……到底是誰？",
  ui_story_5089_50890700_103_dialog_content = "不是有人闖宮嗎？怎麼還有這麼多侍衛盯著這兒啊。",
  ui_story_5089_50890700_104_dialog_content = "你突然說要跑，我還以為你有什麼大計畫。",
  ui_story_5089_50890700_105_dialog_content = "見機行事，怎麼不算是計畫呢？",
  ui_story_5089_50890700_106_dialog_content = "丹棠殿下，雖然您不信在下的卦，但在下可是信的。",
  ui_story_5089_50890700_107_dialog_content = "PlayerName之前抽出的那「陰龍陰鼠」，明顯與現狀相合。",
  ui_story_5089_50890700_108_dialog_content = "可要是在下之後的測算沒錯，光靠PlayerName跟玖姑娘，還真解不了這困局。",
  ui_story_5089_50890700_109_dialog_content = "你的意思是？",
  ui_story_5089_50890700_110_dialog_content = "在下會將守衛引開，您趁機逃出宮去。",
  ui_story_5089_50890700_111_dialog_content = "後面嘛，就見機行事吧。",
  ui_story_5089_50890700_112_dialog_content = "等等，李天閑！",
  ui_story_5089_50890700_113_dialog_content = "誰在那邊！",
  ui_story_5089_50890700_114_dialog_content = "追！",
  ui_story_5089_50890700_115_dialog_content = "跟這個人真是說不明白！",
  ui_story_5089_50890700_116_dialog_content = "但現在也只能——",
  ui_story_5089_50890700_117_dialog_content = "郡主殿下，您要去哪？",
  ui_story_5089_50890700_118_dialog_content = "……",
  ui_story_5089_50890700_119_dialog_content = "璇極大人，外面——",
  ui_story_5089_50890700_120_dialog_content = "別吵，我在幹活呢。",
  ui_story_5089_50890700_121_dialog_content = "都什麼時候了，您怎麼還在擺弄瓦片？",
  ui_story_5089_50890700_122_dialog_content = "這可不是普通的瓦片，是我費心設計了好幾天的琉璃瓦片機關。",
  ui_story_5089_50890700_123_dialog_content = "PlayerName閣下成長了很多，但在偷奸耍滑這件事上，還是差了一點。",
  ui_story_5089_50890700_124_dialog_content = "您說什麼？",
  ui_story_5089_50890700_125_dialog_content = "我的意思是說，這間牢房只是表面上看不見機關零件。",
  ui_story_5089_50890700_126_dialog_content = "但在真正的機巧師手裡，板凳桌椅，房梁瓦片，都可以成為機巧的一部分。",
  ui_story_5089_50890700_127_dialog_content = "來看看，這便是靈感來自空裔，由我僅用屋內材料製作的，即興機關——移光靈瓦！",
  ui_story_5089_50890700_128_dialog_content = "您沒開玩笑吧？這東西有什麼效果？",
  ui_story_5089_50890700_129_dialog_content = "可以將射入的光，或是光能，引導到自己想要的位置。",
  ui_story_5089_50890700_130_dialog_content = "這要用在什麼地方呢？",
  ui_story_5089_50890700_131_dialog_content = "是啊，要用在什麼地方呢～",
  ui_story_5089_50890700_132_dialog_content = "十年前，一位高官為朝中爭鬥所累，墮為囚犯，被罰入礦山做苦工至死。",
  ui_story_5089_50890700_133_dialog_content = "但天不亡他，押送他的官差偷懶，非要在路上找人家借宿。",
  ui_story_5089_50890700_134_dialog_content = "那家的夫妻都是再普通不過的百姓，輕而易舉地被他偷襲，他也趁機逃脫。",
  ui_story_5089_50890700_135_dialog_content = "只是在逃出院子時，他發現那兩個豬狗不如的官兵竟要欺侮那對夫妻的女兒。",
  ui_story_5089_50890700_136_dialog_content = "他順手宰了那倆畜生，才順著原本的路線前往勞工營。",
  ui_story_5089_50890700_137_dialog_content = "當時坐鎮勞工營的親王稱得上是好人，卻也著實是個草包，一副藥下去就成了傻子。",
  ui_story_5089_50890700_138_dialog_content = "為彼此稍加易容，囚犯就替換了他的身分。",
  ui_story_5089_50890700_139_dialog_content = "而他身邊的人也都毫無忠心可言，就連主子悄悄換了個人都不知道。",
  ui_story_5089_50890700_140_dialog_content = "偏巧這時那對夫妻的女兒追來，說要替父母報仇。",
  ui_story_5089_50890700_141_dialog_content = "他這才知道，因自己下手太重，那對夫妻竟都死了。",
  ui_story_5089_50890700_142_dialog_content = "於是他收留了那女孩，也替自己養了一把忠心耿耿的好刀。",
  ui_story_5089_50890700_143_dialog_content = "你是……是你！",
  ui_story_5089_50890700_144_dialog_content = "<color=#e8d9bb>玖紅了眼睛，拚盡全力撐起身子，壓著她的金屬網線發出刺耳的聲響，竟是要被掙斷。</color>",
  ui_story_5089_50890700_145_dialog_content = "這個故事倒是早該告訴妳。",
  ui_story_5089_50890700_146_dialog_content = "事到如今，妳要為我殺了你父母之事報仇嗎？",
  ui_story_5089_50890700_147_dialog_content = "還是要為我救了妳，培養至今的事報恩？",
  ui_story_5089_50890700_148_dialog_content = "我……",
  ui_story_5089_50890700_149_dialog_content = "<color=#e8d9bb>劍第一次在玖的手中顫抖。</color>",
  ui_story_5089_50890700_150_dialog_content = "妳心心念念至今的事，到底算什麼呢？",
  ui_story_5089_50890700_151_dialog_content = "喝啊——！",
  ui_story_5089_50890700_152_dialog_content = "<color=#e8d9bb>一道亮光閃過。</color>",
  ui_story_5089_50890700_153_dialog_content = "<color=#e8d9bb>周邊的金屬線盡數崩裂，在漫天碎屑中，她不顧一切地揮出最後一劍。</color>",
  ui_story_5089_50890700_154_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5089_50890700_155_dialog_content = "<color=#e8d9bb>劍風裹挾著光能劈開了半邊宮殿，還未消散，一路橫掃，在磚石地板上留下深深的溝壑。</color>",
  ui_story_5089_50890700_156_dialog_content = "<color=#e8d9bb>鄴王卻不閃不避，便與劍光錯開，未被傷及分毫。</color>",
  ui_story_5089_50890700_157_dialog_content = "妳心有猶豫，連劍都拿不穩了嗎？",
  ui_story_5089_50890700_158_dialog_content = "<color=#e8d9bb>噹——</color>",
  ui_story_5089_50890700_159_dialog_content = "<color=#e8d9bb>玖的劍被鄴王挑飛出去，落進角落。</color>",
  ui_story_5089_50890700_160_dialog_content = "<color=#e8d9bb>片刻前。</color>",
  ui_story_5089_50890700_161_dialog_content = "殿下，如果您執意要走，屬下只能得罪了。",
  ui_story_5089_50890700_162_dialog_content = "真沒想到有一天，我要在鄴國王宮裡和自己的護衛戰鬥。",
  ui_story_5089_50890700_163_dialog_content = "但事到如今，我已經不會再退回去了。",
  ui_story_5089_50890700_164_dialog_content = "還有人在外面等著我。",
  ui_story_5089_50890700_165_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5089_50890700_166_dialog_content = "<color=#e8d9bb>不遠處的正殿突然被一股強大的光能劈開。</color>",
  ui_story_5089_50890700_167_dialog_content = "<color=#e8d9bb>緊接著，一道亮光閃過，那股強大的光能突然像被鎖定了一般直奔此處而來！</color>",
  ui_story_5089_50890700_168_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5089_50890700_169_dialog_content = "<color=#e8d9bb>城樓從正中被劈裂，將宮廷內衛和丹棠分開。</color>",
  ui_story_5089_50890700_170_dialog_content = "<color=#e8d9bb>亮光再度閃過，照向了一條出宮的路。</color>",
  ui_story_5089_50890700_171_dialog_content = "那個方向……璇璣卿？",
  ui_story_5089_50890700_172_dialog_content = "我就知道她才不會安分地坐牢。",
  ui_story_5089_50890700_173_dialog_content = "你也覺得，現在我還是出宮更好嗎。",
  ui_story_5089_50890700_174_dialog_content = "大王。",
  ui_story_5089_50890700_175_dialog_content = "何事？",
  ui_story_5089_50890700_176_dialog_content = "郡主殿下逃出宮去了。",
  ui_story_5089_50890700_177_dialog_content = "和郡主一同進宮的身分不明之人也不知所蹤。",
  ui_story_5089_50890700_178_dialog_content = "據追蹤的內衛回報，明明眼看著他鑽進了草叢，跟進去後卻只看見一隻糖人。",
  ui_story_5089_50890700_179_dialog_content = "還有……",
  ui_story_5089_50890700_180_dialog_content = "還有什麼事，直接說。",
  ui_story_5089_50890700_181_dialog_content = "還有「那邊」來的消息，近期就將起事。",
  ui_story_5089_50890700_182_dialog_content = "要我們務必在三天內將火器運抵。",
  ui_story_5089_50890700_183_dialog_content = "但工坊表示，要的量實在太大，而且濟國那邊也在催促我們完成之前的交易……",
  ui_story_5089_50890700_184_dialog_content = "知道了。",
  ui_story_5089_50890700_185_dialog_content = "此事之後再說。",
  ui_story_5089_50890700_186_dialog_content = "先將你們首領押下去，讓她好好冷靜冷靜吧。",
  ui_story_5089_50890700_187_dialog_content = "是。",
  ui_story_5089_50890700_188_dialog_content = "<color=#e8d9bb>碰。</color>",
  ui_story_5089_50890700_189_dialog_content = "<color=#e8d9bb>暗衛將玖丟進一個空房間，便離開了。</color>",
  ui_story_5089_50890700_190_dialog_content = "喲，這不是玖姑娘嗎？",
  ui_story_5089_50890700_191_dialog_content = "妳來和我做鄰居啦。",
  ui_story_5089_50890700_192_dialog_content = "……",
  ui_story_5089_50890802_1_dialog_content = "有歹人劫持了郡主，全城戒嚴！",
  ui_story_5089_50890802_2_dialog_content = "大街小巷都要搜查，見到可疑人物立刻報告！",
  ui_story_5089_50890802_3_dialog_content = "是！",
  ui_story_5089_50890802_4_dialog_content = "好多衛兵……整個璟良城的氣氛都不一樣了。",
  ui_story_5089_50890802_5_dialog_content = "而且總覺得我也算是他們要追查的可疑人物。",
  ui_story_5089_50890802_6_dialog_content = "誰在這裡？出來。",
  ui_story_5089_50890802_7_dialog_content = "糟糕——唔！誰拉我……",
  ui_story_5089_50890802_8_dialog_content = "噓，是我。",
  ui_story_5089_50890802_9_dialog_content = "丹棠！",
  ui_story_5089_50890802_10_dialog_content = "跟我來。",
  ui_story_5089_50890802_11_dialog_content = "這裡是什麼地方？",
  ui_story_5089_50890802_12_dialog_content = "是我們之前委託押送金子的鏢局準備的屋子。",
  ui_story_5089_50890802_13_dialog_content = "他們也算江湖中人，有自己的規矩。",
  ui_story_5089_50890802_14_dialog_content = "我們下了那麼大一單，總能為我們行些方便。",
  ui_story_5089_50890802_15_dialog_content = "妳從那時起就考慮了這麼多嗎！",
  ui_story_5089_50890802_16_dialog_content = "所以，妳在客棧丟下我們也是有理由的吧？",
  ui_story_5089_50890802_17_dialog_content = "我當時還不太確定真相如何，畢竟只有璇璣卿那麼一點模糊的暗示。",
  ui_story_5089_50890802_18_dialog_content = "但就算只有一點可能，都是足以危機整個鄴國的大事。",
  ui_story_5089_50890802_19_dialog_content = "還有……糧價太高了。",
  ui_story_5089_50890802_20_dialog_content = "我們也聽李伯說過，濟國的行商最近一直在高價收購糧食。",
  ui_story_5089_50890802_21_dialog_content = "春朔時的動亂，也有鄴國遲遲不肯交付岸防砲的責任。",
  ui_story_5089_50890802_22_dialog_content = "濟國總不能白白吃下這個虧。",
  ui_story_5089_50890802_23_dialog_content = "妳的意思是……濟國在故意哄抬糧價？",
  ui_story_5089_50890802_24_dialog_content = "穀貴傷民，民傷則離散。",
  ui_story_5089_50890802_25_dialog_content = "鄴國近年來增加了不少大大小小的工坊，吸引了大量青壯離開田地前去做工。",
  ui_story_5089_50890802_26_dialog_content = "我們原本就缺少足夠的糧食儲備來應對這種衝擊。",
  ui_story_5089_50890802_27_dialog_content = "糧價的上漲，還意味著其他行業的成本增加，會帶來一連串的惡劣影響。",
  ui_story_5089_50890802_28_dialog_content = "濟國不缺銀錢，若是鐵了心與我們相耗，長此以往，必然生亂。",
  ui_story_5089_50890802_29_dialog_content = "我不認為濟國想將事情做絕，應當只是想要借此拿捏鄴國。",
  ui_story_5089_50890802_30_dialog_content = "……只是時機太差了。",
  ui_story_5089_50890802_31_dialog_content = "時機？",
  ui_story_5089_50890802_32_dialog_content = "PlayerName公子，你覺得所謂的「國家」是什麼？",
  ui_story_5089_50890802_33_dialog_content = "咦？我覺得……是大家為了能讓生活變好，所以聚在一起。",
  ui_story_5089_50890802_34_dialog_content = "既各自打拚，也互相幫助的集體吧，",
  ui_story_5089_50890802_35_dialog_content = "這是空谷的理念嗎？果真如世外桃源一般。",
  ui_story_5089_50890802_36_dialog_content = "不、不對嗎？",
  ui_story_5089_50890802_37_dialog_content = "不，PlayerName公子這樣就很好。",
  ui_story_5089_50890802_38_dialog_content = "即便同屬於兆，龍洲的諸侯國對此也都有自己的觀點。",
  ui_story_5089_50890802_39_dialog_content = "比如濟國認為「治國如經商」。而在鄴國，我們受的教育是…",
  ui_story_5089_50890802_40_dialog_content = "「國家」是一台巨大而無形的機巧機關。運作不息，晝夜不停。",
  ui_story_5089_50890802_41_dialog_content = "君為樞軸，臣為齒輪，匠師為油，芸芸百姓為其動力。",
  ui_story_5089_50890802_42_dialog_content = "倘若能各司其職，正常運轉，自然國力興盛。",
  ui_story_5089_50890802_43_dialog_content = "如今呢？",
  ui_story_5089_50890802_44_dialog_content = "君王為假，臣中恐有駿命異心，匠師不得自由，百姓也眼看要被爭鬥所傷。",
  ui_story_5089_50890802_45_dialog_content = "欲破此局，唯有快刀斬亂麻。",
  ui_story_5089_50890802_46_dialog_content = "所以我自願回宮，想從最核心處找到破綻。",
  ui_story_5089_50890802_47_dialog_content = "同時也能讓你們擺脫追兵，自由去尋找證據。",
  ui_story_5089_50890802_48_dialog_content = "若要直說，阿玖定不會同意，所以才只能出此下策，還請PlayerName公子不要怪罪。",
  ui_story_5089_50890802_49_dialog_content = "不會不會，我也已經領教過阿玖的頑固了。",
  ui_story_5089_50890802_50_dialog_content = "所以我其實也做了一件事……",
  ui_story_5089_50890802_51_dialog_content = "少爺、小姐，你們的鏢都已安全送到，麻煩來清點一下。",
  ui_story_5089_50890802_52_dialog_content = "啊，好，多謝你們了。",
  ui_story_5089_50890802_53_dialog_content = "還有小姐剛託我們打聽的那件事，也有眉目了。",
  ui_story_5089_50890802_54_dialog_content = "是城外兄弟的消息，確實有火龍輦在朝那邊的軌道集中，那架勢，要運的東西應該不少。",
  ui_story_5089_50890802_55_dialog_content = "我知道了，多謝你們。",
  ui_story_5089_50890802_56_dialog_content = "收錢辦事而已，告退。",
  ui_story_5089_50890802_57_dialog_content = "難道是說祕密工坊的事？",
  ui_story_5089_50890802_58_dialog_content = "沒錯，我在宮中也有打聽到一些消息。",
  ui_story_5089_50890802_59_dialog_content = "假叔父一直在利用鄴國，為駿命製造武器。",
  ui_story_5089_50890802_60_dialog_content = "濟國的岸防砲遲遲不送，一是要配合駿命的計畫，二是駿命也想將那批岸防砲據為己有。",
  ui_story_5089_50890802_61_dialog_content = "而就在前段時間，他們又再度增加了火器需求的數量。",
  ui_story_5089_50890802_62_dialog_content = "還幾番催促，乃至威脅要假叔父即刻送去。",
  ui_story_5089_50890802_63_dialog_content = "來的路上，我又聽PlayerName公子說了祕密工坊的存在，便叫人盯著。",
  ui_story_5089_50890802_64_dialog_content = "沒想到這麼快就有了動作……",
  ui_story_5089_50890802_65_dialog_content = "怎麼能眼睜睜看著駿命那種組織拿到那麼多武器！",
  ui_story_5089_50890802_66_dialog_content = "我也是同樣的心情。",
  ui_story_5089_50890802_67_dialog_content = "只是以我們如今的處境，很難採取什麼行動。",
  ui_story_5089_50890802_68_dialog_content = "明明靠著PlayerName公子你們，好不容易弄清了真相。要是我能更早有所準備……",
  ui_story_5089_50890802_69_dialog_content = "這個表情，可不像是我知道的丹棠啊。",
  ui_story_5089_50890802_70_dialog_content = "PlayerName公子？",
  ui_story_5089_50890802_71_dialog_content = "我認識的丹棠，可是連所謂的命中註定都敢爭上一爭。",
  ui_story_5089_50890802_72_dialog_content = "勇敢到甚至令人害怕的人啊。",
  ui_story_5089_50890802_73_dialog_content = "……謬讚了。眼下的困局，絕非一腔孤勇就能解決的。",
  ui_story_5089_50890802_74_dialog_content = "至少，要是能有足以入局談判的籌碼……",
  ui_story_5089_50890802_75_dialog_content = "有啊。",
  ui_story_5089_50890802_76_dialog_content = "什麼？",
  ui_story_5089_50890802_77_dialog_content = "我說，要籌碼的話，這裡有很多。",
  ui_story_5089_50890802_78_dialog_content = "比如——買一座城市都不在話下的黃金。",
  ui_story_5089_50890802_79_dialog_content = "！",
  ui_story_5089_50890802_80_dialog_content = "但那是世子送給你，你還打算退還的禮物。",
  ui_story_5089_50890802_81_dialog_content = "好不容易走到這裡，不把能利用的都拿來利用就太浪費了。",
  ui_story_5089_50890802_82_dialog_content = "但就算有這麼多黃金，想要在有限的時間內拉攏人手——",
  ui_story_5089_50890802_83_dialog_content = "關於這個。",
  ui_story_5089_50890802_84_dialog_content = "我不太懂朝堂的那些眉眉角角，所以無法提出那方面的意見。",
  ui_story_5089_50890802_85_dialog_content = "不過，能不能想得簡單一點呢？",
  ui_story_5089_50890802_86_dialog_content = "畢竟錢，就是用來買東西的嘛。",
  ui_story_5089_50890802_87_dialog_content = "那……PlayerName公子想買什麼？",
  ui_story_5089_50890802_88_dialog_content = "我猜，他們之前應該沒有動用過火龍輦吧。",
  ui_story_5089_50890802_89_dialog_content = "動靜那麼大，周圍的百姓不可能沒聽見，也就不可能篤信那座工坊早已廢棄。",
  ui_story_5089_50890802_90_dialog_content = "的確，之前沒人見過這般景象。",
  ui_story_5089_50890802_91_dialog_content = "事以密成，想要保證祕密工坊是「祕密」，就該分批多次少量地運輸才對。",
  ui_story_5089_50890802_92_dialog_content = "但唯獨這次用了火龍輦，看樣子還遠不止一輛。",
  ui_story_5089_50890802_93_dialog_content = "火龍輦的租用歸由百工院監管。",
  ui_story_5089_50890802_94_dialog_content = "有兩大機巧門派出身的官員，和朝廷直接指派的管理官同時監督。",
  ui_story_5089_50890802_95_dialog_content = "便是大王本人都不得隨意繞過這程序，隨意動用。",
  ui_story_5089_50890802_96_dialog_content = "只是已經租給工坊主等人的那些，管理沒這麼嚴格。",
  ui_story_5089_50890802_97_dialog_content = "也就是說，這些火龍輦很有可能只是駿命從那些人手中二次借用的吧。",
  ui_story_5089_50890802_98_dialog_content = "要從那些人身上著手嗎？",
  ui_story_5089_50890802_99_dialog_content = "不。",
  ui_story_5089_50890802_100_dialog_content = "我們沒必要在這種事上和他們正面衝突，反正現在著急的是駿命。",
  ui_story_5089_50890802_101_dialog_content = "現在置身局外，好像反而更能看清楚璇極所說的「勢」了。",
  ui_story_5089_50890802_102_dialog_content = "丹棠，百工院租出去的，就只是「火龍輦」對吧？",
  ui_story_5089_50890802_103_dialog_content = "是的，沒有錯。",
  ui_story_5089_50890802_104_dialog_content = "那麼，我想要買的……",
  ui_story_5089_50890802_105_dialog_content = "是「路」。",
  ui_story_5089_50890802_106_dialog_content = "……PlayerName公子，真乃奇才！",
  ui_story_5089_50890802_107_dialog_content = "<color=#e8d9bb>祕密工坊。</color>",
  ui_story_5089_50890802_108_dialog_content = "周圍的火龍輦是怎麼回事？誰允妳擅自動作的！",
  ui_story_5089_50890802_109_dialog_content = "吵什麼？我還想問你們呢。",
  ui_story_5089_50890802_110_dialog_content = "上面三番兩次催促，叫我們送武器過去，你們都幹了什麼？",
  ui_story_5089_50890802_111_dialog_content = "造不出足夠的數量就把濟國那批先送過去，至少這個不難吧。",
  ui_story_5089_50890802_112_dialog_content = "濟國的訂單沒完成，可能會影響兩國關係。",
  ui_story_5089_50890802_113_dialog_content = "哈，三歲小孩都不會這麼天真。",
  ui_story_5089_50890802_114_dialog_content = "大家都上了駿命的船，該聽哪邊的命令還要我教你？誰真在乎什麼兩國關係。",
  ui_story_5089_50890802_115_dialog_content = "總不會……你們那個大王真把自己當鄴王了？",
  ui_story_5089_50890802_116_dialog_content = "怎麼會。",
  ui_story_5089_50890802_117_dialog_content = "也是，聽說他以前就是個死囚，投靠了駿命，才能以鄴王的身分活到今天。",
  ui_story_5089_50890802_118_dialog_content = "要是他敢有異心，現在的一切他怎麼得到的，就得怎麼吐出來。",
  ui_story_5089_50890802_119_dialog_content = "眼看起事在即，這些諸侯國聽話的也就罷了，不聽話的，當然是越亂越好。",
  ui_story_5089_50890802_120_dialog_content = "這個道理，你應該也明白吧？",
  ui_story_5089_50890802_121_dialog_content = "……當然。",
  ui_story_5089_50890802_122_dialog_content = "那就行了，快點去幫忙裝貨。",
  ui_story_5089_50890802_123_dialog_content = "綴戶大人，不好了！",
  ui_story_5089_50890802_124_dialog_content = "又怎麼了？",
  ui_story_5089_50890802_125_dialog_content = "恐怕暫時無法用火龍輦運貨了。",
  ui_story_5089_50890802_126_dialog_content = "我們不是給了那些工坊的人一大筆租金嗎？",
  ui_story_5089_50890802_127_dialog_content = "不是這個問題，是……",
  ui_story_5089_50890802_128_dialog_content = "路被封了。",
  ui_story_5089_50890802_129_dialog_content = "嗄？！",
  ui_story_5089_50890901_1_dialog_content = "有PlayerName公子豪擲千金，事情果然好辦。",
  ui_story_5089_50890901_2_dialog_content = "我已將工坊附近沿路的土地也暫租了下來，並拜託村民設了路障。",
  ui_story_5089_50890901_3_dialog_content = "必要那些駿命者寸步難行。",
  ui_story_5089_50890901_4_dialog_content = "只是因為我們封路，有一隊行商也被困在了這裡——",
  ui_story_5089_50890901_5_dialog_content = "兩位貴人，小的就是來收些米糧，可沒犯過罪啊。",
  ui_story_5089_50890901_6_dialog_content = "能不能行行好，放在下的商隊過去？",
  ui_story_5089_50890901_7_dialog_content = "你是從濟國來收糧的？",
  ui_story_5089_50890901_8_dialog_content = "正是，正是，可有什麼問題？在下的經商手續都一應俱全……",
  ui_story_5089_50890901_9_dialog_content = "（丹棠。）",
  ui_story_5089_50890901_10_dialog_content = "（我明白。）",
  ui_story_5089_50890901_11_dialog_content = "咳，你可知自己眼前這位是何人？",
  ui_story_5089_50890901_12_dialog_content = "不，不知貴人尊名……",
  ui_story_5089_50890901_13_dialog_content = "這位PlayerName乃是艾斯特拉大陸特使，空谷之主，濟王親封的榮譽臣民。",
  ui_story_5089_50890901_14_dialog_content = "受龍女神佑者，林家商會的友人，世子正苦苦追求的……",
  ui_story_5089_50890901_15_dialog_content = "（夠了！夠了！他的眼神已經越來越炙熱了，不需要再說更多了！）",
  ui_story_5089_50890901_16_dialog_content = "久仰貴人大名！能再次得見一面真是小的八輩子修來的福氣。",
  ui_story_5089_50890901_17_dialog_content = "您可有事要吩咐小的？只要能做得到……喔，對了，路是您封的。",
  ui_story_5089_50890901_18_dialog_content = "哪怕您要封到天荒地老，小的絕無怨言！",
  ui_story_5089_50890901_19_dialog_content = "不至於這麼嚴重，我只是有一筆生意想和你談。",
  ui_story_5089_50890901_20_dialog_content = "您儘管說，不管要買什麼，一律給您優惠！",
  ui_story_5089_50890901_21_dialog_content = "丹棠，金子還剩下多少？",
  ui_story_5089_50890901_22_dialog_content = "算上工匠的工錢，和租用軌道跟土地的部分，也只用了一小部分。",
  ui_story_5089_50890901_23_dialog_content = "那把剩下的都給他吧。",
  ui_story_5089_50890901_24_dialog_content = "您這是……",
  ui_story_5089_50890901_25_dialog_content = "我想用這些金子，買下你們在鄴國收購的所有糧食。",
  ui_story_5089_50890901_26_dialog_content = "這……您有些為難在下……",
  ui_story_5089_50890901_27_dialog_content = "我知道你們是在位濟王辦事。",
  ui_story_5089_50890901_28_dialog_content = "唔！",
  ui_story_5089_50890901_29_dialog_content = "你可以說是我跟你強買的，就算濟王責怪下來，也只把責任推到我頭上就行了。",
  ui_story_5089_50890901_30_dialog_content = "那……小的就恭敬不如從命了。",
  ui_story_5089_50890901_31_dialog_content = "嗯，我說話算話。",
  ui_story_5089_50890901_32_dialog_content = "呼，總算走了。",
  ui_story_5089_50890901_33_dialog_content = "呵呵。",
  ui_story_5089_50890901_34_dialog_content = "我裝腔作勢的樣子果然很好笑嗎……",
  ui_story_5089_50890901_35_dialog_content = "怎麼會，剛剛的PlayerName公子，可是十分氣度不凡，令人心折呢。",
  ui_story_5089_50890901_36_dialog_content = "嗯？",
  ui_story_5089_50890901_37_dialog_content = "遠處那批人是……",
  ui_story_5089_50890901_38_dialog_content = "<color=#e8d9bb>片刻前——</color>",
  ui_story_5089_50890901_39_dialog_content = "篤篤篤。",
  ui_story_5089_50890901_40_dialog_content = "這種時候，是誰傳的消息？",
  ui_story_5089_50890901_41_dialog_content = "……",
  ui_story_5089_50890901_42_dialog_content = "璇極師姐！百工院的師兄說，那名空裔要——",
  ui_story_5089_50890901_43_dialog_content = "哎，說了都少次，在宮裡別師兄師姐的叫。",
  ui_story_5089_50890901_44_dialog_content = "雖然我們沒有結黨立派的意思，但瓜田李下的，也不好讓人誤會。",
  ui_story_5089_50890901_45_dialog_content = "當年候風卿不就是這麼獲罪的嗎。",
  ui_story_5089_50890901_46_dialog_content = "候風卿……那是十多年前的人了吧。",
  ui_story_5089_50890901_47_dialog_content = "我記得是個沒加入任何門派，四處跟著自由工匠學習的野路子機巧師。",
  ui_story_5089_50890901_48_dialog_content = "很有才幹，只是有些恃才傲物，兩大門派都曾試圖拉攏他，但也都被拒絕了。",
  ui_story_5089_50890901_49_dialog_content = "入朝為官後，還提出了不少激進的改革意見。",
  ui_story_5089_50890901_50_dialog_content = "想解除對機關造物的買賣限制，還說過什麼所有門派的資源都該由朝廷統籌安排的話。",
  ui_story_5089_50890901_51_dialog_content = "他倒是有一腔報國熱血，只是做事太過偏激，又不考慮實際情況。",
  ui_story_5089_50890901_52_dialog_content = "所以落得那個下場，也怪不得別人。璇極大人您可別說要學他。",
  ui_story_5089_50890901_53_dialog_content = "不會不會，我可是個聽事良臣，沒看大王說要關我，我就老老實實讓他關嗎？",
  ui_story_5089_50890901_54_dialog_content = "您似乎忘了自己是為什麼被關起來的。",
  ui_story_5089_50890901_55_dialog_content = "不管是因為什麼，反正不會是因為動了幾台我自己參與設計的機巧砲就是了。",
  ui_story_5089_50890901_56_dialog_content = "好了，讓我看看信上說了什麼。嗯……",
  ui_story_5089_50890901_57_dialog_content = "哈哈哈！有意思，不愧是PlayerName公子。",
  ui_story_5089_50890901_58_dialog_content = "雖然有點異想天開，不過在這種情況下，這竟成了最好的解法。",
  ui_story_5089_50890901_59_dialog_content = "看來你已徹底看清了局面。",
  ui_story_5089_50890901_60_dialog_content = "看清什麼？",
  ui_story_5089_50890901_61_dialog_content = "沒什麼，我是說，稍後要請你幫我傳個信。",
  ui_story_5089_50890901_62_dialog_content = "我如今並無官職，只是個普通的機巧師，不好參與政事。",
  ui_story_5089_50890901_63_dialog_content = "但互通消息，幫著清理師門的叛徒，還是應有之義。",
  ui_story_5089_50890901_64_dialog_content = "所以還望師兄，行個方便。",
  ui_story_5089_50890901_65_dialog_content = "是，師姐。",
  ui_story_5089_50890901_66_dialog_content = "然後就是……鄰居姑娘，妳還好嗎？",
  ui_story_5089_50890901_67_dialog_content = "……",
  ui_story_5089_50890901_68_dialog_content = "我還以為聊聊候風卿的事就能引妳開口呢。",
  ui_story_5089_50890901_69_dialog_content = "十年前曾在朝中任職，被捲入黨政，判處死罪，最後下落不明。",
  ui_story_5089_50890901_70_dialog_content = "符合所有條件的人，只有他一個。",
  ui_story_5089_50890901_71_dialog_content = "……已經與我無關了。",
  ui_story_5089_50890901_72_dialog_content = "如今，我曾執著恩仇都成了一場笑話。",
  ui_story_5089_50890901_73_dialog_content = "我已不知道該再如何揮劍，派不上什麼用場了。",
  ui_story_5089_50890901_74_dialog_content = "璇極大人也請別再為我費心了。",
  ui_story_5089_50890901_75_dialog_content = "只為了一件事而活，派不上用場就只能被放棄。",
  ui_story_5089_50890901_76_dialog_content = "上一次聽到這種形容，還是在說暗鬼。",
  ui_story_5089_50890901_77_dialog_content = "玖姑娘，我問妳。",
  ui_story_5089_50890901_78_dialog_content = "人和暗鬼最大的差別是什麼？",
  ui_story_5089_50890901_79_dialog_content = "……",
  ui_story_5089_50890901_80_dialog_content = "有差別嗎？",
  ui_story_5089_50890901_81_dialog_content = "唉，看來我這邊是搞不定了。",
  ui_story_5089_50890901_82_dialog_content = "交給你囉。",
  ui_story_5089_50890901_83_dialog_content = "……",
  ui_story_5089_50890901_84_dialog_content = "PlayerName公子，你在想什麼？",
  ui_story_5089_50890901_85_dialog_content = "人和暗鬼的差別是什麼？",
  ui_story_5089_50890901_86_dialog_content = "嗯？",
  ui_story_5089_50890901_87_dialog_content = "不，沒什麼。妳剛剛說什麼？",
  ui_story_5089_50890901_88_dialog_content = "我說，現在設下的路障，駿命如果想強行突破還是攔不住他們。",
  ui_story_5089_50890901_89_dialog_content = "所以，差不多該去叫援軍了。",
  ui_story_5089_50890901_90_dialog_content = "璟良城內能容納的兵員有限，所以大部分璟衛軍平常都駐紮在城外。",
  ui_story_5089_50890901_91_dialog_content = "雖不比城內人人精銳，但現在我們所缺的也正是數量。",
  ui_story_5089_50890901_92_dialog_content = "那我們快過去吧，妳剛剛說可以用郡主的身分調兵對吧？",
  ui_story_5089_50890901_93_dialog_content = "PlayerName公子。",
  ui_story_5089_50890901_94_dialog_content = "怎麼了……為什麼突然遞匕首給我？",
  ui_story_5089_50890901_95_dialog_content = "雖說駐紮在城外，但璟衛軍依舊內外一體，城內的消息定然早已傳至此處。",
  ui_story_5089_50890901_96_dialog_content = "你我心知肚明，事到如今，那位假叔父已沒理由再對我留情。",
  ui_story_5089_50890901_97_dialog_content = "想必他們已不再是我亮出身分就調動得了的。",
  ui_story_5089_50890901_98_dialog_content = "那我們來這裡是為了？",
  ui_story_5089_50890901_99_dialog_content = "這個。",
  ui_story_5089_50890901_100_dialog_content = "……為什麼要給我刀子？",
  ui_story_5089_50890901_101_dialog_content = "不知道這裡的璟衛軍收到了什麼樣的命令。",
  ui_story_5089_50890901_102_dialog_content = "但假叔父只要還顧忌身分，至少明面上不會對我痛下殺手。",
  ui_story_5089_50890901_103_dialog_content = "所以在他們看來，灼華郡主應當還是需要保護的對象，所以……",
  ui_story_5089_50890901_104_dialog_content = "妳想叫我扮演劫持妳的歹徒，然後一路將他們引到工坊去？",
  ui_story_5089_50890901_105_dialog_content = "這太冒險了吧，根本無法預測會發生什麼事。",
  ui_story_5089_50890901_106_dialog_content = "萬一我們直接被抓了呢？萬一那個假鄴王喪心病狂，真的要直接殺了妳呢？",
  ui_story_5089_50890901_107_dialog_content = "還是先回去，我們可以想其他辦法——",
  ui_story_5089_50890901_108_dialog_content = "<color=#e8d9bb>丹棠突然抓住我拿刀的手，飛快地割向自己的脖子。</color>",
  ui_story_5089_50890901_109_dialog_content = "丹棠！",
  ui_story_5089_50890901_110_dialog_content = "<color=#e8d9bb>我拚命收力，利刃卻依舊在她頸上劃出一道紅痕。</color>",
  ui_story_5089_50890901_111_dialog_content = "PlayerName公子，請看著我。",
  ui_story_5089_50890901_112_dialog_content = "<color=#e8d9bb>一顆血珠順著刀鋒滑進我的掌心，丹棠卻在被林葉遮擋的天光下輕盈淺笑。</color>",
  ui_story_5089_50890901_113_dialog_content = "我信你。",
  ui_story_5089_50890901_114_dialog_content = "……我明白了。",
  ui_story_5089_50890901_115_dialog_content = "誰在那裡？",
  ui_story_5089_50890901_116_dialog_content = "別過來！",
  ui_story_5089_50890901_117_dialog_content = "你們的灼華郡主在我手裡！",
  ui_story_5089_50890901_118_dialog_content = "唔！",
  ui_story_5089_50890901_119_dialog_content = "有歹人劫持郡主！全隊集合！",
  ui_story_5089_50890901_120_dialog_content = "立刻放了郡主！還能暫且饒你一命！",
  ui_story_5089_50890901_121_dialog_content = "怎麼可能說放就放啊，而且你們也威脅不到我。",
  ui_story_5089_50890901_122_dialog_content = "我乃駿命的一員，我們的據點就在不遠處，裡面存了大量火器。",
  ui_story_5089_50890901_123_dialog_content = "你們最好不要輕舉妄動，不然我們隨時可以跟你們同歸於盡。",
  ui_story_5089_50890901_124_dialog_content = "弓箭手！",
  ui_story_5089_50890901_125_dialog_content = "強制感應！",
  ui_story_5089_50890901_126_dialog_content = "唔啊——",
  ui_story_5089_50890901_127_dialog_content = "別讓他跑了！",
  ui_story_5089_50890901_128_dialog_content = "糟糕，隊長！歹人和郡主都不見了！",
  ui_story_5089_50890901_129_dialog_content = "還不快追！郡主要有什麼閃失咱們擔待得起嗎！",
  ui_story_5089_50890901_130_dialog_content = "可是往哪裡——這有一朵海棠花！",
  ui_story_5089_50890901_131_dialog_content = "一定是郡主留下的線索，往這邊追！",
  ui_story_5089_50890901_132_dialog_content = "一定要找到他們的那個據點！",
  ui_story_5089_50890901_133_dialog_content = "大王，有一隊城外的璟衛軍往工坊方向去了。",
  ui_story_5089_50890901_134_dialog_content = "怎麼回事？",
  ui_story_5089_50890901_135_dialog_content = "說是發現了挾持郡主的歹人。",
  ui_story_5089_50890901_136_dialog_content = "璟衛軍的將領不敢怠慢，即刻就帶兵前去了。",
  ui_story_5089_50890901_137_dialog_content = "還有，現在工坊不僅被璟衛軍包圍，周圍的道路也被封鎖。",
  ui_story_5089_50890901_138_dialog_content = "怕是馬上就要被圍攻。",
  ui_story_5089_50890901_139_dialog_content = "我們的人暫且還能控制工坊內的局面，讓他們按兵不動。",
  ui_story_5089_50890901_140_dialog_content = "但他們還是吵著要知道大王您作何打算。",
  ui_story_5089_50890901_141_dialog_content = "呵。",
  ui_story_5089_50890901_142_dialog_content = "孤注一擲，卻只有這點手段嗎？",
  ui_story_5089_50890901_143_dialog_content = "走。",
  ui_story_5089_50890901_144_dialog_content = "他們既要這樣逼我露面，本王便親自去會會他們。",
  ui_story_5089_50890901_145_dialog_content = "<color=#e8d9bb>片刻後——</color>",
  ui_story_5089_50890901_146_dialog_content = "唉，可算是走了。",
  ui_story_5089_50890901_147_dialog_content = "雖說燈下黑，在敵人眼皮子底下藏著才最安全。",
  ui_story_5089_50890901_148_dialog_content = "但誰成想他大半天不挪窩兒，就在這坐著不知道想什麼，宮殿壞了都不叫人來修。",
  ui_story_5089_50890901_149_dialog_content = "多虧這房梁夠寬，不然藏這麼大半天，我的老胳膊老腿可受不了。",
  ui_story_5089_50890901_150_dialog_content = "現在他們走了，我也能出宮自在去了吧。",
  ui_story_5089_50890901_151_dialog_content = "嗯？角落裡這不是……阿玖姑娘的劍嗎？",
  ui_story_5089_50890901_152_dialog_content = "得，還得給她送回去。",
  ui_story_5089_50890901_153_dialog_content = "呼……哈……我都……這麼拚命地跑了……",
  ui_story_5089_50890901_154_dialog_content = "那些璟衛軍怎麼還是追得這麼快。",
  ui_story_5089_50890901_155_dialog_content = "我已經盡量用海棠引導他們繞路了，但他們反應得也比我預想中快上不少。",
  ui_story_5089_50890901_156_dialog_content = "而且令行禁止，定是平日裡也不曾疏於訓練。",
  ui_story_5089_50890901_157_dialog_content = "那位假叔父，一直在練兵。還有那麼多的火器需求……",
  ui_story_5089_50890901_158_dialog_content = "駿命所圖，究竟為何……",
  ui_story_5089_50890901_159_dialog_content = "現在想太多也沒用，反正我們已經把能做的都做了。",
  ui_story_5089_50890901_160_dialog_content = "就先在這裡休息一下吧。",
  ui_story_5089_50890901_161_dialog_content = "雖然工坊裡到現在都還沒有動靜，但再往前就不知道他們會做出什麼反應了。",
  ui_story_5089_50890901_162_dialog_content = "<color=#e8d9bb>身後，訓練有素的璟衛軍紛紛散開，將我們包圍。手中舉著的火把將夜空映紅一片。</color>",
  ui_story_5089_50890901_163_dialog_content = "<color=#e8d9bb>身前，駿命的工坊雖有人息，卻不見人影。如同蟄伏的巨獸，詭異幽暗。</color>",
  ui_story_5089_50890901_164_dialog_content = "PlayerName公子，之前來不及說。",
  ui_story_5089_50890901_165_dialog_content = "雖然我大言不慚地求了你的幫助，但並沒有想將你置於今日這般險境。",
  ui_story_5089_50890901_166_dialog_content = "對此，我心中有愧。",
  ui_story_5089_50890901_167_dialog_content = "沒關係，我覺得不會有事的。",
  ui_story_5089_50890901_168_dialog_content = "我也信妳。",
  ui_story_5089_50890901_169_dialog_content = "嗯？璟衛軍那邊有什麼動靜……",
  ui_story_5089_50890901_170_dialog_content = "大王駕到——",
  ui_story_5089_50890901_171_dialog_content = "那就是……",
  ui_story_5089_50890901_172_dialog_content = "我的假叔父。",
  ui_story_5089_50890901_173_dialog_content = "丹棠，我本以為妳會更聰明些。",
  ui_story_5089_50890901_174_dialog_content = "難道妳不知道，本王一聲令下，那座工坊不會有半點損傷？",
  ui_story_5089_50890901_175_dialog_content = "只有你們會在這裡死無葬身之地。",
  ui_story_5089_50890901_176_dialog_content = "簡直是自投羅網。",
  ui_story_5089_50890901_177_dialog_content = "如果你真的是叔父，自然有這個權利。",
  ui_story_5089_50890901_178_dialog_content = "可你不過一介冒牌傀儡，怎敢如此放肆！",
  ui_story_5089_50890901_179_dialog_content = "我們這便在眾人面前揭下你的假面——候風卿！",
  ui_story_5089_50890902_1_dialog_content = "PlayerName公子，趁現在！",
  ui_story_5089_50890902_2_dialog_content = "強制感應！",
  ui_story_5089_50890902_3_dialog_content = "唔……",
  ui_story_5089_50890902_4_dialog_content = "（不要在璟衛軍身上浪費時間，我們的目的不是和這些人戰鬥。）",
  ui_story_5089_50890902_5_dialog_content = "（駿命的易容術都是利用人皮面具做的偽裝。）",
  ui_story_5089_50890902_6_dialog_content = "（找到機會，只要一瞬間就好……只要能劃破他的面具——！）",
  ui_story_5089_50890902_7_dialog_content = "啊？！",
  ui_story_5089_50890902_8_dialog_content = "<color=#e8d9bb>刀刃確實割開了假鄴王的側臉。</color>",
  ui_story_5089_50890902_9_dialog_content = "<color=#e8d9bb>裂開的，卻並非想像中無機質的面具。</color>",
  ui_story_5089_50890902_10_dialog_content = "<color=#e8d9bb>鮮血從刀口下滲出，昭示著那確實是屬於活人的外觀。</color>",
  ui_story_5089_50890902_11_dialog_content = "怎麼會……？",
  ui_story_5089_50890902_12_dialog_content = "現在確認過了。",
  ui_story_5089_50890902_13_dialog_content = "得到你們想要的結果了嗎？",
  ui_story_5089_50891001_1_dialog_content = "大、大王！快救駕！救駕啊！你們都愣著幹什麼！",
  ui_story_5089_50891001_2_dialog_content = "都退下吧，小孩子胡鬧而已。",
  ui_story_5089_50891001_3_dialog_content = "不……你不可能是真的鄴王……但為什麼……？",
  ui_story_5089_50891001_4_dialog_content = "所以我說，你們謀劃了半天只為了這個，太愚蠢。",
  ui_story_5089_50891001_5_dialog_content = "我用了這個身分這麼久，沒有任何人察覺到異常。",
  ui_story_5089_50891001_6_dialog_content = "難道你以為只是靠每天藏在面具之下，做個苟延殘喘的亡魂？",
  ui_story_5089_50891001_7_dialog_content = "唔！",
  ui_story_5089_50891001_8_dialog_content = "從十年前開始，我就一直在調整自己的臉。",
  ui_story_5089_50891001_9_dialog_content = "割開血肉，切削骨頭。",
  ui_story_5089_50891001_10_dialog_content = "手臂的形狀不對？砍了再接便是。",
  ui_story_5089_50891001_11_dialog_content = "說話的聲音不對？服毒燒啞便是。",
  ui_story_5089_50891001_12_dialog_content = "我曾聽說過……繼位前的一段時間，叔父經常遭到刺殺，原來竟是如此。",
  ui_story_5089_50891001_13_dialog_content = "為了駿命，你倒不遺餘力。",
  ui_story_5089_50891001_14_dialog_content = "駿命？呵，不過一群只敢藏在陰影中的老鼠罷了。",
  ui_story_5089_50891001_15_dialog_content = "他們真以為自己算什麼東西，膽敢染指本王的鄴國！",
  ui_story_5089_50891001_16_dialog_content = "你……",
  ui_story_5089_50891001_17_dialog_content = "如今鎮邪大儀不穩，幼帝無執掌天下之能，風雲動盪，眼看亂世將至。",
  ui_story_5089_50891001_18_dialog_content = "我本還顧忌著與濟國的關係，想徐徐圖之。",
  ui_story_5089_50891001_19_dialog_content = "但事已至此，便是將火器都交予駿命又何妨？",
  ui_story_5089_50891001_20_dialog_content = "火器到手，駿命就將即刻起事。",
  ui_story_5089_50891001_21_dialog_content = "諸國被駿命滲透多年，水淹皓津之事必在各國重演。他們自顧不暇，駿命又直指央京。",
  ui_story_5089_50891001_22_dialog_content = "屆時螳螂捕蟬，我又何嘗不能做那在後的黃雀？",
  ui_story_5089_50891001_23_dialog_content = "候風，候風……候風卿候了一輩子都不曾等來那東風。",
  ui_story_5089_50891001_24_dialog_content = "這次，便由本王自己來做那陣風！",
  ui_story_5089_50891001_25_dialog_content = "十年間，本王厲兵秣馬，枕戈待旦。",
  ui_story_5089_50891001_26_dialog_content = "待群雄逐鹿，起的可就未必就是駿命的「勢」。",
  ui_story_5089_50891001_27_dialog_content = "丹棠，妳已知本王的祕密。",
  ui_story_5089_50891001_28_dialog_content = "雖然妳今日所為甚愚，但依舊算個賢才，可願追隨本王？",
  ui_story_5089_50891001_29_dialog_content = "只要妳點頭，本王保你還能做妳的灼華郡主。",
  ui_story_5089_50891001_30_dialog_content = "那邊的空裔，你的能力在戰場上大有可為，也可願投入本王麾下？",
  ui_story_5089_50891001_31_dialog_content = "將來踏平七國……",
  ui_story_5089_50891001_32_dialog_content = "你可知駿命和妖魔邪靈勾結，皆為罔顧人命之徒？",
  ui_story_5089_50891001_33_dialog_content = "駿命的火器儲備大多仰賴鄴國，本王自然知道。",
  ui_story_5089_50891001_34_dialog_content = "但既不能為我所用，別國百姓之命又與我何干？為敵人憂心，乃婦人之仁。",
  ui_story_5089_50891001_35_dialog_content = "至於妖魔，豬狗不如的蠢物，雖令人不恥，但駿命本就是鬼祟在下，用就用了。",
  ui_story_5089_50891001_36_dialog_content = "你若不喜，用完殺了就是。",
  ui_story_5089_50891001_37_dialog_content = "我瞭解你的想法了。看來我們——",
  ui_story_5089_50891001_38_dialog_content = "道不同，不相為謀。",
  ui_story_5089_50891001_39_dialog_content = "不識抬舉。",
  ui_story_5089_50891001_40_dialog_content = "那個……我也有一個問題想問。",
  ui_story_5089_50891001_41_dialog_content = "你把這些事就這樣說出來，沒關係嗎？",
  ui_story_5089_50891001_42_dialog_content = "明明一座滿是駿命者的工坊就在旁邊。",
  ui_story_5089_50891001_43_dialog_content = "本王可不是你們，那座工坊我早已差人封鎖。",
  ui_story_5089_50891001_44_dialog_content = "駿命想辦大事，還得指望本王的火器。",
  ui_story_5089_50891001_45_dialog_content = "只要火器到手，工坊裡那些人是死是活，也就無需在乎了。",
  ui_story_5089_50891001_46_dialog_content = "但要是三天內，你的火器交不到他們手裡會怎麼樣？",
  ui_story_5089_50891001_47_dialog_content = "……你從何得知的？",
  ui_story_5089_50891001_48_dialog_content = "空裔的能力很有用這件事，我也是知道的。",
  ui_story_5089_50891001_49_dialog_content = "不過現在的重點是，你應該無法遵守三天的期限了。",
  ui_story_5089_50891001_50_dialog_content = "你做了什麼？",
  ui_story_5089_50891001_51_dialog_content = "大王！不好了——",
  ui_story_5089_50891001_52_dialog_content = "說！",
  ui_story_5089_50891001_53_dialog_content = "百工院的人正在拆除火龍輦的軌道，我們原定的運輸路線已全部作廢！",
  ui_story_5089_50891001_54_dialog_content = "誰允許的！",
  ui_story_5089_50891001_55_dialog_content = "百工院說——",
  ui_story_5089_50891001_56_dialog_content = "只是有一個好心的投資人，捐贈給了他們一點金子。",
  ui_story_5089_50891001_57_dialog_content = "用來翻修因為租賃者的不當使用，早已過度磨損的鐵軌而已。",
  ui_story_5089_50891001_58_dialog_content = "唯一的條件就是想要指定拆除的軌道順序，這不過分吧。",
  ui_story_5089_50891001_59_dialog_content = "我們還幫忙吸引了你的視線。",
  ui_story_5089_50891001_60_dialog_content = "從今天下午就開始作業的話，就算現在開始重建，應該也要花費三天以上。",
  ui_story_5089_50891001_61_dialog_content = "從一開始，我想買的就是這一條「路」。",
  ui_story_5089_50891001_62_dialog_content = "不過是上不得檯面的小手段而已，只要大王一聲令下——",
  ui_story_5089_50891001_63_dialog_content = "蠢貨，滾開！",
  ui_story_5089_50891001_64_dialog_content = "或許我用的是不上檯面的小手段吧。",
  ui_story_5089_50891001_65_dialog_content = "但你應該也明白，從現在開始，重點已經不再是我們用什麼手段了。",
  ui_story_5089_50891001_66_dialog_content = "百工院竟然會站在你這邊……是璇璣卿嗎？",
  ui_story_5089_50891001_67_dialog_content = "她入獄並不是因為擅動機巧砲，而是因為發現了你的祕密吧？",
  ui_story_5089_50891001_68_dialog_content = "所以從你沒能真正關住她的那一刻開始，你就輸了。",
  ui_story_5089_50891001_69_dialog_content = "就算你還能站在鄴王的王座上——",
  ui_story_5089_50891001_70_dialog_content = "朝中官員，天下機巧師，都可能正暗中盯著你的一舉一動。",
  ui_story_5089_50891001_71_dialog_content = "火龍輦的軌道可以拆除，木牛流馬的轅軸可以損壞。",
  ui_story_5089_50891001_72_dialog_content = "就算想換用馬車，馬匹都很有可能力有不逮。",
  ui_story_5089_50891001_73_dialog_content = "更何況，火龍輦之外的其他工具，都難以快速運輸那麼大量的貨物吧。",
  ui_story_5089_50891001_74_dialog_content = "當然最重要的一點還是……",
  ui_story_5089_50891001_75_dialog_content = "在眾人的注視下，你要怎麼解釋，自己為何要將那麼多不曾記錄在案的火器送往別處？",
  ui_story_5089_50891001_76_dialog_content = "……",
  ui_story_5089_50891001_77_dialog_content = "抱歉了，鄴王殿下。",
  ui_story_5089_50891001_78_dialog_content = "之後會怎樣暫且不論——",
  ui_story_5089_50891001_79_dialog_content = "但現在的「勢」，在我這邊。",
  ui_story_5089_50891001_80_dialog_content = "原來如此。",
  ui_story_5089_50891001_81_dialog_content = "你堵的不是駿命的路，是我的。",
  ui_story_5089_50891001_82_dialog_content = "你說我們自投羅網時，怎麼沒想到，其實是我們在請君入甕呢？",
  ui_story_5089_50891001_83_dialog_content = "你已經沒有選擇了，候風卿。",
  ui_story_5089_50891001_84_dialog_content = "火器若不能及時送到，駿命必然前來調查。",
  ui_story_5089_50891001_85_dialog_content = "而根據你剛剛所言，你對駿命可算不上忠心，所作所為，怕是也經不起查。",
  ui_story_5089_50891001_86_dialog_content = "現在我們可以坐下來心平氣和地談談了嗎？",
  ui_story_5089_50891001_87_dialog_content = "暗鬼和駿命這個組織都沒有你想的那麼簡單，你的計畫根本就是與虎謀皮。",
  ui_story_5089_50891001_88_dialog_content = "哈哈哈，談談？本王乃鄴國之主！",
  ui_story_5089_50891001_89_dialog_content = "鄴國的道路，只能由本王一人執掌！",
  ui_story_5089_50891001_90_dialog_content = "絕不可能受你們掣肘——！",
  ui_story_5089_50891001_91_dialog_content = "<color=#e8d9bb>噗嗤——</color>",
  ui_story_5089_50891001_92_dialog_content = "<color=#e8d9bb>刀刃入肉的悶聲傳來。</color>",
  ui_story_5089_50891001_93_dialog_content = "<color=#e8d9bb>鮮血四濺。</color>",
  ui_story_5089_50891001_94_dialog_content = "候風卿——！",
  ui_story_5089_50891001_95_dialog_content = "<color=#e8d9bb>一根尖銳的金屬鉤尾從背後穿透了假鄴王的身軀。</color>",
  ui_story_5089_50891001_96_dialog_content = "那是……蠆！",
  ui_story_5089_50891001_97_dialog_content = "唉，老老實實地聽話不好嗎？",
  ui_story_5089_50891001_98_dialog_content = "就像我的機關術，踏實地汲取久經驗證的百家之長，才能做出這麼漂亮的成果。",
  ui_story_5089_50891001_99_dialog_content = "而不切實際的雄心壯志，可是會要命的。",
  ui_story_5089_50891001_100_dialog_content = "妳……大膽！",
  ui_story_5089_50891001_101_dialog_content = "小郡主倒是有一句話說得很對。",
  ui_story_5089_50891001_102_dialog_content = "你太小瞧駿命了。",
  ui_story_5089_50891001_103_dialog_content = "主上有令，鄴國已無用。",
  ui_story_5089_50891001_104_dialog_content = "這塊地可以交由我隨意處置，甚至還允我使用最大功率測試蠆的火力！",
  ui_story_5089_50891001_105_dialog_content = "哈哈，沒想到還有這種好事，還得多虧鄴王殿下你願意把燭陰火交給我啊。",
  ui_story_5089_50891001_106_dialog_content = "我看看……命令是叫我轟掉那座山嗎？",
  ui_story_5089_50891001_107_dialog_content = "走了，蠆。目標校準、能源整備……我們還有好多事要幹呢。",
  ui_story_5089_50891001_108_dialog_content = "<color=#e8d9bb>蠆的鉤尾猛地抽出，假鄴王隨即倒地。</color>",
  ui_story_5089_50891001_109_dialog_content = "對了，這還有個廢物的叛徒……",
  ui_story_5089_50891001_110_dialog_content = "駿命聽令，將他就地誅殺！",
  ui_story_5089_50891001_111_dialog_content = "大王——",
  ui_story_5089_50891001_112_dialog_content = "<color=#e8d9bb>遠處的璟衛軍正要動作，原本整齊劃一的陣型卻驀然一亂。</color>",
  ui_story_5089_50891001_113_dialog_content = "<color=#e8d9bb>竟有不少人拿起武器，刺向了身旁的同伴！</color>",
  ui_story_5089_50891001_114_dialog_content = "不妙，假鄴王那裡——",
  ui_story_5089_50891001_115_dialog_content = "灼灼海棠！",
  ui_story_5089_50891001_116_dialog_content = "你……",
  ui_story_5089_50891001_117_dialog_content = "別誤會，你的招攬我依舊敬謝不敏。",
  ui_story_5089_50891001_118_dialog_content = "但只要你還活著，我們就還能掌握一枚能用來對付駿命的棋子。",
  ui_story_5089_50891001_119_dialog_content = "而且還有些恩仇，你得和別人親自去算。",
  ui_story_5089_50891001_120_dialog_content = "何必呢……咳……",
  ui_story_5089_50891001_121_dialog_content = "現在不走……可無法再……後悔。",
  ui_story_5089_50891001_122_dialog_content = "就算要後悔，我該悔的也是沒趁著在宮裡孤注一擲，將你取而代之。",
  ui_story_5089_50891001_123_dialog_content = "那座山下還有無數無辜的百姓，還有大片要供給口糧、人們賴以生存的農田。",
  ui_story_5089_50891001_124_dialog_content = "如果這時候逃了，我還有什麼顏面自稱鄴國郡主？",
  ui_story_5089_50891001_125_dialog_content = "而且我和PlayerName公子還好好地站在這裡，沒到要抱頭鼠竄的時候！",
  ui_story_5089_50891001_126_dialog_content = "哈……真看不出，妳竟……",
  ui_story_5089_50891001_127_dialog_content = "比我更狂妄。",
  ui_story_5089_50891001_128_dialog_content = "但狂言……還是得……活下去再說。",
  ui_story_5089_50891001_129_dialog_content = "<color=#e8d9bb>璟衛軍間的戰鬥還沒結束，從工坊內，又衝出一批駿命刺客！</color>",
  ui_story_5089_50891002_1_dialog_content = "這一戰這麼打下去，怕是凶多吉少。",
  ui_story_5089_50891002_2_dialog_content = "玖姑娘。",
  ui_story_5089_50891002_3_dialog_content = "看到這樣的場景，你還是一句話都不想說嗎？",
  ui_story_5089_50891002_4_dialog_content = "……",
  ui_story_5089_50891002_5_dialog_content = "唉……？",
  ui_story_5089_50891002_6_dialog_content = "是誰！",
  ui_story_5089_50891002_7_dialog_content = "奉主上之命，清除礙事之人。",
  ui_story_5089_50891002_8_dialog_content = "嘖，連宮裡都滲透了嗎。",
  ui_story_5089_50891002_9_dialog_content = "雷光奇掣！",
  ui_story_5089_50891002_10_dialog_content = "……",
  ui_story_5089_50891002_11_dialog_content = "唔！",
  ui_story_5089_50891002_12_dialog_content = "滾開！",
  ui_story_5089_50891002_13_dialog_content = "玖姑娘，就算其他事情妳都不打算再管……",
  ui_story_5089_50891002_14_dialog_content = "難道還要任由自己的性命折在這些連名號都不敢報的鼠輩手上嗎！",
  ui_story_5089_50891002_15_dialog_content = "……",
  ui_story_5089_50891101_1_dialog_content = "呃啊——",
  ui_story_5089_50891101_2_dialog_content = "很好，丹棠，就這樣繼續——唔……",
  ui_story_5089_50891101_3_dialog_content = "PlayerName公子，你怎麼……額頭好燙！",
  ui_story_5089_50891101_4_dialog_content = "沒關係，只是能力使用過度，很快就……",
  ui_story_5089_50891101_5_dialog_content = "你這哪裡像很快就能好的樣子！",
  ui_story_5089_50891101_6_dialog_content = "……不對。",
  ui_story_5089_50891101_7_dialog_content = "我又不是第一天認識你，你的能力如何我心中有數。",
  ui_story_5089_50891101_8_dialog_content = "雖說敵數眾多，但如今的戰鬥強度絕沒道理讓你倒下。",
  ui_story_5089_50891101_9_dialog_content = "你究竟在做什麼？",
  ui_story_5089_50891101_10_dialog_content = "……被發現了啊。",
  ui_story_5089_50891101_11_dialog_content = "抱歉，我之前就想告訴妳的，只是一直找不到機會。",
  ui_story_5089_50891101_12_dialog_content = "現在的話……直接讓妳看比較快。",
  ui_story_5089_50891101_13_dialog_content = "什麼？",
  ui_story_5089_50891101_14_dialog_content = "感應。",
  ui_story_5089_50891101_15_dialog_content = "終於來了啊。",
  ui_story_5089_50891101_16_dialog_content = "等妳很久了，郡主。",
  ui_story_5089_50891101_17_dialog_content = "璇璣卿！還有……妳那邊……",
  ui_story_5089_50891101_18_dialog_content = "嗯，雖然很想和妳敘敘舊，但我這邊還有些不請自來的惡客。",
  ui_story_5089_50891101_19_dialog_content = "璇極，身後！",
  ui_story_5089_50891101_20_dialog_content = "雷光奇掣！",
  ui_story_5089_50891101_21_dialog_content = "多謝PlayerName公子。",
  ui_story_5089_50891101_22_dialog_content = "難道，PlayerName公子一直同時指揮著那邊的戰鬥？！所以負擔才會這麼大。",
  ui_story_5089_50891101_23_dialog_content = "沒錯，而且郡主，妳也該問問他和我的感應連接維持了多久。",
  ui_story_5089_50891101_24_dialog_content = "……",
  ui_story_5089_50891101_25_dialog_content = "PlayerName公子？",
  ui_story_5089_50891101_26_dialog_content = "也、也沒多久啊……從昨天和璇極見面結束才開始的。",
  ui_story_5089_50891101_27_dialog_content = "一天一夜。",
  ui_story_5089_50891101_28_dialog_content = "誰讓璇極很多話都沒說清楚……",
  ui_story_5089_50891101_29_dialog_content = "而且我有注意的，沒事發生時不會保持太緊密的連接……",
  ui_story_5089_50891101_30_dialog_content = "但為了不中斷，你到現在為止都沒有好好睡過覺吧。",
  ui_story_5089_50891101_31_dialog_content = "……",
  ui_story_5089_50891101_32_dialog_content = "甚至還不只我一個。",
  ui_story_5089_50891101_33_dialog_content = "關於這點，我得跟阿玖道歉才行。",
  ui_story_5089_50891101_34_dialog_content = "昨晚妳說了那些話，讓我覺得妳可能會衝動行事，所以偷偷和妳建立了感應連接。",
  ui_story_5089_50891101_35_dialog_content = "妳和鄴王的那場戰鬥，我也看到了。",
  ui_story_5089_50891101_36_dialog_content = "我明白你的心情，可是……",
  ui_story_5089_50891101_37_dialog_content = "小心！",
  ui_story_5089_50891101_38_dialog_content = "唔嗯……",
  ui_story_5089_50891101_39_dialog_content = "丹棠！妳受傷了？！",
  ui_story_5089_50891101_40_dialog_content = "唔！",
  ui_story_5089_50891101_41_dialog_content = "阿玖！現在狀況緊急，多一個人也好，來幫幫我們吧。",
  ui_story_5089_50891101_42_dialog_content = "我，並不是……",
  ui_story_5089_50891101_43_dialog_content = "<color=#e8d9bb>良久，阿玖嘆息一聲。</color>",
  ui_story_5089_50891101_44_dialog_content = "<color=#e8d9bb>她沒有說話，只是拿起刺客掉在旁邊的匕首，刺向正與璇極纏鬥的駿命者。</color>",
  ui_story_5089_50891101_45_dialog_content = "唔！",
  ui_story_5089_50891101_46_dialog_content = "<color=#e8d9bb>他驚慌躲閃，匕首卻只劃出一道扭曲的弧度，掠過他身邊後脫手，彈到了牆邊。</color>",
  ui_story_5089_50891101_47_dialog_content = "玖姑娘，妳……",
  ui_story_5089_50891101_48_dialog_content = "以前，刀劍就如同我的身體。",
  ui_story_5089_50891101_49_dialog_content = "受傷也好，染血也罷，都無關痛癢。",
  ui_story_5089_50891101_50_dialog_content = "劍刃該走的軌跡無比清晰——皆指向報恩兩字。",
  ui_story_5089_50891101_51_dialog_content = "但如今，我再看不清劍軌，刀劍便也拋棄了我。",
  ui_story_5089_50891101_52_dialog_content = "如你所見，我已無法揮劍了。",
  ui_story_5089_50891101_53_dialog_content = "阿玖……",
  ui_story_5089_50891101_54_dialog_content = "PlayerName公子，戰況緊急，沒時間與無關之人廢話。",
  ui_story_5089_50891101_55_dialog_content = "我之前竟還幾度猶豫，現在看來，放棄這樣一個護衛真是再正確不過。",
  ui_story_5089_50891101_56_dialog_content = "丹棠？",
  ui_story_5089_50891101_57_dialog_content = "她十年如一日地鑽研劍術，卻能一夕之間前功盡棄。",
  ui_story_5089_50891101_58_dialog_content = "想來教她劍術的那所謂天下第一劍客，也不過是浪得虛名。",
  ui_story_5089_50891101_59_dialog_content = "……是我學藝不精，殿下不該如此詆毀我的恩師。",
  ui_story_5089_50891101_60_dialog_content = "恩師？不見得吧。",
  ui_story_5089_50891101_61_dialog_content = "他的授藝之恩，可沒見妳放在劍上。",
  ui_story_5089_50891101_62_dialog_content = "……",
  ui_story_5089_50891101_63_dialog_content = "妳要算恩仇，我便與妳算恩仇。",
  ui_story_5089_50891101_64_dialog_content = "大到父母生養，鄰里照拂，師長傳道受業。",
  ui_story_5089_50891101_65_dialog_content = "小到蜃風號上，沒有月白盡心，璇璣卿賣力，我們怕是也早已葬身海底。",
  ui_story_5089_50891101_66_dialog_content = "更別說還有PlayerName公子至今都不肯棄妳於不顧。",
  ui_story_5089_50891101_67_dialog_content = "但原來這些都不曾被妳放在眼裡，真是白糟踐了這些心意。",
  ui_story_5089_50891101_68_dialog_content = "……殿下如今倒是能洞徹人心了。",
  ui_story_5089_50891101_69_dialog_content = "我對諸位虧欠良多，我當然明白。",
  ui_story_5089_50891101_70_dialog_content = "可您自己又如何？",
  ui_story_5089_50891101_71_dialog_content = "我自認在您身邊盡忠職守，未曾有一刻懈怠。",
  ui_story_5089_50891101_72_dialog_content = "您不依舊不發一言，便將我棄如敝履！",
  ui_story_5089_50891101_73_dialog_content = "這不是還會生氣嗎。",
  ui_story_5089_50891101_74_dialog_content = "我還以為妳早就成了個無血無淚的偶人了呢。",
  ui_story_5089_50891101_75_dialog_content = "讓殿下失望了？",
  ui_story_5089_50891101_76_dialog_content = "是啊。",
  ui_story_5089_50891101_77_dialog_content = "既然還有七情六欲，既然還知道自己受了旁人的關心。",
  ui_story_5089_50891101_78_dialog_content = "為何妳的劍卻只囿於那一份恩仇！",
  ui_story_5089_50891101_79_dialog_content = "殿下……？",
  ui_story_5089_50891101_80_dialog_content = "丹棠，後面——！",
  ui_story_5089_50891101_81_dialog_content = "灼灼海棠。",
  ui_story_5089_50891101_82_dialog_content = "<color=#e8d9bb>她沒有回頭，卻有無數海棠如海浪般鋪開，朝四周席捲而去。</color>",
  ui_story_5089_50891101_83_dialog_content = "有件事，我還是要讓妳知道。",
  ui_story_5089_50891101_84_dialog_content = "我將你丟下，並不是因為妳比起我要更忠於他人。而是因為妳不懂。",
  ui_story_5089_50891101_85_dialog_content = "<color=#e8d9bb>轉瞬間，目之所及，海棠開遍。</color>",
  ui_story_5089_50891101_86_dialog_content = "<color=#e8d9bb>所有敵人，但凡踏入這片綺麗的花海，都瞬間呆立在原地，茫然自失。</color>",
  ui_story_5089_50891101_87_dialog_content = "<color=#e8d9bb>丹棠立於其中，衣衫染血，眸光凜然。竟是最奪人心魄的一抹殊色。</color>",
  ui_story_5089_50891101_88_dialog_content = "大道五十，天衍四九，人遁其一。",
  ui_story_5089_50891101_89_dialog_content = "那不講道理的天尚且不曾絕人之路，妳又憑什麼自己畫地為牢！",
  ui_story_5089_50891101_90_dialog_content = "之前在客棧裡沒說完的話，我再說一遍。",
  ui_story_5089_50891101_91_dialog_content = "愛鳥華麗的羽毛，就將牠囚禁在籠裡。",
  ui_story_5089_50891101_92_dialog_content = "愛虎斑斕的皮毛，便殺死牠剝皮製衣。",
  ui_story_5089_50891101_93_dialog_content = "那才不是真正的喜愛。",
  ui_story_5089_50891101_94_dialog_content = "萬物生來自在，若是真的珍愛牠們，就該任飛鳥淩空，放虎嘯於山林。",
  ui_story_5089_50891101_95_dialog_content = "我迫妳去尋找真相，是因我不要那道枷鎖永遠束縛在妳身上。",
  ui_story_5089_50891101_96_dialog_content = "我不想再做只被妳聽命保護的郡主，我不要妳只能成為陰影裡見不得人的刀。",
  ui_story_5089_50891101_97_dialog_content = "我想要妳抬頭挺胸，自由自在地生活在陽光下。",
  ui_story_5089_50891101_98_dialog_content = "我想要妳的名字能與我並肩，我想要妳成為萬人稱頌的將軍。",
  ui_story_5089_50891101_99_dialog_content = "我要妳心甘情願地追隨於我。",
  ui_story_5089_50891101_100_dialog_content = "我要——",
  ui_story_5089_50891101_101_dialog_content = "做妳真正的主君！",
  ui_story_5089_50891101_102_dialog_content = "丹棠……殿下。",
  ui_story_5089_50891101_103_dialog_content = "妳已不再是我的護衛，我不會命令妳來幫忙。",
  ui_story_5089_50891101_104_dialog_content = "但如果不再有命令、恩仇，還有那面具下狹隘的視野束縛的妳，還願助我一臂之力……",
  ui_story_5089_50891101_105_dialog_content = "就站起來！用爬的也好——",
  ui_story_5089_50891101_106_dialog_content = "阿玖！",
  ui_story_5089_50891101_107_dialog_content = "到我身邊來！",
  ui_story_5089_50891101_108_dialog_content = "……我有沒有說過，丹棠殿下有的時候，真的很任性。",
  ui_story_5089_50891101_109_dialog_content = "沒有。",
  ui_story_5089_50891101_110_dialog_content = "所以妳來親自說給我聽。",
  ui_story_5089_50891101_111_dialog_content = "……",
  ui_story_5089_50891101_112_dialog_content = "領命。",
  ui_story_5089_50891101_113_dialog_content = "<color=#e8d9bb>片刻後。</color>",
  ui_story_5089_50891101_114_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5089_50891101_115_dialog_content = "<color=#e8d9bb>剛修補好的宮門迎來了第二次崩塌。</color>",
  ui_story_5089_50891101_116_dialog_content = "重犯越獄！快追！",
  ui_story_5089_50891101_117_dialog_content = "師姐，我回來了——這裡是怎麼回事？！",
  ui_story_5089_50891101_118_dialog_content = "沒什麼大事，只是我難得的鄰居又沒了，唉。",
  ui_story_5089_50891101_119_dialog_content = "剛剛我身邊刮過的那道風……是那位姑娘嗎。",
  ui_story_5089_50891101_120_dialog_content = "就拜託她先幫忙開路吧，打了這麼一架，我也得歇歇了。",
  ui_story_5089_50891101_121_dialog_content = "您真是……等等。",
  ui_story_5089_50891101_122_dialog_content = "說來剛剛那位姑娘，離開的時候是不是沒有帶武器？",
  ui_story_5089_50891101_123_dialog_content = "當然了，以她的本事，想將這宮殿劈開都輕輕鬆鬆。",
  ui_story_5089_50891101_124_dialog_content = "換我也不敢在要關她的時候還給她帶刀劍啊。",
  ui_story_5089_50891101_125_dialog_content = "那不是說她要赤手空拳對付整個皓津的璟衛軍？！您不擔心？",
  ui_story_5089_50891101_126_dialog_content = "有什麼好擔心的？",
  ui_story_5089_50891101_127_dialog_content = "之前她一臉陰沉的時候姑且不論，只說現在的話——",
  ui_story_5089_50891101_128_dialog_content = "只要她不想，就沒有人能攔得住她。",
  ui_story_5089_50891101_129_dialog_content = "找到了！逃犯在這裡，已經被包圍了！",
  ui_story_5089_50891101_130_dialog_content = "她手裡沒有武器，拿下她！",
  ui_story_5089_50891101_131_dialog_content = "看來你們不知道。",
  ui_story_5089_50891101_132_dialog_content = "對劍客而言，便是手無寸鐵，萬事萬物亦皆可為劍。",
  ui_story_5089_50891101_133_dialog_content = "<color=#e8d9bb>她一旋身，便融進了夜色。然後——</color>",
  ui_story_5089_50891101_134_dialog_content = "<color=#e8d9bb>飛花。</color>",
  ui_story_5089_50891101_135_dialog_content = "什……什麼東……西……",
  ui_story_5089_50891101_136_dialog_content = "<color=#e8d9bb>摘葉。</color>",
  ui_story_5089_50891101_137_dialog_content = "喂，你在幹什麼，好端端地躺下犯什麼病？趕緊——呃啊！",
  ui_story_5089_50891101_138_dialog_content = "<color=#e8d9bb>掃青竹。</color>",
  ui_story_5089_50891101_139_dialog_content = "躲開！快躲開！哇啊啊啊——",
  ui_story_5089_50891101_140_dialog_content = "<color=#e8d9bb>幽影一閃。</color>",
  ui_story_5089_50891101_141_dialog_content = "在那裡！吃我一槍！",
  ui_story_5089_50891101_142_dialog_content = "什麼？只是披風……那人……唔嗯……",
  ui_story_5089_50891101_143_dialog_content = "<color=#e8d9bb>刹那斬千軍。</color>",
  ui_story_5089_50891101_144_dialog_content = "這傢伙簡直……是惡鬼！",
  ui_story_5089_50891101_145_dialog_content = "不，我是人。",
  ui_story_5089_50891101_146_dialog_content = "與妖魔不同。",
  ui_story_5089_50891101_147_dialog_content = "我好不容易才想通其中道理，所以，能請你們讓開嗎？",
  ui_story_5089_50891101_148_dialog_content = "我趕時間。",
  ui_story_5089_50891101_149_dialog_content = "……上。",
  ui_story_5089_50891101_150_dialog_content = "唉。",
  ui_story_5089_50891101_151_dialog_content = "<color=#e8d9bb>玖彎腰，撿起一個倒下的璟衛軍身側掉落的長槍，隨手一折，變為劍勢。</color>",
  ui_story_5089_50891101_152_dialog_content = "別擋路。",
  ui_story_5089_50891101_153_dialog_content = "讓我——",
  ui_story_5089_50891101_154_dialog_content = "回殿下身邊去！",
  ui_story_5089_50891201_1_dialog_content = "PlayerName公子，找到綴戶的位置了嗎？",
  ui_story_5089_50891201_2_dialog_content = "就在前面！",
  ui_story_5089_50891201_3_dialog_content = "嘖。",
  ui_story_5089_50891201_4_dialog_content = "那麼多人，竟然都攔不住你們。",
  ui_story_5089_50891201_5_dialog_content = "人果然比不了機關獸。",
  ui_story_5089_50891201_6_dialog_content = "但本郡主還記得，上次那隻蠆可是被我們撕成了碎片呢。",
  ui_story_5089_50891201_7_dialog_content = "沒錯，而且我們的援軍馬上就到，妳還是趁現在投降比較好。",
  ui_story_5089_50891201_8_dialog_content = "援軍？真嚇人啊。",
  ui_story_5089_50891201_9_dialog_content = "但不管來多少人，都是肉體凡胎，你們確定要這樣對抗山崩？",
  ui_story_5089_50891201_10_dialog_content = "有這時間做無用功，不如快點去疏散人群。",
  ui_story_5089_50891201_11_dialog_content = "我剛剛稍微測算了一下，那座山一旦倒下來，這一整片區域的農田都會變成廢墟。",
  ui_story_5089_50891201_12_dialog_content = "怪不得要派我來做這麼莫名其妙的事。",
  ui_story_5089_50891201_13_dialog_content = "這裡是鄴國最重要的糧產地吧？看來今年要顆粒無收了。",
  ui_story_5089_50891201_14_dialog_content = "聽說濟國也在對鄴國的糧食動手腳，弄不好，一場饑荒就近在眼前。",
  ui_story_5089_50891201_15_dialog_content = "你不也是鄴國人嗎！為什麼要做這種事！",
  ui_story_5089_50891201_16_dialog_content = "我說過了吧？誰認同我的機關術，誰就是我的主子。",
  ui_story_5089_50891201_17_dialog_content = "不對，PlayerName公子，別被她的話牽著走。",
  ui_story_5089_50891201_18_dialog_content = "她是在拖延時間……綴戶，蠆在哪裡！",
  ui_story_5089_50891201_19_dialog_content = "哈哈，可惜，發現得太晚了。",
  ui_story_5089_50891201_20_dialog_content = "看到遠處那個光點了嗎？",
  ui_story_5089_50891201_21_dialog_content = "蠆的攻擊已經準備就緒，燭陰火的能源全開，馬上，那座山就會像花一樣——砰！",
  ui_story_5089_50891201_22_dialog_content = "這樣炸開喔。",
  ui_story_5089_50891201_23_dialog_content = "妳瘋了嗎？如果真是這樣，妳繼續待在這裡也會死的。",
  ui_story_5089_50891201_24_dialog_content = "我自有保命的本事。",
  ui_story_5089_50891201_25_dialog_content = "重要的是，這可是蠆重生後第一次全力攻擊，我當然要在最近的地方觀測效果。",
  ui_story_5089_50891201_26_dialog_content = "欣喜吧，兩位，這種景象不是誰都有機會見的。",
  ui_story_5089_50891201_27_dialog_content = "……PlayerName公子，先別管她，去阻止蠆！",
  ui_story_5089_50891201_28_dialog_content = "來不及了。",
  ui_story_5089_50891201_29_dialog_content = "<color=#e8d9bb>轟！！！</color>",
  ui_story_5089_50891201_30_dialog_content = "<color=#e8d9bb>刺目的光束擊穿了厚重的山體，無數大大小小的碎石如雨般從天而降。</color>",
  ui_story_5089_50891201_31_dialog_content = "璟衛軍！把候——大王帶走！然後去搜索周圍還有沒有留下的百姓，救援後立刻撤退！",
  ui_story_5089_50891201_32_dialog_content = "把聊天對象就這麼扔下，可不是郡主應有的禮儀。",
  ui_story_5089_50891201_33_dialog_content = "<color=#e8d9bb>一隻機關獸混在崩落的碎石中，襲向丹棠！</color>",
  ui_story_5089_50891201_34_dialog_content = "小心——！",
  ui_story_5089_50891201_35_dialog_content = "前方危險，不能過去。",
  ui_story_5089_50891201_36_dialog_content = "唉，在下都跟您從夕陽西下說到月上中天了，您怎麼就不相信呢？",
  ui_story_5089_50891201_37_dialog_content = "在下的卦象顯示，這個方位恐有天崩地裂之災。",
  ui_story_5089_50891201_38_dialog_content = "除非趕緊將這把劍送去給它的主人，才能挽狂瀾於既倒，扶大廈之將傾啊。",
  ui_story_5089_50891201_39_dialog_content = "真出事有璟衛軍解決，你不能過去。",
  ui_story_5089_50891201_40_dialog_content = "唉，您還是行個方便——",
  ui_story_5089_50891201_41_dialog_content = "<color=#e8d9bb>轟！！！</color>",
  ui_story_5089_50891201_42_dialog_content = "山……怎麼會！",
  ui_story_5089_50891201_43_dialog_content = "看，在下說什麼來著？",
  ui_story_5089_50891201_44_dialog_content = "時間不等人，在下先走了！",
  ui_story_5089_50891201_45_dialog_content = "等等，你——",
  ui_story_5089_50891201_46_dialog_content = "<color=#e8d9bb>旁邊彷彿突然刮過一陣暗色的風。</color>",
  ui_story_5089_50891201_47_dialog_content = "剛剛，還有人經過嗎？",
  ui_story_5089_50891201_48_dialog_content = "灼灼海棠！",
  ui_story_5089_50891201_49_dialog_content = "唔！",
  ui_story_5089_50891201_50_dialog_content = "比起在海上時，你變強了不少啊。",
  ui_story_5089_50891201_51_dialog_content = "不是誰都像妳一樣，只知道抱著既有的東西踟躕不前。",
  ui_story_5089_50891201_52_dialog_content = "呵，說得好聽。",
  ui_story_5089_50891201_53_dialog_content = "都出來吧！",
  ui_story_5089_50891201_54_dialog_content = "我倒要看看你能不能在這些「既有的東西」手下活下來。",
  ui_story_5089_50891201_55_dialog_content = "唔！",
  ui_story_5089_50891201_56_dialog_content = "（丹棠的狀態已經很勉強了，不能再這麼耗下去。）",
  ui_story_5089_50891201_57_dialog_content = "（但那座山還有大半搖搖欲墜沒有倒下來……該怎麼辦！）",
  ui_story_5089_50891201_58_dialog_content = "<color=#e8d9bb>唰——</color>",
  ui_story_5089_50891201_59_dialog_content = "<color=#e8d9bb>濃稠的夜色裡，切出一道迅雷。</color>",
  ui_story_5089_50891201_60_dialog_content = "阿玖！",
  ui_story_5089_50891201_61_dialog_content = "太慢了！",
  ui_story_5089_50891201_62_dialog_content = "丹棠殿下，請考慮一下實際情況，我已經用了最快的速度。",
  ui_story_5089_50891201_63_dialog_content = "不過，還是要說聲抱歉。",
  ui_story_5089_50891201_64_dialog_content = "我回來晚了。",
  ui_story_5089_50891201_65_dialog_content = "妳知道就好。",
  ui_story_5089_50891201_66_dialog_content = "嘖，礙事的傢伙。",
  ui_story_5089_50891201_67_dialog_content = "但就憑你們三個，應付得了整個工坊的機關獸嗎！",
  ui_story_5089_50891201_68_dialog_content = "吼！！！",
  ui_story_5089_50891201_69_dialog_content = "我一個人就夠了。",
  ui_story_5089_50891201_70_dialog_content = "想要靠近殿下和PlayerName公子，先問過我的劍意再說！",
  ui_story_5089_50891201_71_dialog_content = "（接下來的戰鬥，只能用「炫目」來形容。）",
  ui_story_5089_50891201_72_dialog_content = "（面對相繼撲來的機關獸，還有一刻不停的落石，阿玖竟硬是不曾移動一步。）",
  ui_story_5089_50891201_73_dialog_content = "（地上落下的武器、樹枝、葉片、石塊、甚至機關獸的殘骸……）",
  ui_story_5089_50891201_74_dialog_content = "（周圍能見到的一切，只要被阿玖拿在手裡，就彷彿開了鋒刃，勢不可擋。）",
  ui_story_5089_50891201_75_dialog_content = "霍如羿射九日落，矯如群帝驂龍翔。",
  ui_story_5089_50891201_76_dialog_content = "來如雷霆收震怒，罷如江海凝清光。",
  ui_story_5089_50891201_77_dialog_content = "妳找到了，自己想要的劍嗎。",
  ui_story_5089_50891201_78_dialog_content = "嘎——",
  ui_story_5089_50891201_79_dialog_content = "喂，騙人的吧！怎麼可能有肉體凡胎做到這種地步！",
  ui_story_5089_50891201_80_dialog_content = "還沒完——！",
  ui_story_5089_50891201_81_dialog_content = "<color=#e8d9bb>但在她召出更多機關獸之前，阿玖已先一步來到她身後。</color>",
  ui_story_5089_50891201_82_dialog_content = "別動。",
  ui_story_5089_50891201_83_dialog_content = "唔！",
  ui_story_5089_50891201_84_dialog_content = "呵，就算抓住了我又如何？",
  ui_story_5089_50891201_85_dialog_content = "會有駿命的人去回收蠆，我最強的機關獸還是會在戰場上大發神威！",
  ui_story_5089_50891201_86_dialog_content = "而且就算妳再強，也已經阻止不了這座山崩塌！",
  ui_story_5089_50891201_87_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5089_50891201_88_dialog_content = "<color=#e8d9bb>礦山內擠壓的層岩發出不祥的聲響，一塊塊巨石以要幾乎要砸裂大地的氣勢墜下。</color>",
  ui_story_5089_50891201_89_dialog_content = "不行了，丹棠、阿玖，我們也快點離開吧。",
  ui_story_5089_50891201_90_dialog_content = "只能如此了，璟衛軍那邊應該已經疏散好了百姓。",
  ui_story_5089_50891201_91_dialog_content = "之後的事，之後再說吧。",
  ui_story_5089_50891201_92_dialog_content = "阿玖，妳在那發什麼呆？",
  ui_story_5089_50891201_93_dialog_content = "我能阻止。",
  ui_story_5089_50891201_94_dialog_content = "什麼？",
  ui_story_5089_50891201_95_dialog_content = "師父說，「驚霆劍」是足以開山分海的一劍。",
  ui_story_5089_50891201_96_dialog_content = "但妳師父不是沒教那招嗎？",
  ui_story_5089_50891201_97_dialog_content = "師父說這招不能教我，我之前也只以為是他藉口推託。",
  ui_story_5089_50891201_98_dialog_content = "但現在我好像才有些明白，他說得沒錯。",
  ui_story_5089_50891201_99_dialog_content = "「驚霆劍」沒辦法教，是因為它並不是真正的劍招。",
  ui_story_5089_50891201_100_dialog_content = "而是劍心。",
  ui_story_5089_50891201_101_dialog_content = "就算是這樣，但妳現在連把劍都沒有——",
  ui_story_5089_50891201_102_dialog_content = "幾位！快、快來幫幫在下！",
  ui_story_5089_50891201_103_dialog_content = "哎喲，哎喲喲，這麼多石頭可怎麼躲——",
  ui_story_5089_50891201_104_dialog_content = "李天閑，這時候你又來湊什麼熱鬧！",
  ui_story_5089_50891201_105_dialog_content = "還不是在下算卦——哎喲，不行不行，前面在下可過不去了。",
  ui_story_5089_50891201_106_dialog_content = "阿玖姑娘，在下把妳的劍帶來了，接著！",
  ui_story_5089_50891201_107_dialog_content = "想得美！",
  ui_story_5089_50891201_108_dialog_content = "唔！",
  ui_story_5089_50891201_109_dialog_content = "<color=#e8d9bb>劍被拋向空中的同時，幾隻火蟹齊齊撲向丹棠。</color>",
  ui_story_5089_50891201_110_dialog_content = "<color=#e8d9bb>玖被絆住腳步，劍被最後一隻火蟹抓著，衝進了落石最密集的區域。</color>",
  ui_story_5089_50891201_111_dialog_content = "<color=#e8d9bb>火蟹頃刻間就被壓扁，劍也落到一邊。</color>",
  ui_story_5089_50891201_112_dialog_content = "我去撿！",
  ui_story_5089_50891201_113_dialog_content = "PlayerName公子！/PlayerName閣下！",
  ui_story_5089_50891201_114_dialog_content = "感應！",
  ui_story_5089_50891201_115_dialog_content = "（只要能及時判斷石頭的落點，就可以穿過去！）",
  ui_story_5089_50891201_116_dialog_content = "拿到了！",
  ui_story_5089_50891201_117_dialog_content = "<color=#e8d9bb>轟！</color>",
  ui_story_5089_50891201_118_dialog_content = "<color=#e8d9bb>大地轟然震動，那搖搖欲墜支撐了許久的礦山，終於徹底倒下！</color>",
  ui_story_5089_50891201_119_dialog_content = "（糟糕，太多了，這下躲不開——）",
  ui_story_5089_50891201_120_dialog_content = "<color=#e8d9bb>金光一閃。</color>",
  ui_story_5089_50891201_121_dialog_content = "……石頭，全都被擋住了？",
  ui_story_5089_50891201_122_dialog_content = "<color=#e8d9bb>熟悉的金蓮虛影籠罩在上空，將所有危險擋在蓮瓣之外。</color>",
  ui_story_5089_50891201_123_dialog_content = "口袋裡有什麼在發熱？我看看，這裡應該只放了阿霓送我的……樹葉……？",
  ui_story_5089_50891201_124_dialog_content = "<color=#e8d9bb>那根本不是什麼隨手摘下的樹葉。</color>",
  ui_story_5089_50891201_125_dialog_content = "<color=#e8d9bb>而是一片流光溢彩的龍鱗。</color>",
  ui_story_5089_50891201_126_dialog_content = "……謝謝，阿霓。",
  ui_story_5089_50891201_127_dialog_content = "再見面的時候，不管多少點心我都請妳吃。",
  ui_story_5089_50891201_128_dialog_content = "阿玖，妳的劍！接住——",
  ui_story_5089_50891201_129_dialog_content = "多謝。",
  ui_story_5089_50891201_130_dialog_content = "<color=#e8d9bb>高山墜落的景象，宛如巨人隕落，天地傾頹。</color>",
  ui_story_5089_50891201_131_dialog_content = "<color=#e8d9bb>周圍嘈雜不斷，阿玖卻閉上了眼睛，將周圍的一切摒除在外。</color>",
  ui_story_5089_50891201_132_dialog_content = "師父，我好像事到如今才真正明白，究竟什麼是劍。",
  ui_story_5089_50891201_133_dialog_content = "大道五十，天衍四九，人遁其一。",
  ui_story_5089_50891201_134_dialog_content = "那不講道理的天尚且不曾絕人之路，妳又憑什麼自己畫地為牢！",
  ui_story_5089_50891201_135_dialog_content = "非要說一個期限的話，我想想……",
  ui_story_5089_50891201_136_dialog_content = "就到，你能不為報恩，也不為報仇地揮劍為止吧。",
  ui_story_5089_50891201_137_dialog_content = "玖姑娘，我問妳。",
  ui_story_5089_50891201_138_dialog_content = "人和暗鬼最大的差別是什麼？",
  ui_story_5089_50891201_139_dialog_content = "璇極大人，我果然還是太過愚鈍，竟一直沒能明白那個問題的意思。",
  ui_story_5089_50891201_140_dialog_content = "但好在，我身邊有能在迷茫之時，還願意拉我一把的人。",
  ui_story_5089_50891201_141_dialog_content = "所以，這就是我的答案了。",
  ui_story_5089_50891201_142_dialog_content = "人和妖魔最大的區別，就是我們並非被本能和命令操控的道具。",
  ui_story_5089_50891201_143_dialog_content = "就是我們不會沒了那些就只剩一片空虛。",
  ui_story_5089_50891201_144_dialog_content = "就是哪怕誤入迷途，哪怕墮入深淵，哪怕愚蠢到畫地為牢，也依舊能遇到無數溫暖的好意。",
  ui_story_5089_50891201_145_dialog_content = "帶你離開狹隘的陰影——",
  ui_story_5089_50891201_146_dialog_content = "堂堂正正地活在陽光下！",
  ui_story_5089_50891201_147_dialog_content = "<color=#e8d9bb>她倏然睜眼，以幾乎看不見的動作揮出一劍。</color>",
  ui_story_5089_50891201_148_dialog_content = "<color=#e8d9bb>隨即，山石崩裂，天地同吟。</color>",
  ui_story_5089_50891201_149_dialog_content = "<color=#e8d9bb>那是極盡淩厲，卻又極盡輕盈的一劍。</color>",
  ui_story_5089_50891201_150_dialog_content = "這一劍，不為報恩，也不為報仇。",
  ui_story_5089_50891201_151_dialog_content = "<color=#e8d9bb>只是想作為禮物，送給所有曾溫柔待她的朋友。</color>",
  ui_story_5089_50891201_152_dialog_content = "<color=#e8d9bb>劍光掠過碎石和大山，無匹的劍意霸道地碾碎了碰觸到的一切。</color>",
  ui_story_5089_50891201_153_dialog_content = "好厲害……",
  ui_story_5089_50891201_154_dialog_content = "<color=#e8d9bb>再抬頭，剛剛還在轟然墜落的大山，已成了一片塵埃。</color>",
  ui_story_5089_50891201_155_dialog_content = "<color=#e8d9bb>霜刃淩空，一劍驚霆。</color>",
  ui_story_5089_50891201_156_dialog_content = "<color=#e8d9bb>遠處的山嶺。</color>",
  ui_story_5089_50891201_157_dialog_content = "璇極師姐……剛剛那個攻擊，不會再來了吧。",
  ui_story_5089_50891201_158_dialog_content = "應該是不會了。",
  ui_story_5089_50891201_159_dialog_content = "我也沒想到，她的劍竟然能有這麼強的威力。",
  ui_story_5089_50891201_160_dialog_content = "這台蠆，隔了這麼遠都被劈成兩半了……咦？",
  ui_story_5089_50891201_161_dialog_content = "師姐……那個，該不會是燭陰火吧！",
  ui_story_5089_50891201_162_dialog_content = "我一直跟你說，機巧師做事要嚴謹。",
  ui_story_5089_50891201_163_dialog_content = "現在該叫他們燭火和陰火了。",
  ui_story_5089_50891201_164_dialog_content = "都什麼時候您還在開玩笑！",
  ui_story_5089_50891201_165_dialog_content = "這可是我們的師門重寶！現在！被！劈成兩半了啊——！",
  ui_story_5089_50891201_166_dialog_content = "還是精準地從中間等分呢。",
  ui_story_5089_50891201_167_dialog_content = "玖姑娘，真是幫了我一個大忙。",
  ui_story_5089_50891201_168_dialog_content = "您在說什麼啊！這下我們可怎麼和師門交待啊！",
  ui_story_5089_50891201_169_dialog_content = "這個我會處理，別擔心。",
  ui_story_5089_50891201_170_dialog_content = "好了，快去通知下面的其他同門，這裡的機關獸解決了，叫他們到那邊去幫忙吧。",
  ui_story_5089_50891201_171_dialog_content = "自家師門叛徒搞出的事情，也得幫著善後才行啊。",
  ui_story_5089_50891201_172_dialog_content = "是。",
  ui_story_5089_50891201_173_dialog_content = "呼。",
  ui_story_5089_50891201_174_dialog_content = "阿玖，妳沒事吧？",
  ui_story_5089_50891201_175_dialog_content = "無妨，只是有些脫力……",
  ui_story_5089_50891201_176_dialog_content = "等等，仔細一看，妳渾身上下不都是血嗎！妳就是拖著這樣的身體在戰鬥的？！",
  ui_story_5089_50891201_177_dialog_content = "快去治療！",
  ui_story_5089_50891201_178_dialog_content = "謝謝PlayerName閣下的關心，但是現在，我還有一件事要做。",
  ui_story_5089_50891201_179_dialog_content = "都這樣了妳還要幹什麼！",
  ui_story_5089_50891201_180_dialog_content = "丹棠！妳也說說她！",
  ui_story_5089_50891201_181_dialog_content = "PlayerName公子，這次就由她去吧。",
  ui_story_5089_50891201_182_dialog_content = "這一切，也該結束了。",
  ui_story_5089_50891201_183_dialog_content = "究竟是要做什麼……啊，我明白了。",
  ui_story_5089_50891201_184_dialog_content = "是該做個了斷。",
  ui_story_5089_50891201_185_dialog_content = "妳來了。",
  ui_story_5089_50891201_186_dialog_content = "嗯，我來了。",
  ui_story_5089_50891201_187_dialog_content = "來人，給我拿把劍來。",
  ui_story_5089_50891201_188_dialog_content = "大王！您還有傷在身，不能亂動啊！",
  ui_story_5089_50891201_189_dialog_content = "拿來。",
  ui_story_5089_50891201_190_dialog_content = "這是我欠她的。",
  ui_story_5089_50891201_191_dialog_content = "<color=#e8d9bb>阿玖從懷中拿出一張面具，戴在臉上。</color>",
  ui_story_5089_50891201_192_dialog_content = "請您賜教。",
  ui_story_5089_50891202_1_dialog_content = "<color=#e8d9bb>噹！</color>",
  ui_story_5089_50891202_2_dialog_content = "<color=#e8d9bb>兩人的身影最後在場中交錯過後，假鄴王的劍被挑飛到空中。</color>",
  ui_story_5089_50891202_3_dialog_content = "咳……咳咳……",
  ui_story_5089_50891202_4_dialog_content = "大王！大王！我們不打了，不打了！",
  ui_story_5089_50891202_5_dialog_content = "勝負，也已分曉。",
  ui_story_5089_50891202_6_dialog_content = "我輸了。",
  ui_story_5089_50891202_7_dialog_content = "……",
  ui_story_5089_50891202_8_dialog_content = "<color=#e8d9bb>啪嗒。</color>",
  ui_story_5089_50891202_9_dialog_content = "<color=#e8d9bb>玖的面具也被劍風切成兩半，落到地面。</color>",
  ui_story_5089_50891202_10_dialog_content = "至此，你我恩怨已消。",
  ui_story_5089_50891202_11_dialog_content = "嗯。",
  ui_story_5089_50891202_12_dialog_content = "妳走吧。",
  ui_story_5089_50891202_13_dialog_content = "<color=#e8d9bb>阿玖收起劍，朝著遠處的丹棠輕施一禮，便轉身離開。</color>",
  ui_story_5089_50891202_14_dialog_content = "<color=#e8d9bb>沒再回頭。</color>",
  ui_story_5089_50891300_1_dialog_content = "<color=#e8d9bb>濟國王宮</color>",
  ui_story_5089_50891300_2_dialog_content = "父王，父王！聽說我的未婚妻送東西來了！",
  ui_story_5089_50891300_3_dialog_content = "是啊。",
  ui_story_5089_50891300_4_dialog_content = "讓我看看，讓我看看！",
  ui_story_5089_50891300_5_dialog_content = "就是這些金子。",
  ui_story_5089_50891300_6_dialog_content = "咦？這不是我送他的追求禮物嗎？",
  ui_story_5089_50891300_7_dialog_content = "難道他不喜歡？我就知道，我的大英雄一定也不喜歡這些俗物。",
  ui_story_5089_50891300_8_dialog_content = "我得更用心準備禮物才行，嗯，現在就去！",
  ui_story_5089_50891300_9_dialog_content = "這小子……",
  ui_story_5089_50891300_10_dialog_content = "那位小郎君用這些金子，換了我們的人在鄴國收購的糧食，想來意圖已十分明顯。",
  ui_story_5089_50891300_11_dialog_content = "殿下準備如何？",
  ui_story_5089_50891300_12_dialog_content = "PlayerName是我親口承諾的濟國友人，之前救了皓津的恩情還未曾報答。",
  ui_story_5089_50891300_13_dialog_content = "他既然要插手其中，本王自當給他這個面子。",
  ui_story_5089_50891300_14_dialog_content = "只是下次鄴國再來挑釁，本王可就不會再客氣了。",
  ui_story_5089_50891300_15_dialog_content = "本當如此。",
  ui_story_5089_50891300_16_dialog_content = "<color=#e8d9bb>嘩啦——</color>",
  ui_story_5089_50891300_17_dialog_content = "<color=#e8d9bb>人來人往的碼頭上，又一艘大船揚帆啟航。</color>",
  ui_story_5089_50891300_18_dialog_content = "那之後，阿玖就沒再回來嗎？",
  ui_story_5089_50891300_19_dialog_content = "我既親手放了她自由，自然也該尊重她的選擇。",
  ui_story_5089_50891300_20_dialog_content = "就算她真的不再回來，我也會一直記著，自己曾有幸得到過這樣一名摯友。",
  ui_story_5089_50891300_21_dialog_content = "PlayerName公子呢，之後要怎麼辦？",
  ui_story_5089_50891300_22_dialog_content = "嗯？我們不是正在去濟國的船上嗎。",
  ui_story_5089_50891300_23_dialog_content = "還是丹棠妳說的，駿命是大家共同的敵人，要說服濟鄴兩國暫時放下爭鬥。",
  ui_story_5089_50891300_24_dialog_content = "我也得去把剩下的金子還回去，啊，還沒謝謝候風卿……呃，鄴王……他願意替我還這筆錢。",
  ui_story_5089_50891300_25_dialog_content = "說到這個，還繼續讓他當鄴王沒關係嗎？",
  ui_story_5089_50891300_26_dialog_content = "這也是沒有辦法的辦法。",
  ui_story_5089_50891300_27_dialog_content = "叔父神志不清，阿姐還沒做好執掌一國的準備，當下鄴國也承擔不起一點動盪了。",
  ui_story_5089_50891300_28_dialog_content = "候風卿雖有些自負，卻也是真心在為鄴國打算。",
  ui_story_5089_50891300_29_dialog_content = "而且如今還有璇璣卿跟百工院為首的朝中勢力牽制，他暫時也掀不起什麼風浪。",
  ui_story_5089_50891300_30_dialog_content = "但我不是在說這個，我是問你將來的打算。",
  ui_story_5089_50891300_31_dialog_content = "也是啊，去過了皓津，走過了璟良，我也想看看龍洲的其他地方。",
  ui_story_5089_50891300_32_dialog_content = "但離開艾斯特拉這麼久，是不是該先回去一趟，不然薇絲跟卡蓮她們要擔心了。",
  ui_story_5089_50891300_33_dialog_content = "丹棠妳怎麼看？",
  ui_story_5089_50891300_34_dialog_content = "公子說笑了。",
  ui_story_5089_50891300_35_dialog_content = "你又不是困籠之鳥，亦非在柙之獸，哪裡輪得到我來安排你的未來。",
  ui_story_5089_50891300_36_dialog_content = "不是這個，也不是那個，那我在丹棠眼裡是什麼啊？",
  ui_story_5089_50891300_37_dialog_content = "這個嘛……",
  ui_story_5089_50891300_38_dialog_content = "<color=#e8d9bb>朝陽下，她輕笑抬眸，鄭重的雙眼間滿溢著灼灼流光。</color>",
  ui_story_5089_50891300_39_dialog_content = "君是大鵬鳥。",
  ui_story_5089_50891300_40_dialog_content = "終將振翅動九霄。",
  ui_story_5089_50891300_41_dialog_content = "這個評價是不是太高了？",
  ui_story_5089_50891300_42_dialog_content = "怎麼會。",
  ui_story_5089_50891300_43_dialog_content = "喂！快看海上！有人，有人在追船哪！",
  ui_story_5089_50891300_44_dialog_content = "你睡昏頭了吧，海上怎麼可能有——龍女娘娘在上！真的有啊！",
  ui_story_5089_50891300_45_dialog_content = "那邊在吵什麼——嗚哇！",
  ui_story_5089_50891300_46_dialog_content = "那不是阿玖嗎？！",
  ui_story_5089_50891300_47_dialog_content = "<color=#e8d9bb>船已駛離岸邊好遠，卻有一道身影踏在水面之上，飛快地奔來。</color>",
  ui_story_5089_50891300_48_dialog_content = "<color=#e8d9bb>少頃，她便已靠近甲板，在無數的驚呼聲裡縱身一躍。</color>",
  ui_story_5089_50891300_49_dialog_content = "<color=#e8d9bb>阿玖帶著清涼的水氣落到我們面前。</color>",
  ui_story_5089_50891300_50_dialog_content = "丹棠殿下，既要出使別國，連個貼身護衛都不帶，是否太過大意？",
  ui_story_5089_50891300_51_dialog_content = "妳想好了？",
  ui_story_5089_50891300_52_dialog_content = "如果還要跟著我，再有像這次的事發生，我就不會這麼寬容了。",
  ui_story_5089_50891300_53_dialog_content = "想好了。",
  ui_story_5089_50891300_54_dialog_content = "這次，玖必不辱使命。",
  ui_story_5089_50891300_55_dialog_content = "那麼走吧。",
  ui_story_5089_50891300_56_dialog_content = "駿命威脅的是整個兆國，去過濟國之後，我們還得去其他諸侯國打探情況。",
  ui_story_5089_50891300_57_dialog_content = "如今局勢不穩，殿下何必親自涉險？濟國之外的諸侯國，大可命人代勞。",
  ui_story_5089_50891300_58_dialog_content = "馳騁天下，縱橫捭闔，乃是多少人求而不得的機遇。",
  ui_story_5089_50891300_59_dialog_content = "我自幼有志於此，怎可因一點隱於暗處的危機便放棄。",
  ui_story_5089_50891300_60_dialog_content = "而且，鯤鵬自由，天地無處不可去。",
  ui_story_5089_50891300_61_dialog_content = "若我連踏遍天下的膽量都沒有，又怎能期望有一天，會有隻鵬鳥伴我身側？",
  ui_story_5089_50891300_62_dialog_content = "前方，還有一趟漫長的旅行呢。",
  ui_story_5089_50891300_63_dialog_content = "<color=#e8d9bb>某處的茶館。</color>",
  ui_story_5089_50891300_64_dialog_content = "如此這般，這般如此，灼華郡主跟異鄉使者再度踏上了各自的旅程。",
  ui_story_5089_50891300_65_dialog_content = "這塊舞台表面上的風雲變幻，也總算平靜了些許。",
  ui_story_5089_50891300_66_dialog_content = "在下呢，也就趁機先偷個懶，給您講講這些奇聞軼事，換幾枚銅板養鳥兒。",
  ui_story_5089_50891300_67_dialog_content = "什麼，您說這是我編的本子？這可太冤枉在下了。",
  ui_story_5089_50891300_68_dialog_content = "剛剛所講之事句句屬實，有詩為證啊。",
  ui_story_5089_50891300_69_dialog_content = "刻海行舟畫波光，灼灼海棠開未央。",
  ui_story_5089_50891300_70_dialog_content = "春朔一夜魚龍舞，萬鈞風雷鎮海平。",
  ui_story_5089_50891300_71_dialog_content = "驚霆寒劍淩霜刃，妖邪羅刹歸塵煙。",
  ui_story_5089_50891300_72_dialog_content = "囚鳥破籠九霄動，從此逍遙天地寬。",
  ui_story_5089_50891300_73_dialog_content = "這名為《灼華行》的故事，就到此結束了。",
  ui_story_5089_50891300_74_dialog_content = "當然，主人公的旅途可不會就此終結，您要是對後續還有興趣啊——",
  ui_story_5089_50891300_75_dialog_content = "<color=#e8d9bb>啪！</color>",
  ui_story_5089_50891300_76_dialog_content = "<color=#e8d9bb>驚堂木一響，已翻到結尾的書卷緩緩收攏，燭火熄滅，帷幕落下。</color>",
  ui_story_5089_50891300_77_dialog_content = "且聽……呵呵，天涯海角，有緣再見。",
  ui_story_5089_50891400_1_dialog_content = "你，已經下定決心了嗎？",
  ui_story_5089_50891400_2_dialog_content = "邁出下一步，就意味著與現在的大家告別。",
  ui_story_5089_50891400_3_dialog_content = "你好不容易所建立起來的牽絆，都將遠去。",
  ui_story_5089_50891400_4_dialog_content = "即便如此，你還是願意為了她前往「遠方」，對嗎？",
  ui_story_5089_50891400_5_option_content = "對。",
  ui_story_5089_50891400_6_option_content = "沒錯，我決定了。",
  ui_story_5089_50891400_7_dialog_content = "……",
  ui_story_5089_50891400_8_dialog_content = "去了趟龍洲，你變果斷了啊。",
  ui_story_5089_50891400_9_dialog_content = "那，去道別吧。",
  ui_story_5089_50891400_10_dialog_content = "在最後的最後，和所有的朋友們。",
  ui_story_5089_50891400_11_dialog_content = "最後一次，讓我們繞艾斯特拉飛一圈吧？",
  ui_story_5089_50891400_12_dialog_content = "像最開始那樣，瀟灑地踏上旅途！",
  ui_story_5089_50891400_13_dialog_content = "大老遠跑過來，就是為了道個別？",
  ui_story_5089_50891400_14_dialog_content = "受不了你，你還會回來的吧。",
  ui_story_5089_50891400_15_option_content = "我也不確定",
  ui_story_5089_50891400_16_option_content = "嗯……",
  ui_story_5089_50891400_17_dialog_content = "哎，過來。",
  ui_story_5089_50891400_18_dialog_content = "男子漢啊，只要這樣抱一下，一切都在不言中。",
  ui_story_5089_50891400_19_dialog_content = "我知道你一定有自己的理由。",
  ui_story_5089_50891400_20_dialog_content = "……謝啦。一直以來幫了我們這麼多忙。",
  ui_story_5089_50891400_21_dialog_content = "要是什麼時候回來了，記得來這說一聲。",
  ui_story_5089_50891400_22_dialog_content = "過得不好的話，別忘了我這裡永遠有一個你的位置。",
  ui_story_5089_50891400_23_dialog_content = "嗯，我絕對會記得。",
  ui_story_5089_50891400_24_dialog_content = "可惡，你搞得我也變得傷感起來了。",
  ui_story_5089_50891400_25_dialog_content = "去吧，去和伊芙她們道個別。",
  ui_story_5089_50891400_26_dialog_content = "再見了，醒山。",
  ui_story_5089_50891400_27_dialog_content = "再見了，PlayerName。",
  ui_story_5089_50891400_28_dialog_content = "怎麼這樣……一下子要離開很久嗎？",
  ui_story_5089_50891400_29_dialog_content = "啊，也不一定，但我也不確定回程的日子……",
  ui_story_5089_50891400_30_dialog_content = "別哭呀！被醒山看到我就遭殃了！",
  ui_story_5089_50891400_31_dialog_content = "可是……",
  ui_story_5089_50891400_32_dialog_content = "總有一天會再見的啦！",
  ui_story_5089_50891400_33_dialog_content = "嗯，等我什麼時候再次「回歸」的那天。",
  ui_story_5089_50891400_34_dialog_content = "到那個時候，我再跟妳分享很多艾斯特拉看不到的東西吧。",
  ui_story_5089_50891400_35_dialog_content = "約好了喲。",
  ui_story_5089_50891400_36_dialog_content = "好，我跟妳約定！",
  ui_story_5089_50891400_37_dialog_content = "要打勾勾嗎？",
  ui_story_5089_50891400_38_dialog_content = "嗯！",
  ui_story_5089_50891400_39_dialog_content = "對了，我帶你去跟大家都說一聲吧。",
  ui_story_5089_50891400_40_dialog_content = "大家一直也很想見你。",
  ui_story_5089_50891400_41_dialog_content = "那位你介紹過來的「小姐」，你還沒見過她在這裡的樣子吧？",
  ui_story_5089_50891400_42_dialog_content = "還有還有，「不死鳥阿塔爾」大姐姐也……",
  ui_story_5089_50891400_43_dialog_content = "伊芙？",
  ui_story_5089_50891400_44_dialog_content = "對不起，明明說好了不能哭。",
  ui_story_5089_50891400_45_dialog_content = "可是……忽然就想起好多和你一起經歷的事情……",
  ui_story_5089_50891400_46_dialog_content = "是啊，好長一段時間了呢。",
  ui_story_5089_50891400_47_dialog_content = "夥伴一下子多了好多，大家也都有各式各樣的變化。",
  ui_story_5089_50891400_48_dialog_content = "果然我還是好喜歡這裡。",
  ui_story_5089_50891400_49_dialog_content = "像龍洲的火鍋一樣。",
  ui_story_5089_50891400_50_dialog_content = "所以我相信伊芙沒有問題的。",
  ui_story_5089_50891400_51_dialog_content = "因為大家還在伊芙的身邊。",
  ui_story_5089_50891400_52_dialog_content = "我......我明白了。",
  ui_story_5089_50891400_53_dialog_content = "我會等PlayerName回來，而且是和大家一起笑著等。",
  ui_story_5089_50891400_54_dialog_content = "走吧，去和大家道別。",
  ui_story_5089_50891400_55_dialog_content = "事情我已經聽說了。",
  ui_story_5089_50891400_56_dialog_content = "既然是薇絲的事情，我不會阻攔你們。",
  ui_story_5089_50891400_57_dialog_content = "假我也批給薇絲了，你還有什麼需求，都儘管說。",
  ui_story_5089_50891400_58_dialog_content = "沒事的，這樣就夠了。感謝妳和萊因哈特！",
  ui_story_5089_50891400_59_dialog_content = "這趟旅途去的是「未知」。",
  ui_story_5089_50891400_60_dialog_content = "不是多找幾個人就能解決的。",
  ui_story_5089_50891400_61_dialog_content = "話雖這麼說，但能幫上你一些忙還是好的。",
  ui_story_5089_50891400_62_dialog_content = "你要是不在的話，大家都會很寂寞。",
  ui_story_5089_50891400_63_dialog_content = "至少家裡蹲巴頓會特別無聊。",
  ui_story_5089_50891400_64_dialog_content = "不然讓貢露帶他多玩點遊戲吧？不打仗就悶在家裡可不好。",
  ui_story_5089_50891400_65_dialog_content = "呵，開玩笑的。",
  ui_story_5089_50891400_66_dialog_content = "那傢伙被自己的老長官看著，有得忙呢。",
  ui_story_5089_50891400_67_dialog_content = "緋居然跟我開玩笑了……",
  ui_story_5089_50891400_68_dialog_content = "或許，這就是你帶給我們的改變吧。",
  ui_story_5089_50891400_69_dialog_content = "就算大元帥也會受你影響，何況是我。",
  ui_story_5089_50891400_70_dialog_content = "……",
  ui_story_5089_50891400_71_dialog_content = "保重。",
  ui_story_5089_50891400_72_dialog_content = "嗯！",
  ui_story_5089_50891400_73_dialog_content = "在這在這！",
  ui_story_5089_50891400_74_dialog_content = "PlayerName——咱也來了。",
  ui_story_5089_50891400_75_dialog_content = "說拜拜。",
  ui_story_5089_50891400_76_dialog_content = "怎麼這時候巨像起飛就那麼快？",
  ui_story_5089_50891400_77_dialog_content = "喂——PlayerName！",
  ui_story_5089_50891400_78_dialog_content = "記得一天三餐要按時吃，在路上也別忘了照顧好自己！",
  ui_story_5089_50891400_79_dialog_content = "還要把薇絲也帶回來哦。",
  ui_story_5089_50891400_80_dialog_content = "好——等著我把薇絲帶回來吧！",
  ui_story_5089_50891400_81_dialog_content = "我一定會和她安全回來的！",
  ui_story_5089_50891400_82_dialog_content = "臭小子……薇絲是我們啟光人，他說拐走就拐走……",
  ui_story_5089_50891400_83_dialog_content = "您不去告別嗎？",
  ui_story_5089_50891400_84_dialog_content = "不要。",
  ui_story_5089_50891400_85_dialog_content = "那傢伙有一雙自由的翅膀，我沒必要再去增添重量。",
  ui_story_5089_50891400_86_dialog_content = "接下來是「PlayerName」自己的故事，自己的旅途。",
  ui_story_5089_50891400_87_dialog_content = "身為朋友，我所能做的，就是默默祝福那雙羽翼。",
  ui_story_5089_50891400_88_dialog_content = "……回去吧，我們自己不也還有決斷要下嗎？",
  ui_story_5089_50891400_89_dialog_content = "告別啊……",
  ui_story_5089_50891400_90_dialog_content = "……",
  ui_story_5089_50891400_91_dialog_content = "維多利亞大人、普律瑪、帕索洛都不在這……",
  ui_story_5089_50891400_92_dialog_content = "妳不是在這嗎？",
  ui_story_5089_50891400_93_dialog_content = "至少能和妳見上一面，親口說聲再見。",
  ui_story_5089_50891400_94_dialog_content = "真是太好了。",
  ui_story_5089_50891400_95_dialog_content = "不說再見的話，好像就少了點什麼。",
  ui_story_5089_50891400_96_dialog_content = "？！",
  ui_story_5089_50891400_97_dialog_content = "雖然沒見到普律瑪很可惜……",
  ui_story_5089_50891400_98_dialog_content = "不過維多利亞神通廣大，也許她會幫忙傳達，哈哈……",
  ui_story_5089_50891400_99_dialog_content = "實在不行的話——",
  ui_story_5089_50891400_100_dialog_content = "喂——隱修大師——",
  ui_story_5089_50891400_101_dialog_content = "拜託您把我的話傳遞給維多利亞她們吧——",
  ui_story_5089_50891400_102_dialog_content = "你在和誰說話？",
  ui_story_5089_50891400_103_dialog_content = "呵呵呵，會有人懂的。",
  ui_story_5089_50891400_104_dialog_content = "……",
  ui_story_5089_50891400_105_dialog_content = "我......",
  ui_story_5089_50891400_106_dialog_content = "希望你能夠順利回來。",
  ui_story_5089_50891400_107_dialog_content = "那當然了。",
  ui_story_5089_50891400_108_dialog_content = "再見。",
  ui_story_5089_50891400_109_dialog_content = "嗯，再見。",
  ui_story_5089_50891400_110_dialog_content = "……這樣就是最後一批貨了。",
  ui_story_5089_50891400_111_dialog_content = "影鎮總商會，還有……「空心粉」們能給你的支援，就這些了。",
  ui_story_5089_50891400_112_dialog_content = "來一趟影鎮，沒想到還能白拿這麼多物資……",
  ui_story_5089_50891400_113_dialog_content = "有些不好意思。",
  ui_story_5089_50891400_114_dialog_content = "你永遠是影鎮的朋友，是我們的朋友。",
  ui_story_5089_50891400_115_dialog_content = "放心收下吧。",
  ui_story_5089_50891400_116_dialog_content = "哇！嚇我一跳！",
  ui_story_5089_50891400_117_dialog_content = "哈哈哈，接下來你要前往的地方，可沒有影子照看你。",
  ui_story_5089_50891400_118_dialog_content = "萬事小心。",
  ui_story_5089_50891400_119_dialog_content = "嗯。",
  ui_story_5089_50891400_120_dialog_content = "……貝菲爾，交給妳了。",
  ui_story_5089_50891400_121_dialog_content = "……",
  ui_story_5089_50891400_122_dialog_content = "路克、斯莫奇、吉納維芙，還有那位納努塞爾長老都在後面等你。",
  ui_story_5089_50891400_123_dialog_content = "你真是艾斯特拉的大紅人，所有人都想來幫你送行。",
  ui_story_5089_50891400_124_dialog_content = "嗯……",
  ui_story_5089_50891400_125_dialog_content = "所以我也要和大家好好道別。",
  ui_story_5089_50891400_126_dialog_content = "還有妳，貝菲爾。",
  ui_story_5089_50891400_127_dialog_content = "......！",
  ui_story_5089_50891400_128_dialog_content = "……真的會去很久嗎？",
  ui_story_5089_50891400_129_dialog_content = "我不知道，甚至可能都不回來了。",
  ui_story_5089_50891400_130_dialog_content = "但是，我不會忘記大家的。",
  ui_story_5089_50891400_131_dialog_content = "只要能夠回來，我會拼盡全力。",
  ui_story_5089_50891400_132_dialog_content = "PlayerName......",
  ui_story_5089_50891400_133_dialog_content = "好好保重。",
  ui_story_5089_50891400_134_dialog_content = "要是路上看到有趣的小說，我會帶回來給妳的。",
  ui_story_5089_50891400_135_dialog_content = "到時候就去咖啡館裡和大家一起讀！",
  ui_story_5089_50891400_136_dialog_content = "所以……",
  ui_story_5089_50891400_137_dialog_content = "再見，貝菲爾。",
  ui_story_5089_50891400_138_dialog_content = "找到了，他在那裡。",
  ui_story_5089_50891400_139_dialog_content = "PlayerName～",
  ui_story_5089_50891400_140_dialog_content = "再見啦～",
  ui_story_5089_50891400_141_dialog_content = "啊……",
  ui_story_5089_50891400_142_dialog_content = "再見了——",
  ui_story_5089_50891400_143_dialog_content = "但願你們的前路，還有歌和希望常伴……",
  ui_story_5089_50891400_144_dialog_content = "……再見了。",
  ui_story_5089_50891400_145_dialog_content = "啊？妳說妳想一起去？",
  ui_story_5089_50891400_146_dialog_content = "也、也不是那麼想和你一起去啦。",
  ui_story_5089_50891400_147_dialog_content = "可是探索「幻想之地」什麼的，好像有點意思。",
  ui_story_5089_50891400_148_dialog_content = "就連安頓都會心動，我比他又閒一點，有興趣不是很正常嗎？",
  ui_story_5089_50891400_149_dialog_content = "呵呵，到最後一刻都不說真心話的話，是會後悔的呦。",
  ui_story_5089_50891400_150_dialog_content = "……",
  ui_story_5089_50891400_151_dialog_content = "身為艾斯特拉的啟明星，就這樣讓你踏上旅途，確實令人不安。",
  ui_story_5089_50891400_152_dialog_content = "噢？要不這樣？",
  ui_story_5089_50891400_153_dialog_content = "導航員先生一聲令下，我再逮五個打手過來給你。",
  ui_story_5089_50891400_154_dialog_content = "什麼屬性都有，什麼路都走得動……",
  ui_story_5089_50891400_155_dialog_content = "可是，我能預見你的未來。",
  ui_story_5089_50891400_156_dialog_content = "在那個地方，你仍能擁有無限光芒。",
  ui_story_5089_50891400_157_dialog_content = "或許，那才是你真正要為之奮鬥的地方。",
  ui_story_5089_50891400_158_dialog_content = "無比現實，又充滿幻想——你將為了更好的一切戰鬥。",
  ui_story_5089_50891400_159_dialog_content = "那是你自己的路。",
  ui_story_5089_50891400_160_dialog_content = "雖然我們萬般擔心，但唯有對你獻上祝福。",
  ui_story_5089_50891400_161_dialog_content = "謝謝，有這樣的祝福，我就已經很安心了。",
  ui_story_5089_50891400_162_dialog_content = "啊？沒有我們經歷冒險再升級，兩刀砍死罪靈的後續發展空間嗎？",
  ui_story_5089_50891400_163_dialog_content = "我快悶死了。",
  ui_story_5089_50891400_164_dialog_content = "但弗雷雅在這裡待得很開心吧？",
  ui_story_5089_50891400_165_dialog_content = "話是這麼說……",
  ui_story_5089_50891400_166_dialog_content = "以前的故鄉去看過了，家裡的「至寶」確認了，拿到了新的衣服……",
  ui_story_5089_50891400_167_dialog_content = "一覺醒來，好像突然獲得了某種偏愛一樣。",
  ui_story_5089_50891400_168_dialog_content = "可是我弗雷雅大人，才不會就這樣滿足好嗎？",
  ui_story_5089_50891400_169_dialog_content = "你跑過來說了一堆新的東西，還不讓我們去。",
  ui_story_5089_50891400_170_dialog_content = "搞得我現在拳頭技癢難耐……",
  ui_story_5089_50891400_171_dialog_content = "導航員先生，還是你讓我打個半拳吧？",
  ui_story_5089_50891400_172_dialog_content = "畢竟我的夢可是——",
  ui_story_5089_50891400_173_dialog_content = "再見了，弗雷雅。",
  ui_story_5089_50891400_174_dialog_content = "……",
  ui_story_5089_50891400_175_dialog_content = "能夠看到妳笑得這麼開心，這麼「真實」。",
  ui_story_5089_50891400_176_dialog_content = "我就很安心了。",
  ui_story_5089_50891400_177_dialog_content = "……要好好向他們道別喔。",
  ui_story_5089_50891400_178_dialog_content = "我會的。",
  ui_story_5089_50891400_179_dialog_content = "伯利恆，再見。",
  ui_story_5089_50891400_180_dialog_content = "再見了。",
  ui_story_5089_50891400_181_dialog_content = "你要見的人們，就在宮殿外面。",
  ui_story_5089_50891400_182_dialog_content = "去吧，PlayerName。",
  ui_story_5089_50891400_183_dialog_content = "再見，札莉雅。",
  ui_story_5089_50891400_184_dialog_content = "我想去的。",
  ui_story_5089_50891400_185_dialog_content = "欸？",
  ui_story_5089_50891400_186_dialog_content = "不，沒什麼。",
  ui_story_5089_50891400_187_dialog_content = "再見……",
  ui_story_5089_50891400_188_dialog_content = "哎呀呀……過來，讓老人家傳遞點人生哲理。",
  ui_story_5089_50891400_189_dialog_content = "喂！",
  ui_story_5089_50891400_190_dialog_content = "這機會可不多得，你也就在女王和山神這樣的老人家面前還能當少女了。",
  ui_story_5089_50891400_191_dialog_content = "喂！！！",
  ui_story_5089_50891400_192_dialog_content = "……所以，這裡就是最後一站。",
  ui_story_5089_50891400_193_dialog_content = "PlayerName……一定要回來。",
  ui_story_5089_50891400_194_dialog_content = "嗯，再見了，零恩。也拜託你把道別轉達給大家了。",
  ui_story_5089_50891400_195_dialog_content = "啊呀，該把舞台留給主角了。",
  ui_story_5089_50891400_196_dialog_content = "走吧，大家。",
  ui_story_5089_50891400_197_dialog_content = "……",
  ui_story_5089_50891400_198_dialog_content = "……",
  ui_story_5089_50891400_199_dialog_content = "怎麼了，你不是來道別的嗎？",
  ui_story_5089_50891400_200_dialog_content = "不知道為什麼，忽然有點說不出口……",
  ui_story_5089_50891400_201_dialog_content = "那讓摩耶來說！",
  ui_story_5089_50891400_202_dialog_content = "咦？摩耶？",
  ui_story_5089_50891400_203_dialog_content = "不對，怎麼是阿克琉斯！！！",
  ui_story_5089_50891400_204_dialog_content = "……她在我後面說話。",
  ui_story_5089_50891400_205_dialog_content = "聽說PlayerName要走了，摩耶馬上就來找你啦！",
  ui_story_5089_50891400_206_dialog_content = "不過摩耶忘記路了，還是這位好心的大哥哥帶我來的。",
  ui_story_5089_50891400_207_dialog_content = "怪不得我去找妳的時候找不到……",
  ui_story_5089_50891400_208_dialog_content = "妳這樣亂跑，傑諾和艾維斯會擔心的。",
  ui_story_5089_50891400_209_dialog_content = "咳咳。",
  ui_story_5089_50891400_210_dialog_content = "艾、艾維「是」會傷心的。",
  ui_story_5089_50891400_211_dialog_content = "是「艾維斯」哥哥哦。",
  ui_story_5089_50891400_212_dialog_content = "咳咳咳！",
  ui_story_5089_50891400_213_dialog_content = "你做好決定了嗎？",
  ui_story_5089_50891400_214_dialog_content = "離開這裡，不用我們幫忙。",
  ui_story_5089_50891400_215_dialog_content = "嗯。總不能一直依賴大家。",
  ui_story_5089_50891400_216_dialog_content = "……",
  ui_story_5089_50891400_217_dialog_content = "你們已經有嶄新的未來……",
  ui_story_5089_50891400_218_dialog_content = "我希望你們能過上自己想要的日子。",
  ui_story_5089_50891400_219_dialog_content = "如果，我們之中有人想要的生活，就是「和你在一起」呢？",
  ui_story_5089_50891400_220_dialog_content = "欸，這……",
  ui_story_5089_50891400_221_dialog_content = "如果你把選擇的權利交給我們自己，那就請你要重視每個人的想法。",
  ui_story_5089_50891400_222_dialog_content = "也許有人不願離你而去。",
  ui_story_5089_50891400_223_dialog_content = "也許有人還無法放下和你的旅行。",
  ui_story_5089_50891400_224_dialog_content = "也許那樣的人就在你的身邊。",
  ui_story_5089_50891400_225_dialog_content = "呵，或許會把你的巨像塞滿。",
  ui_story_5089_50891400_226_dialog_content = "是、是真的嗎？",
  ui_story_5089_50891400_227_dialog_content = "那摩耶也要去。",
  ui_story_5089_50891400_228_dialog_content = "住不下的話，摩耶可以讓先祖大人帶我。",
  ui_story_5089_50891400_229_dialog_content = "那水族館怎麼辦？",
  ui_story_5089_50891400_230_dialog_content = "咦咦咦咦？！！！",
  ui_story_5089_50891400_231_dialog_content = "摩耶著急PlayerName的事情，一時忘了！",
  ui_story_5089_50891400_232_dialog_content = "唔......",
  ui_story_5089_50891400_233_dialog_content = "不用勉強自己的，摩耶。",
  ui_story_5089_50891400_234_dialog_content = "這不是一時能決定的事情。",
  ui_story_5089_50891400_235_dialog_content = "妳不用急著選擇。我不會覺得妳不去，就是和我感情不夠好啦。",
  ui_story_5089_50891400_236_dialog_content = "真的嗎？",
  ui_story_5089_50891400_237_dialog_content = "真的。",
  ui_story_5089_50891400_238_dialog_content = "那……摩耶會在水族館等你回來。",
  ui_story_5089_50891400_239_dialog_content = "嗯，我們約好了。",
  ui_story_5089_50891400_240_dialog_content = "太好了！摩耶這就回去和傑諾哥哥、艾維斯哥哥說！",
  ui_story_5089_50891400_241_dialog_content = "咳咳咳咳咳——",
  ui_story_5089_50891400_242_dialog_content = "看來，你已經明白了。",
  ui_story_5089_50891400_243_dialog_content = "「道別」，意味著一時的分離。",
  ui_story_5089_50891400_244_dialog_content = "但那未必是永恆的。",
  ui_story_5089_50891400_245_dialog_content = "既然你希望總有一日會回來，就不必把「道別」放入最沉重的想法中。",
  ui_story_5089_50891400_246_dialog_content = "你也不必逼自己去說說不出口的「道別」。",
  ui_story_5089_50891400_247_dialog_content = "屬於你的故事還在繼續。",
  ui_story_5089_50891400_248_dialog_content = "做好你的選擇，讓故事走向心中的完美結局吧。",
  ui_story_5089_50891400_249_dialog_content = "阿克琉斯……",
  ui_story_5089_50891400_250_dialog_content = "PlayerName，再見。",
  ui_story_5089_50891400_251_dialog_content = "「空之末裔」，飛入那更廣闊的天空吧。",
  ui_story_5089_50891400_252_dialog_content = "……",
  ui_story_5089_50891400_253_dialog_content = "……",
  ui_story_5089_50891400_254_dialog_content = "卡蓮，我……",
  ui_story_5089_50891400_255_dialog_content = "臨空者號來了。",
  ui_story_5089_50891400_256_dialog_content = "出發的時間到了吧？",
  ui_story_5089_50891400_257_dialog_content = "嗯。",
  ui_story_5089_50891400_258_dialog_content = "……簡直就像一開始那樣呢。",
  ui_story_5089_50891400_259_dialog_content = "臨空者號、我、你，還有薇絲，在白夜城……",
  ui_story_5089_50891400_260_dialog_content = "……",
  ui_story_5089_50891400_261_dialog_content = "再——",
  ui_story_5089_50891400_262_dialog_content = "一起走吧，卡蓮。",
  ui_story_5089_50891400_263_dialog_content = "就像最初那樣？",
  ui_story_5089_50891400_264_dialog_content = "就像最初那樣。",
  ui_story_5089_50891400_265_dialog_content = "……",
  ui_story_5089_50891400_266_dialog_content = "走吧！PlayerName！",
  ui_story_5089_50891400_267_dialog_content = "好慢啊，PlayerName。",
  ui_story_5089_50891400_268_dialog_content = "我在這都忙暈啦。",
  ui_story_5089_50891400_269_dialog_content = "薇絲，我……",
  ui_story_5089_50891400_270_dialog_content = "我就知道你會來的。",
  ui_story_5089_50891400_271_dialog_content = "沒想到居然花了這麼久。",
  ui_story_5089_50891400_272_dialog_content = "把人突然帶走實在是說不過去……",
  ui_story_5089_50891400_273_dialog_content = "我不也是嘛？",
  ui_story_5089_50891400_274_dialog_content = "真是的，都這麼久了，你還見外。",
  ui_story_5089_50891400_275_dialog_content = "會讓人傷心的，笨蛋。",
  ui_story_5089_50891400_276_dialog_content = "欸……",
  ui_story_5089_50891400_277_dialog_content = "還有什麼需要幫忙的嗎？",
  ui_story_5089_50891400_278_dialog_content = "沒什麼了，接下來就剩下設定目的地。",
  ui_story_5089_50891400_279_dialog_content = "目的地……是之前發現的「幻想之地」，對吧？",
  ui_story_5089_50891400_280_dialog_content = "嗯。召喚著我，還有薇絲的記憶碎片飛過去的那道裂縫。",
  ui_story_5089_50891400_281_dialog_content = "經過彌加德、維多利亞、聖女大人等多方確認，另一頭還存在著某個世界。",
  ui_story_5089_50891400_282_dialog_content = "我聽說那裡簡直是暴走的N物質世界。",
  ui_story_5089_50891400_283_dialog_content = "是的，那是超級現實的世界。幾乎偵測不到代表了虛構的X物質。",
  ui_story_5089_50891400_284_dialog_content = "那裡很可能非常安全，但也充滿神祕。",
  ui_story_5089_50891400_285_dialog_content = "所以我不能讓其他人跟著我冒險。",
  ui_story_5089_50891400_286_dialog_content = "……不過，對……大家才不是「其他人」。",
  ui_story_5089_50891400_287_dialog_content = "咦，這麼說起來，為什麼那裡還叫作「幻想之地」呢？",
  ui_story_5089_50891400_288_dialog_content = "唔……最後的最後，伯利恆她是這麼說的——",
  ui_story_5089_50891400_289_dialog_content = "相比起我們的世界而言，那裡或許是現實的……",
  ui_story_5089_50891400_290_dialog_content = "但它與艾斯特拉卻有著奇妙的、無法斷離的聯繫。",
  ui_story_5089_50891400_291_dialog_content = "那最終導致薇絲的記憶流入其中，空裔想追尋的真相也在那裡頭。",
  ui_story_5089_50891400_292_dialog_content = "也許，在那現實中，存在著相應的虛構吧。",
  ui_story_5089_50891400_293_dialog_content = "這意味著，即便在「現實」的世界，人們還是會憑空想像美好的「幻夢」。",
  ui_story_5089_50891400_294_dialog_content = "「他們」向虛構所寄託的思念，最終導致了兩個世界的聯通。",
  ui_story_5089_50891400_295_dialog_content = "……但我們不是去終結那些幻想的。",
  ui_story_5089_50891400_296_dialog_content = "而且也不是非得去接受完全的「現實」啦。",
  ui_story_5089_50891400_297_dialog_content = "我們只是去踏上新的旅程，在未知中找到我們思念所牽扯的「美夢」。",
  ui_story_5089_50891400_298_dialog_content = "就算是在現實中做這些，我相信，總有一天也能做到。",
  ui_story_5089_50891400_299_dialog_content = "屆時，我們就再回來艾斯特拉吧！",
  ui_story_5089_50891400_300_dialog_content = "雖然對我來說，這種想法不是很懂啦。",
  ui_story_5089_50891400_301_dialog_content = "不過，我很高興大家還能再這樣一起踏上旅行。",
  ui_story_5089_50891400_302_dialog_content = "我也一樣。",
  ui_story_5089_50891400_303_dialog_content = "雖然我的台詞很少，但你們可別把我忘了。",
  ui_story_5089_50891400_304_dialog_content = "怎麼會呢？",
  ui_story_5089_50891400_305_dialog_content = "你可是我們好不容易才找回來的啊！",
  ui_story_5089_50891400_306_dialog_content = "那快設定座標吧。",
  ui_story_5089_50891400_307_dialog_content = "薇絲。",
  ui_story_5089_50891400_308_dialog_content = "卡蓮要一起彈嗎？",
  ui_story_5089_50891400_309_dialog_content = "我又不會……",
  ui_story_5089_50891400_310_dialog_content = "有什麼關係，最後的幻想就剩這麼點了啦。",
  ui_story_5089_50891400_311_dialog_content = "沒錯沒錯，只要把自己的情緒投入其中，我和薇絲會引導妳的。",
  ui_story_5089_50891400_312_dialog_content = "……我懂了。",
  ui_story_5089_50891400_313_dialog_content = "那麼……",
  ui_story_5089_50891400_314_dialog_content = "走吧！",
  ui_story_5089_50891400_315_dialog_content = "再見，艾斯特拉。",
  ui_story_5089_50891400_316_dialog_content = "再見，一起走過美好幻夢的大家。",
  ui_story_5089_50891400_317_dialog_content = "再見了。",
  ui_story_5089_50891400_318_dialog_content = "THE END",
  ui_story_5089_50891400_319_dialog_content = "感謝您的遊玩"
}
